def _research_retry_cooldown_active(
    state: Mapping[str, Any],
    policy_id: str,
) -> bool:
    """Return whether same-reboot research evidence still blocks a retry."""
    if (
        (
            policy_id == _SOURCE_RANKED_SANCTUARY_RECOVERY_POLICY.policy_id
            and _sanctuary_resource_revalidation_pending(state)
        )
        or _sanctuary_combat_only_transit_revalidation_pending(
            state,
            policy_id=policy_id,
        )
    ):
        return False
    result = _campaign_research_results(dict(state)).get(policy_id)
    if not (
        isinstance(result, Mapping)
        and result.get("boot_id") == state.get("world_boot_id")
        and result.get("completed_kill") is not True
    ):
        return False
    for key in (
        _RESEARCH_ABSENCE_COOLDOWN_KEY,
        _RESEARCH_CROWD_COOLDOWN_KEY,
    ):
        cooldowns = state.get(key) or {}
        try:
            if int(cooldowns.get(policy_id) or 0) > 0:
                return True
        except (AttributeError, TypeError, ValueError):
            continue
    return False


def _research_fatal_failure_active(
    state: Mapping[str, Any],
    policy_id: str,
) -> bool:
    """Keep a fatal live attempt blocked until level or reboot changes."""
    if (
        (
            policy_id == _SOURCE_RANKED_SANCTUARY_RECOVERY_POLICY.policy_id
            and _sanctuary_resource_revalidation_pending(state)
        )
        or _sanctuary_combat_only_transit_revalidation_pending(
            state,
            policy_id=policy_id,
        )
    ):
        return False
    result = _campaign_research_results(dict(state)).get(policy_id)
    return bool(
        isinstance(result, Mapping)
        and result.get("fatal_failure") is True
        and result.get("boot_id") == state.get("world_boot_id")
        and result.get("level") == _level(state)
        and result.get("completed_kill") is not True
    )


def _is_retryable_source_ranked_route_hazard(
    policy_id: str,
    route_hazard: Any,
) -> bool:
    """Recognize dynamic source-ranked hazards that may clear after reset."""
    return bool(
        (
            policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX)
            or policy_id
            in {
                _SOURCE_RANKED_SANCTUARY_RESERVE_POLICY.policy_id,
                _SOURCE_RANKED_SANCTUARY_RECOVERY_POLICY.policy_id,
            }
        )
        and isinstance(route_hazard, str)
        and (
            route_hazard in {
                "summon familiar was not positively confirmed",
                "familiar group ownership was not positively confirmed",
                "familiar preparation exceeded its confirmation deadline",
                "summon familiar exhausted three recitation attempts",
                "insufficient observed mana for summon familiar",
            }
            or route_hazard.startswith((
                _SOURCE_RANKED_LOCATOR_ROUTE_HAZARD_PREFIX,
                _SOURCE_RANKED_ADJACENT_SCAN_ROUTE_HAZARD_PREFIX,
                _SOURCE_RANKED_REQUIRED_LOOT_ROUTE_HAZARD_PREFIX,
                _SOURCE_RANKED_LOW_RESERVE_ROUTE_HAZARD_PREFIX,
                "field route watchdog stopped:",
                _SOURCE_RANKED_RUNTIME_BOUNDARY_ROUTE_HAZARD,
                _SOURCE_RANKED_RECALL_RECOVERY_ROUTE_HAZARD_PREFIX,
            ))
        )
    )


def _is_retryable_dynamic_route_hazard(
    policy_id: str,
    route_hazard: Any,
) -> bool:
    """Recognize route hazards that may clear without a reboot."""
    return bool(
        route_hazard == _DYNAMIC_FIELD_ROUTE_HAZARD_ABORT_REASON
        or _is_retryable_source_ranked_route_hazard(
            policy_id,
            route_hazard,
        )
    )


def _repair_retryable_dynamic_route_hazards(state: dict[str, Any]) -> dict[str, Any]:
    """Classify temporary failures without clearing their bounded retry evidence."""
    results = _campaign_research_results(state)
    migrated = dict(results)
    for policy_id, result in results.items():
        if (
            policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX)
            and isinstance(result, Mapping)
            and result.get("completed_kill") is not True
            and result.get("fatal_failure") is not True
            and result.get("consider_viable") is not False
            and result.get("retryable_failure") is not True
            and _is_retryable_dynamic_route_hazard(policy_id, result.get("route_hazard"))
        ):
            migrated[policy_id] = {**result, "retryable_failure": True}
    return {**state, "campaign_research_results": migrated} if migrated != results else state


def _campaign_has_shadow_grove_route_hazard(
    state: Mapping[str, Any],
) -> bool:
    """Return whether this reboot has blocked the shared Shadow Grove route."""
    boot_id = state.get("world_boot_id")
    if boot_id is None:
        return False
    marker = state.get(_SHADOW_GROVE_ROUTE_HAZARD_KEY)
    if isinstance(marker, Mapping) and marker.get("boot_id") == boot_id:
        return True
    last_policy_id = str(state.get("campaign_last_policy") or "")
    research_results = _campaign_research_results(dict(state))
    for policy_id, result in research_results.items():
        if not isinstance(result, Mapping) or result.get("boot_id") != boot_id:
            continue
        route_hazard = str(result.get("route_hazard") or "")
        if "shadow guardian" in route_hazard.casefold():
            return True
        if (
            policy_id in _SHADOW_GROVE_ROUTE_HAZARD_POLICY_IDS
            and route_hazard == _DYNAMIC_FIELD_ROUTE_HAZARD_ABORT_REASON
        ):
            # Older live checkpoints recorded the dynamic attacker only as a
            # generic no-combat abort. The policy identity still proves which
            # shared route was crossed, so preserve that evidence.
            return True
    if last_policy_id not in _SHADOW_GROVE_ROUTE_HAZARD_POLICY_IDS:
        return False
    route_hazards = state.get("campaign_fastwalk_route_hazards") or ()
    if isinstance(route_hazards, (list, tuple, set, frozenset)) and any(
        _SHADOW_GROVE_ROUTE_PREFLIGHT_TARGET in str(hazard).casefold()
        for hazard in route_hazards
    ):
        return True
    return (
        str(state.get("campaign_fastwalk_abort_reason") or "")
        == _DYNAMIC_FIELD_ROUTE_HAZARD_ABORT_REASON
    )


def _legacy_fastwalk_training_route_hazard(
    state: Mapping[str, Any],
) -> bool:
    """Recognize the pre-marker checkpoint that retraced Dorrik's route."""
    if state.get("campaign_fastwalk_training_complete") is not False:
        return False
    if str(state.get("room_vnum") or "") != "3054":
        return False
    route_hazards = state.get("campaign_fastwalk_route_hazards") or ()
    if not isinstance(route_hazards, (list, tuple, set, frozenset)):
        return False
    if not any(
        str(hazard).startswith("transit below-band attacker:")
        for hazard in route_hazards
    ):
        return False
    return str(state.get("campaign_fastwalk_abort_reason") or "").startswith(
        _FASTWALK_TRAINING_ROUTE_HAZARD_ABORT_PREFIX
    )


def _fastwalk_training_route_hazard_marker(
    state: Mapping[str, Any],
) -> dict[str, Any]:
    """Build the reboot-and-level-scoped record for a deferred trainer trip."""
    return {
        "boot_id": state.get("world_boot_id"),
        "level": _level(dict(state)),
        "reason": (
            "defer class-aware training after a source-known transit attacker "
            "interrupted the distant trainer route"
        ),
        "route_hazards": [
            str(hazard)
            for hazard in (state.get("campaign_fastwalk_route_hazards") or ())
        ],
    }


def _campaign_fastwalk_training_deferred_after_route_hazard(
    state: Mapping[str, Any],
) -> bool:
    """Return whether same-level training should wait for a safer route."""
    marker = state.get(_FASTWALK_TRAINING_ROUTE_HAZARD_KEY)
    if isinstance(marker, Mapping):
        boot_id = state.get("world_boot_id")
        try:
            marker_level = int(marker.get("level"))
        except (TypeError, ValueError):
            marker_level = -1
        return bool(
            boot_id
            and marker.get("boot_id") == boot_id
            and marker_level == _level(dict(state))
        )
    return _legacy_fastwalk_training_route_hazard(state)


def _source_ranked_candidate_uses_shadow_grove_route(
    candidate: HuntCandidate,
) -> bool:
    """Identify generated candidates whose route preflight crosses room 1300."""
    route_target = str(candidate.route_preflight_target or "").casefold()
    if _SHADOW_GROVE_ROUTE_PREFLIGHT_TARGET in route_target:
        return True
    return any(
        _SHADOW_GROVE_ROUTE_PREFLIGHT_TARGET in str(target).casefold()
        for target in candidate.route_hard_hazard_targets
    )


def _state_uses_shadow_grove_route(state: Mapping[str, Any]) -> bool:
    """Identify a saved fixed or generated route that crosses Shadow Grove."""
    policy_id = str(state.get("campaign_last_policy") or "")
    if policy_id in _SHADOW_GROVE_ROUTE_HAZARD_POLICY_IDS:
        return True
    candidate = state.get(_SOURCE_RANKED_CANDIDATE_KEY)
    if not isinstance(candidate, Mapping):
        return False
    route_target = str(candidate.get("route_preflight_target") or "").casefold()
    if _SHADOW_GROVE_ROUTE_PREFLIGHT_TARGET in route_target:
        return True
    return any(
        _SHADOW_GROVE_ROUTE_PREFLIGHT_TARGET in str(target).casefold()
        for target in (candidate.get("route_hard_hazard_targets") or ())
    )


def _shadow_grove_route_hazard_observed(
    policy_id: str,
    state: Mapping[str, Any],
    route_hazard: str,
) -> bool:
    """Return whether one live result proves the shared route is unsafe."""
    normalized_hazard = route_hazard.casefold()
    return bool(
        "shadow guardian" in normalized_hazard
        or (
            policy_id in _SHADOW_GROVE_ROUTE_HAZARD_POLICY_IDS
            and route_hazard == _DYNAMIC_FIELD_ROUTE_HAZARD_ABORT_REASON
        )
        or (
            _state_uses_shadow_grove_route(state)
            and route_hazard == _DYNAMIC_FIELD_ROUTE_HAZARD_ABORT_REASON
        )
    )


def _repair_shadow_grove_route_hazard(
    state: Mapping[str, Any],
    segments: Collection[Mapping[str, Any]],
) -> dict[str, Any]:
    """Rebuild a lost Shadow Grove quarantine from durable segment evidence."""
    boot_id = state.get("world_boot_id")
    if boot_id is None:
        return dict(state)
    existing = state.get(_SHADOW_GROVE_ROUTE_HAZARD_KEY)
    if isinstance(existing, Mapping) and existing.get("boot_id") == boot_id:
        return dict(state)

    evidence: dict[str, Any] | None = None
    normalized_segments: list[Mapping[str, Any]] = []
    for raw_segment in segments:
        if isinstance(raw_segment, Mapping):
            normalized_segments.append(raw_segment)
            continue
        try:
            normalized_segments.append(
                {key: raw_segment[key] for key in raw_segment.keys()}
            )
        except (AttributeError, KeyError, TypeError):
            continue
    ordered_segments = sorted(
        normalized_segments,
        key=lambda segment: int(segment.get("sequence") or 0),
        reverse=True,
    )
    for segment in ordered_segments:
        phase = str(segment.get("phase") or "")
        for state_field in ("end_state_json", "start_state_json"):
            raw_state = segment.get(state_field)
            try:
                segment_state = json.loads(raw_state or "{}")
            except (TypeError, json.JSONDecodeError):
                continue
            if not isinstance(segment_state, Mapping):
                continue
            if segment_state.get("world_boot_id") != boot_id:
                continue
            route_hazard = str(
                segment_state.get("campaign_fastwalk_abort_reason") or ""
            )
            result = _campaign_research_results(dict(segment_state)).get(phase)
            if isinstance(result, Mapping) and result.get("route_hazard"):
                route_hazard = str(result["route_hazard"])
            if not route_hazard:
                continue
            if not _shadow_grove_route_hazard_observed(
                phase,
                segment_state,
                route_hazard,
            ):
                continue
            evidence = {
                "boot_id": boot_id,
                "policy_id": phase,
                "route_hazard": route_hazard,
                "source": "campaign_segment_history",
            }
            break
        if evidence is not None:
            break
    if evidence is None:
        if isinstance(existing, Mapping):
            repaired = dict(state)
            repaired.pop(_SHADOW_GROVE_ROUTE_HAZARD_KEY, None)
            return repaired
        return dict(state)

    repaired = dict(state)
    repaired[_SHADOW_GROVE_ROUTE_HAZARD_KEY] = evidence
    policy_id = str(evidence.get("policy_id") or "")
    results = _campaign_research_results(repaired)
    if policy_id and policy_id not in results:
        results[policy_id] = {
            "observed": False,
            "viable": False,
            "route_hazard": evidence["route_hazard"],
            "boot_id": boot_id,
        }
        repaired["campaign_research_results"] = results
    return repaired


def _is_capability_blocked_source_ranked_route_hazard(
    policy_id: str,
    route_hazard: Any,
) -> bool:
    """Recognize a route blocked by an unowned movement capability."""
    return bool(
        policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX)
        and isinstance(route_hazard, str)
        and route_hazard.startswith("field route movement blocked:")
    )


_BARDOOSH_ROUTE_FIX_RETRY_REASON = (
    "policy revision corrected the Bardoosh final route from south to west"
)
_BARDOOSH_IDENTITY_FIX_RETRY_REASON = (
    "policy revision bound Bardoosh's generic live line to his source identity"
)
_NOBLEMAN_ROUTE_FIX_RETRY_REASON = (
    "policy revision removed the redundant nobleman destination hop"
)
_NOBLEMAN_IDENTITY_FIX_RETRY_REASON = (
    "policy revision aligned the nobleman stop with its source identity"
)
_DWARVEN_WORKERS_SEARCH_FIX_RETRY_REASON = (
    "policy revision bound the worker survey to its exact source room line"
)
_MAHNTOR_ROUTE_ABORT_PREFIX = "field route could not find GMCP exit to room "
_ANSI_ESCAPE = re.compile(r"\x1b(?:[@-Z\\-_]|\[[0-?]*[ -/]*[@-~])")
_RECOVER_BASIC_BODY_REQUIRED_FREE_WEIGHT = 7
_RECOVER_SCHOOL_WRIST_FLOAT_REQUIRED_FREE_WEIGHT = 30
_RECOVER_GREMLIN_WAIST_REQUIRED_FREE_WEIGHT = 5
_RECOVER_DAYCARE_RING_REQUIRED_FREE_WEIGHT = 21
_DAYCARE_RING_ATTEMPT_BOOT_KEY = "campaign_daycare_ring_attempted_boot_id"
_DAYCARE_RING_COOLDOWN_KEY = "campaign_daycare_ring_cooldown"
_DAYCARE_RING_COOLDOWN_SEGMENTS = 3
