def _source_ranked_watchdog_failure_state(
    state: Mapping[str, Any],
    *,
    policy_id: str,
    error: str,
) -> dict[str, Any]:
    """Quarantine a source route that repeated a movement cycle without progress."""
    updated = dict(state)
    updated.pop(_SOURCE_RANKED_CANDIDATE_KEY, None)
    route_hazard = f"field route watchdog stopped: {error}"
    updated.update(
        {
            "campaign_fastwalk_abort_reason": route_hazard,
            "campaign_fastwalk_target_absent": False,
            "campaign_fastwalk_target_present_observed": False,
            "campaign_fastwalk_crowded": False,
            "campaign_fastwalk_consider_outcomes": {},
            _SOURCE_CONSIDER_OUTCOMES_KEY: {},
            _SOURCE_BELOW_BAND_SIGHTINGS_KEY: [],
            _SOURCE_ABSENT_SIGHTINGS_KEY: [],
            _SOURCE_PRESENT_SIGHTINGS_KEY: [],
            "campaign_objective_kills": [],
            "campaign_completed_kills": [],
            "campaign_last_policy": policy_id,
            "campaign_policy_revision": _CAMPAIGN_POLICY_REVISION,
        }
    )
    results = _campaign_research_results(state)
    results[policy_id] = {
        "observed": False,
        "viable": False,
        "route_hazard": route_hazard,
        "retryable_failure": True,
        "boot_id": updated.get("world_boot_id"),
    }
    updated["campaign_research_results"] = results
    retry_cooldown = _research_absence_retry_cooldown(
        policy_id,
        default=_DEFAULT_RESEARCH_CROWD_COOLDOWN,
    )
    if retry_cooldown is not None:
        absence_cooldowns = dict(
            state.get(_RESEARCH_ABSENCE_COOLDOWN_KEY) or {}
        )
        absence_cooldowns[policy_id] = retry_cooldown
        updated[_RESEARCH_ABSENCE_COOLDOWN_KEY] = absence_cooldowns
    return updated


def _maintenance_route_watchdog_failure_state(
    state: Mapping[str, Any],
    *,
    policy_id: str,
    execution: str,
    boot_id: str | int | None,
    error: str,
) -> dict[str, Any]:
    """Quarantine an optional maintenance route without failing the campaign."""
    updated = _maintenance_failure_state(
        dict(state),
        execution=execution,
        boot_id=boot_id,
        error=error,
    )
    route_hazard = f"field route watchdog stopped: {error}"
    updated.update(
        {
            "campaign_fastwalk_abort_reason": route_hazard,
            "campaign_fastwalk_target_absent": False,
            "campaign_fastwalk_target_present_observed": False,
            "campaign_fastwalk_crowded": False,
            "campaign_fastwalk_consider_outcomes": {},
            _SOURCE_CONSIDER_OUTCOMES_KEY: {},
            _SOURCE_BELOW_BAND_SIGHTINGS_KEY: [],
            _SOURCE_ABSENT_SIGHTINGS_KEY: [],
            _SOURCE_PRESENT_SIGHTINGS_KEY: [],
            "campaign_objective_kills": [],
            "campaign_completed_kills": [],
        }
    )
    hazards = dict(updated.get(_MAINTENANCE_ROUTE_HAZARDS_KEY) or {})
    previous_hazard = hazards.get(policy_id)
    hazard_record = {
        "boot_id": updated.get("world_boot_id") or boot_id,
        "route_hazard": route_hazard,
        "retryable_failure": True,
    }
    candidate_keys = []
    if (
        isinstance(previous_hazard, Mapping)
        and previous_hazard.get("boot_id") == hazard_record["boot_id"]
    ):
        candidate_keys.extend(
            str(value)
            for value in (previous_hazard.get("candidate_keys") or [])
            if value is not None
        )
        if previous_hazard.get("candidate_key") is not None:
            candidate_keys.append(str(previous_hazard["candidate_key"]))
    if execution == "provision-funding":
        attempt = updated.get(_PROVISION_FUNDING_LAST_ATTEMPT_KEY)
        if (
            isinstance(attempt, Mapping)
            and attempt.get("candidate_key") is not None
            and attempt.get("boot_id") == hazard_record["boot_id"]
        ):
            candidate_keys.append(str(attempt["candidate_key"]))
    candidate_keys = list(dict.fromkeys(candidate_keys))
    if candidate_keys:
        hazard_record["candidate_keys"] = candidate_keys
    hazards[policy_id] = hazard_record
    updated[_MAINTENANCE_ROUTE_HAZARDS_KEY] = hazards
    if execution == "upgrade-piercing-weapon":
        updated[_PIERCING_WEAPON_UPGRADE_COOLDOWN_KEY] = max(
            int(updated.get(_PIERCING_WEAPON_UPGRADE_COOLDOWN_KEY) or 0),
            _PIERCING_WEAPON_UPGRADE_COOLDOWN_SEGMENTS,
        )
        if boot_id is not None:
            updated[_PIERCING_WEAPON_UPGRADE_BOOT_KEY] = boot_id
        if policy_id == "thalos-long-dagger-upgrade-10-29":
            updated[_INTERMEDIATE_PIERCING_WEAPON_UPGRADE_COOLDOWN_KEY] = max(
                int(
                    updated.get(
                        _INTERMEDIATE_PIERCING_WEAPON_UPGRADE_COOLDOWN_KEY
                    )
                    or 0
                ),
                _INTERMEDIATE_PIERCING_WEAPON_UPGRADE_COOLDOWN_SEGMENTS,
            )
    return updated


def _reconcile_maintenance_fastwalk_state(
    previous: Mapping[str, Any],
    current: Mapping[str, Any],
    *,
    execution: str,
    policy_id: str,
    boot_id: str | int | None,
    fresh_observation: bool = True,
) -> dict[str, Any]:
    """Keep maintenance route observations out of the field-policy ledger."""
    if execution not in _MAINTENANCE_EXECUTIONS:
        return dict(current)

    updated = dict(current)
    provision_target_absent = (
        execution == "provision-funding"
        and current.get("campaign_fastwalk_target_absent") is True
        and current.get("campaign_fastwalk_target_present_observed") is not True
    )
    abort_reason = str(updated.get("campaign_fastwalk_abort_reason") or "")
    previous_abort_reason = str(
        previous.get("campaign_fastwalk_abort_reason") or ""
    )
    existing_hazard = (
        (updated.get(_MAINTENANCE_ROUTE_HAZARDS_KEY) or {}).get(policy_id)
        if isinstance(updated.get(_MAINTENANCE_ROUTE_HAZARDS_KEY), Mapping)
        else None
    )
    attempt = updated.get(_PROVISION_FUNDING_LAST_ATTEMPT_KEY)
    candidate_key = (
        str(attempt.get("candidate_key"))
        if (
            execution == "provision-funding"
            and isinstance(attempt, Mapping)
            and attempt.get("candidate_key") is not None
            and attempt.get("boot_id") == (updated.get("world_boot_id") or boot_id)
        )
        else None
    )
    same_hazard_candidate = (
        isinstance(existing_hazard, Mapping)
        and candidate_key is not None
        and candidate_key
        in {
            str(value)
            for value in (existing_hazard.get("candidate_keys") or [])
            if value is not None
        }
        or (
            isinstance(existing_hazard, Mapping)
            and candidate_key is not None
            and str(existing_hazard.get("candidate_key") or "") == candidate_key
        )
    )
    if fresh_observation and abort_reason and (
        abort_reason != previous_abort_reason
        or (
            execution == "provision-funding"
            and candidate_key is not None
            and not same_hazard_candidate
        )
    ):
        hazards = dict(updated.get(_MAINTENANCE_ROUTE_HAZARDS_KEY) or {})
        previous_hazard = hazards.get(policy_id)
        hazard_record = {
            "boot_id": updated.get("world_boot_id") or boot_id,
            "route_hazard": abort_reason,
            "retryable_failure": True,
        }
        if (
            isinstance(previous_hazard, Mapping)
            and previous_hazard.get("boot_id") == hazard_record["boot_id"]
        ):
            candidate_keys = [
                str(value)
                for value in (previous_hazard.get("candidate_keys") or [])
                if value is not None
            ]
            if previous_hazard.get("candidate_key") is not None:
                candidate_keys.append(str(previous_hazard["candidate_key"]))
            candidate_keys = list(dict.fromkeys(candidate_keys))
        else:
            candidate_keys = []
        if candidate_key is not None and candidate_key not in candidate_keys:
            candidate_keys.append(candidate_key)
        if candidate_keys:
            hazard_record["candidate_keys"] = candidate_keys
        hazards[policy_id] = hazard_record
        updated[_MAINTENANCE_ROUTE_HAZARDS_KEY] = hazards

    # A maintenance trip can use the same fastwalk machinery as a hunt. Its
    # transient observations must not replace the last field policy's evidence
    # or make a safe healer checkpoint look like an unfinished hunt.
    fastwalk_keys = (
        "campaign_fastwalk_abort_reason",
        "campaign_fastwalk_target_absent",
        "campaign_fastwalk_target_present_observed",
        "campaign_fastwalk_crowded",
        "campaign_fastwalk_consider_outcomes",
        _SOURCE_CONSIDER_OUTCOMES_KEY,
        _SOURCE_BELOW_BAND_SIGHTINGS_KEY,
        _SOURCE_ABSENT_SIGHTINGS_KEY,
        _SOURCE_PRESENT_SIGHTINGS_KEY,
        "campaign_fastwalk_below_band_targets",
        "campaign_fastwalk_route_hazards",
        "campaign_fastwalk_route_preflight_hazard_observed",
        "campaign_fastwalk_target_vnum_mismatch",
        "campaign_fastwalk_unattackable_target",
    )
    for key in fastwalk_keys:
        if provision_target_absent and key in {
            "campaign_fastwalk_target_absent",
            "campaign_fastwalk_target_present_observed",
            "campaign_fastwalk_consider_outcomes",
            _SOURCE_CONSIDER_OUTCOMES_KEY,
            _SOURCE_BELOW_BAND_SIGHTINGS_KEY,
            _SOURCE_ABSENT_SIGHTINGS_KEY,
            _SOURCE_PRESENT_SIGHTINGS_KEY,
            "campaign_fastwalk_below_band_targets",
            "campaign_fastwalk_target_vnum_mismatch",
            "campaign_fastwalk_unattackable_target",
        }:
            # Funding routes have an explicit endpoint check. Keep that
            # current absence evidence instead of restoring a previous field
            # hunt's target-present flag into the funding checkpoint.
            continue
        if key in previous:
            if key == "campaign_fastwalk_abort_reason":
                previous_reason = str(previous[key] or "")
                field_policy = str(previous.get("campaign_last_policy") or "")
                field_result = _campaign_research_results(previous).get(
                    field_policy
                )
                owns_abort = any(
                    previous_reason.startswith(prefix)
                    for prefix in (
                        *_FIELD_CROWD_ABORT_PREFIXES,
                        *_FIELD_ROUTE_HAZARD_ABORT_PREFIXES,
                    )
                ) or (
                    isinstance(field_result, Mapping)
                    and field_result.get("route_hazard") == previous_reason
                )
                if not owns_abort:
                    updated.pop(key, None)
                    continue
            elif key == "campaign_fastwalk_target_absent" and previous[key]:
                field_policy = str(previous.get("campaign_last_policy") or "")
                field_result = _campaign_research_results(previous).get(
                    field_policy
                )
                if not (
                    isinstance(field_result, Mapping)
                    and (
                        field_result.get("absent") is True
                        or field_result.get("verified_empty") is True
                    )
                ):
                    updated.pop(key, None)
                    continue
            updated[key] = previous[key]
        else:
            updated.pop(key, None)
    return updated


def _is_source_ranked_endpoint_failure(error: Any) -> bool:
    """Recognize the fastwalk boundary that must rotate instead of failing."""
    return "returned without observing its endpoint" in str(error or "")


def _is_source_ranked_recall_recovery_failure(error: Any) -> bool:
    """Recognize a source-route recall failure that must rotate safely."""
    return "recall recovery did not reach Midgaard from room " in str(
        error or ""
    )


def _is_source_ranked_watchdog_failure(error: Any) -> bool:
    """Recognize a source-route progress watchdog that must rotate safely."""
    text = str(error or "")
    legacy_command_budget = (
        "Starter bot exceeded" in text and "command budget" in text
    )
    return (
        (
            "progress watchdog stopped after repeating" in text
            or "source route command budget" in text
            or legacy_command_budget
        )
        and (
            "route cycle" in text
            or "no policy decision" in text
            or "repeating 'look'" in text
            or "source route command budget" in text
            or legacy_command_budget
        )
    )


def _is_source_ranked_timeout_failure(error: Any) -> bool:
    """Recognize the bounded outer runner cap as a route rotation signal."""
    text = str(error or "")
    return bool(
        (
            "campaign runner exceeded" in text
            and "outer cleanup grace" in text
        )
        or re.fullmatch(
            r"Starter bot exceeded [0-9]+(?:\.[0-9]+)? second runtime",
            text,
        )
        or (
            "startup boundary stopped" in text
            and "source route" in text
        )
        or "duplicate timed-out source route" in text
    )


def _is_retryable_city_shop_route_failure(
    execution: str,
    error: Any,
) -> bool:
    """Recognize a temporary healer-origin shop route hazard."""
    return (
        execution == "sell-loot"
        and "loot liquidation route remained blocked by the source-backed "
        "Midgaard drunk"
        in str(error or "")
    )


def _run_terminal_state(
    storage: RunStorage,
    run_id: int,
) -> dict[str, Any] | None:
    """Return the latest structured runner completion boundary."""
    return _run_state_boundary(storage, run_id, states=("completed", "runtime_cap"))


def _run_failed_terminal_state(
    storage: RunStorage,
    run_id: int,
) -> dict[str, Any] | None:
    """Return the last structured failure boundary emitted by a live run."""
    return _run_state_boundary(storage, run_id, states=("failed",))


def _run_state_boundary(
    storage: RunStorage, run_id: int, *, states: tuple[str, ...],
) -> dict[str, Any] | None:
    loader = getattr(storage, "get_latest_run_state_event", None)
    if callable(loader):
        event = loader(run_id, states=states)
        return json.loads(event["payload_json"]) if event is not None else None
    # Lightweight replay stores retain the chronological event-list interface.
    for event in reversed(storage.list_events(run_id)):
        if event["kind"] != "state":
            continue
        payload = json.loads(event["payload_json"])
        if payload.get("state") in states:
            return payload
    return None


_CONNECTION_TRANSIENT_FASTWALK_KEYS = (
    "campaign_fastwalk_target_absent",
    "campaign_fastwalk_target_present_observed",
    "campaign_fastwalk_crowded",
    "campaign_fastwalk_consider_outcomes",
    _SOURCE_CONSIDER_OUTCOMES_KEY,
    _SOURCE_BELOW_BAND_SIGHTINGS_KEY,
    _SOURCE_ABSENT_SIGHTINGS_KEY,
    _SOURCE_PRESENT_SIGHTINGS_KEY,
    "campaign_fastwalk_below_band_targets",
    "campaign_fastwalk_route_hazards",
    "campaign_fastwalk_route_preflight_hazard_observed",
    "campaign_fastwalk_route_preflight_inconclusive",
    "campaign_fastwalk_route_preflight_locations",
    "campaign_fastwalk_route_preflight_retry_attempts",
    "campaign_fastwalk_target_vnum_mismatch",
    "campaign_fastwalk_unattackable_target",
    "campaign_fastwalk_where_relocation_attempts",
)


def _is_connection_recovery_failure(error: Any) -> bool:
    """Recognize bounded socket failures that require a safe homeward retry."""
    text = str(error or "").casefold()
    return any(marker in text for marker in _CONNECTION_RECOVERY_ERROR_MARKERS)


def _mark_connection_loss_checkpoint(state: Mapping[str, Any]) -> dict[str, Any]:
    """Preserve an explicit homeward handoff after a live socket failure."""
    repaired = dict(state)
    repaired[
        "campaign_fastwalk_abort_reason"
    ] = _CONNECTION_LOSS_FASTWALK_ABORT_REASON
    for key in _CONNECTION_TRANSIENT_FASTWALK_KEYS:
        repaired.pop(key, None)
    return repaired


def _complete_connection_loss_recovery(
    state: Mapping[str, Any], observed: Mapping[str, Any], *, execution: str, succeeded: bool,
) -> dict[str, Any]:
    """Close only a completed transport handoff, after maintenance reconciliation."""
    updated = dict(state)
    if (
        execution != "return-home" or not succeeded
        or state.get("campaign_fastwalk_abort_reason") != _CONNECTION_LOSS_FASTWALK_ABORT_REASON
        or str(observed.get("room_vnum") or "") != "3054"
        or observed.get("dead") or _numeric_progress(dict(observed), "hp") <= 0
        or "enemies" not in observed or not _enemy_snapshot_empty(observed.get("enemies"))
        or observed.get("position") not in {4, 5, 6, 7}
        or observed.get("campaign_fastwalk_abort_reason")
    ):
        return updated
    updated.pop("campaign_fastwalk_abort_reason", None)
    return updated


def _campaign_failure_state_from_run(
    storage: RunStorage,
    run_id: int | None,
    state: dict[str, Any],
    *,
    character_name: str,
) -> dict[str, Any]:
    """Merge live snapshots and terminal policy facts into a failed segment."""
    if run_id is None:
        return dict(state)
    live_state = (
        storage.get_latest_character_state(character_name)
        or _run_latest_state(storage, run_id)
        or state
    )
    merged = {**state, **live_state}
    terminal = _run_failed_terminal_state(storage, run_id)
    if terminal is not None:
        # Character snapshots carry vitals, room, inventory, and progress;
        # the terminal boundary carries policy-owned observations that are
        # intentionally not part of CharacterState.
        for key, value in terminal.items():
            if key.startswith("campaign_") or key in {
                "magic_shop_route_blocked_by_drunk",
                "city_shop_route_wait_attempts",
            }:
                merged[key] = value
        terminal_abort_reason = terminal.get("fastwalk_abort_reason")
        if (
            isinstance(terminal_abort_reason, str)
            and terminal_abort_reason.startswith(
                "field route interrupted by connection loss"
            )
        ):
            merged = _mark_connection_loss_checkpoint(merged)
    return merged


def _source_ranked_policy_ids_from_fastwalk_state(
    state: Mapping[str, Any],
) -> tuple[str, ...]:
    """Extract source-hunt identities from one live fastwalk boundary."""
    policy_ids: set[str] = set()
    for key in (
        _SOURCE_CONSIDER_OUTCOMES_KEY,
        "fastwalk_source_consider_outcomes",
    ):
        outcomes = state.get(key)
        if isinstance(outcomes, Mapping):
            policy_ids.update(
                str(policy_id)
                for policy_id in outcomes
                if str(policy_id).startswith(_SOURCE_RANKED_POLICY_PREFIX)
            )
    for key in (
        _SOURCE_BELOW_BAND_SIGHTINGS_KEY,
        _SOURCE_ABSENT_SIGHTINGS_KEY,
        _SOURCE_PRESENT_SIGHTINGS_KEY,
        "fastwalk_source_below_band_sightings",
        "fastwalk_source_absent_sightings",
        "fastwalk_source_present_sightings",
    ):
        sightings = state.get(key)
        if not isinstance(sightings, (list, tuple, set, frozenset)):
            continue
        policy_ids.update(
            str(record["policy_id"])
            for record in sightings
            if isinstance(record, Mapping)
            and record.get("policy_id") is not None
            and str(record["policy_id"]).startswith(
                _SOURCE_RANKED_POLICY_PREFIX
            )
        )
    return tuple(sorted(policy_ids))


def _advance_retry_cooldown(
    state: dict[str, Any],
    *,
    key: str,
    execution: str,
    xp_delta: int,
) -> dict[str, Any]:
    """Advance an optional-loot retry only after productive field work."""
    if execution in _MAINTENANCE_EXECUTIONS or xp_delta <= 0:
        return state
    remaining = int(state.get(key) or 0)
    if remaining <= 0:
        return state
    updated = dict(state)
    updated[key] = remaining - 1
    return updated


def _advance_city_shop_route_cooldown(
    state: dict[str, Any],
    *,
    execution: str,
    xp_delta: int = 0,
) -> dict[str, Any]:
    """Age a temporary city-shop hazard after an independent segment."""
    if execution in _MAINTENANCE_EXECUTIONS and xp_delta <= 0:
        return state
    remaining = int(state.get(_CITY_SHOP_ROUTE_COOLDOWN_KEY) or 0)
    if remaining <= 0:
        return state
    updated = dict(state)
    remaining -= 1
    if remaining > 0:
        updated[_CITY_SHOP_ROUTE_COOLDOWN_KEY] = remaining
        return updated
    updated.pop(_CITY_SHOP_ROUTE_COOLDOWN_KEY, None)
    updated.pop(_MAGIC_SHOP_ROUTE_BLOCKED_KEY, None)
    updated.pop(_MAGIC_SHOP_ROUTE_BLOCKED_BOOT_KEY, None)
    return updated


def _advance_daycare_ring_cooldown(
    state: dict[str, Any],
    *,
    execution: str,
    xp_delta: int,
) -> dict[str, Any]:
    """Retry missing Daycare rings after other productive work."""
    return _advance_retry_cooldown(
        state,
        key=_DAYCARE_RING_COOLDOWN_KEY,
        execution=execution,
        xp_delta=xp_delta,
    )


def _daycare_ring_below_band_observed(state: Mapping[str, Any]) -> bool:
    """Return whether the ring route has direct live below-band evidence."""
    return any(
        state.get(key)
        for key in (
            "campaign_fastwalk_below_band_targets",
            "campaign_fastwalk_below_band_sightings",
            _SOURCE_BELOW_BAND_SIGHTINGS_KEY,
        )
    )


def _clear_daycare_ring_field_metadata(
    state: dict[str, Any],
) -> dict[str, Any]:
    """Keep optional ring retries from contaminating the active XP policy."""
    updated = dict(state)
    for key in (
        "campaign_fastwalk_target_absent",
        "campaign_fastwalk_target_present_observed",
        "campaign_fastwalk_crowded",
        "campaign_fastwalk_abort_reason",
        "campaign_fastwalk_consider_outcomes",
        _SOURCE_CONSIDER_OUTCOMES_KEY,
        _SOURCE_BELOW_BAND_SIGHTINGS_KEY,
        _SOURCE_ABSENT_SIGHTINGS_KEY,
        _SOURCE_PRESENT_SIGHTINGS_KEY,
        "campaign_fastwalk_unattackable_target",
        "campaign_fastwalk_target_vnum_mismatch",
    ):
        updated.pop(key, None)

    results = _campaign_research_results(updated)
    results.pop("recover-daycare-ring", None)
    if results:
        updated["campaign_research_results"] = results
    else:
        updated.pop("campaign_research_results", None)

    exclusions = dict(updated.get(_BELOW_BAND_POLICY_EXCLUSIONS_KEY) or {})
    exclusions.pop("recover-daycare-ring", None)
    if exclusions:
        updated[_BELOW_BAND_POLICY_EXCLUSIONS_KEY] = exclusions
    else:
        updated.pop(_BELOW_BAND_POLICY_EXCLUSIONS_KEY, None)

    for key in (
        _RESEARCH_ABSENCE_COOLDOWN_KEY,
        _RESEARCH_CROWD_COOLDOWN_KEY,
        _SOURCE_RANKED_CROWD_ATTEMPTS_KEY,
    ):
        records = dict(updated.get(key) or {})
        records.pop("recover-daycare-ring", None)
        if records:
            updated[key] = records
        else:
            updated.pop(key, None)

    cleared = {
        str(policy_id)
        for policy_id in updated.get(_CLEARED_RESEARCH_POLICIES_KEY, ())
    }
    cleared.discard("recover-daycare-ring")
    if cleared:
        updated[_CLEARED_RESEARCH_POLICIES_KEY] = sorted(cleared)
    else:
        updated.pop(_CLEARED_RESEARCH_POLICIES_KEY, None)
    return updated


