def _reconcile_city_shop_route_probe(
    previous: dict[str, Any],
    current: dict[str, Any],
    observed: dict[str, Any],
    *,
    run_id: int,
) -> dict[str, Any]:
    """A fresh locator can supersede a wandering hazard, never purchase failure."""
    probe = observed.get("campaign_city_shop_route_probe")
    if not isinstance(probe, Mapping):
        return current
    updated = dict(current)
    updated["campaign_city_shop_route_probe"] = {**probe, "run_id": run_id}
    locations = probe.get("locations")
    routes = probe.get("route_rooms")
    if not (
        previous.get(_MAGIC_SHOP_ROUTE_BLOCKED_KEY)
        and previous.get("magic_shop_purchase_failed") is False
        and probe.get("complete") is True and probe.get("clear") is True
        and probe.get("room_vnum") == observed.get("room_vnum") == "3054"
        and probe.get("boot_id")
        == observed.get("world_boot_id") == previous.get("world_boot_id")
        and probe.get("boot_id")
        and isinstance(locations, list) and locations
        and isinstance(routes, list) and routes
        and all(isinstance(location, str) and location.strip()
                and _normalise_room_label(location) not in routes
                for location in locations)
    ):
        return updated
    for key in (_MAGIC_SHOP_ROUTE_BLOCKED_KEY, _MAGIC_SHOP_ROUTE_BLOCKED_BOOT_KEY,
                _CITY_SHOP_ROUTE_COOLDOWN_KEY, _FLIGHT_PURCHASE_COOLDOWN_KEY):
        updated.pop(key, None)
    updated["campaign_city_shop_route_probe"]["released_route_cooldown"] = True
    return updated


def _advance_flight_purchase_cooldown(
    state: dict[str, Any],
    *,
    execution: str,
    xp_delta: int,
) -> dict[str, Any]:
    """Retry an optional flight purchase after productive field work."""
    # Provisioning remains maintenance for policy selection, but a funding
    # kill is still productive field work and must be able to age a blocked
    # shop retry.  Without this exception, a blocked shop plus a positive
    # cooldown creates a liveness deadlock because funding cannot advance the
    # counter and the shop cannot be retried.
    cooldown_execution = (
        "provision-funding-progress"
        if execution == "provision-funding" and xp_delta > 0
        else execution
    )
    advanced = _advance_retry_cooldown(
        state,
        key=_FLIGHT_PURCHASE_COOLDOWN_KEY,
        execution=cooldown_execution,
        xp_delta=xp_delta,
    )
    city_shop_route_cooldown = int(
        advanced.get(_CITY_SHOP_ROUTE_COOLDOWN_KEY) or 0
    )
    has_flight = any(
        _state_has_active_affect(advanced.get("affects"), effect)
        for effect in ("fly", "levitation")
    )
    if not has_flight and not (
        advanced.get(_MAGIC_SHOP_ROUTE_BLOCKED_KEY)
        and int(advanced.get(_FLIGHT_PURCHASE_COOLDOWN_KEY) or 0) <= 0
        and city_shop_route_cooldown <= 0
    ):
        return advanced
    updated = dict(advanced)
    updated.pop(_MAGIC_SHOP_ROUTE_BLOCKED_KEY, None)
    updated.pop(_MAGIC_SHOP_ROUTE_BLOCKED_BOOT_KEY, None)
    if has_flight:
        updated.pop(_FLIGHT_PURCHASE_COOLDOWN_KEY, None)
    return updated


def _xp_delta(before: dict[str, Any], after: dict[str, Any]) -> int:
    """Treat a level gain as progress even when DD4 resets cumulative XP."""
    level_delta = _level(after) - _level(before)
    if level_delta > 0:
        return max(1, level_delta)
    return _numeric_progress(after, "xp") - _numeric_progress(before, "xp")


def _xp_loss_total(state: Mapping[str, Any]) -> int | None:
    """Return a durable XP-loss counter when the state exposes one."""
    for key in ("xp_loss_total", "campaign_xp_loss_total"):
        raw_value = state.get(key)
        if isinstance(raw_value, bool) or raw_value is None:
            continue
        try:
            return max(0, int(raw_value))
        except (TypeError, ValueError):
            continue
    return None


def _campaign_xp_loss_total(state: Mapping[str, Any]) -> int | None:
    """Return the campaign-wide XP-loss total, when already checkpointed."""
    raw_value = state.get("campaign_xp_loss_total")
    if isinstance(raw_value, bool) or raw_value is None:
        return None
    try:
        return max(0, int(raw_value))
    except (TypeError, ValueError):
        return None


def _verified_net_xp_loss(
    previous: Mapping[str, Any],
    current: Mapping[str, Any],
) -> int:
    """Return a loss lower bound without inferring its unobserved cause."""
    if (
        current.get("progress_source") not in {"text", "gmcp"}
        or not _progress_state_is_valid(previous, require_level=True)
        or not _progress_state_is_valid(current, require_level=True)
        or _level(previous) != _level(current)
        or type(previous.get("xp")) is not int
        or type(current.get("xp")) is not int
    ):
        return 0
    previous_name = str(previous.get("name") or "").casefold()
    current_name = str(current.get("name") or "").casefold()
    if previous_name and current_name and previous_name != current_name:
        return 0
    return max(0, previous["xp"] - current["xp"])


def _xp_loss_event_observed(
    previous: Mapping[str, Any],
    current: Mapping[str, Any],
) -> bool:
    """Detect a new DD4 XP loss even when partial XP makes the net positive."""
    previous_total = _xp_loss_total(previous)
    current_total = _xp_loss_total(current)
    if current_total is not None:
        if previous_total is not None:
            return current_total > previous_total
        if current_total > 0:
            return True
    current_observed = bool(
        current.get("xp_loss_observed")
        or current.get("campaign_xp_loss_observed")
    )
    previous_observed = bool(
        previous.get("xp_loss_observed")
        or previous.get("campaign_xp_loss_observed")
    )
    return current_observed and not previous_observed


def _preserve_verified_progress_on_unexplained_regression(
    previous: dict[str, Any],
    current: dict[str, Any],
    merged: dict[str, Any],
) -> None:
    """Reject same-level regressions unless DD4 supplied loss evidence."""
    if (
        current.get("dead")
        or current.get("campaign_died_during_segment")
        or current.get("xp_loss_observed")
        or current.get("campaign_xp_loss_observed")
        or current.get("progress_source") in {"text", "gmcp"}
    ):
        return
    previous_level = _level(previous)
    current_level = _level(current)
    previous_xp = _numeric_progress(previous, "xp")
    current_xp = _numeric_progress(current, "xp")
    if (
        previous_level <= 0
        or current_level != previous_level
        or current_xp >= previous_xp
    ):
        return
    for key in ("level", "xp", "max_xp", "xp_to_next_level"):
        if key in previous:
            merged[key] = previous[key]
    previous_progress = previous.get("progress")
    current_progress = current.get("progress")
    if isinstance(previous_progress, Mapping) and isinstance(
        current_progress, Mapping
    ):
        merged["progress"] = {
            **current_progress,
            **{
                key: previous_progress[key]
                for key in ("level", "xp", "maxxp", "xptnl", "xplvl")
                if key in previous_progress
            },
        }


def _campaign_segment_end_state(
    previous: dict[str, Any],
    current: dict[str, Any],
    *,
    execution: str,
    policy_id: str | None = None,
) -> dict[str, Any]:
    """Keep maintenance facts sticky until their owning policy re-evaluates them."""
    merged = dict(current)
    previous_campaign_xp_loss = _campaign_xp_loss_total(previous) or 0
    current_campaign_xp_loss = _campaign_xp_loss_total(current)
    if current_campaign_xp_loss is not None:
        campaign_xp_loss = max(
            previous_campaign_xp_loss,
            current_campaign_xp_loss,
        )
    else:
        segment_xp_loss = _xp_loss_total(current) or 0
        loss_observed = bool(
            current.get("xp_loss_observed")
            or current.get("campaign_xp_loss_observed")
            or segment_xp_loss > 0
        )
        campaign_xp_loss = previous_campaign_xp_loss + (
            segment_xp_loss if loss_observed else 0
        )
    # A reconnect's first GMCP/text progress report can expose a loss that
    # occurred with no socket attached. The net drop is a floor, not another
    # loss to add to explicit in-connection penalties or an already merged total.
    campaign_xp_loss = max(
        campaign_xp_loss,
        previous_campaign_xp_loss + _verified_net_xp_loss(previous, current),
    )
    if campaign_xp_loss > 0:
        # CharacterState starts its XP-loss counter at zero for each live
        # segment. Keep a separate monotonic campaign counter so a later
        # healer segment cannot erase an earlier loss from durable evidence.
        merged["campaign_xp_loss_total"] = campaign_xp_loss
    _preserve_verified_progress_on_unexplained_regression(
        previous,
        current,
        merged,
    )
    if not _execution_records_objective_kills(execution):
        # A maintenance runner can still be attacked by a wandering mobile.
        # Its transient kill ledger belongs to the run transcript, not to the
        # campaign objective ledger. Clear it before the checkpoint is saved.
        merged.pop("campaign_completed_kills", None)
        merged.pop("campaign_objective_kills", None)
    if execution == "source-ranked-hunt":
        # A repair marker authorizes one live attempt, not an indefinite
        # replay loop. Maintenance segments retain it through sticky metadata;
        # the first source-ranked attempt consumes it regardless of outcome.
        merged.pop(_SOURCE_RANKED_REVALIDATION_POLICY_KEY, None)
        merged.pop(_FAME_RECOVERY_SOURCE_RANKED_KEY, None)
    for key in _CAMPAIGN_STICKY_METADATA_KEYS:
        if (
            key == _SOURCE_RANKED_REVALIDATION_POLICY_KEY
            and execution == "source-ranked-hunt"
        ):
            # Do not let the sticky pass restore a marker consumed above.
            continue
        if key in previous and (
            key not in merged
            or (
                key == _SOURCE_RANKED_XP_LOSS_POLICIES_KEY
                and not merged.get(key)
                and previous.get(key)
            )
        ):
            # Starter maintenance runs initialize this history to an empty
            # list. Preserve a real source-hunt loss ledger across healer,
            # sale, and rearm segments until a later positive kill clears it.
            merged[key] = previous[key]
    known_skills: set[str] = set()
    for state_source in (previous, current):
        raw_skills = state_source.get("campaign_known_skills")
        if isinstance(raw_skills, str):
            raw_skills = (raw_skills,)
        if isinstance(raw_skills, (list, tuple, set, frozenset)):
            known_skills.update(
                " ".join(str(skill).casefold().split())
                for skill in raw_skills
                if str(skill).strip()
            )
        raw_levels = state_source.get("campaign_known_skill_levels")
        if isinstance(raw_levels, Mapping):
            known_skills.update(
                " ".join(str(skill).casefold().split())
                for skill in raw_levels
                if str(skill).strip()
            )
    if known_skills:
        merged["campaign_known_skills"] = sorted(known_skills)
    known_skill_levels: dict[str, int] = {}
    for source_index, state_source in enumerate((previous, current)):
        raw_levels = state_source.get("campaign_known_skill_levels")
        if not isinstance(raw_levels, Mapping):
            continue
        for raw_skill, raw_percent in raw_levels.items():
            try:
                percent = int(raw_percent)
            except (TypeError, ValueError):
                continue
            skill = " ".join(str(raw_skill).casefold().split())
            if skill:
                if source_index == 1:
                    # The current segment may have refreshed the skill list
                    # from the live server. Do not let historical maxima mask
                    # a real proficiency loss.
                    known_skill_levels[skill] = percent
                else:
                    known_skill_levels[skill] = max(
                        percent,
                        known_skill_levels.get(skill, 0),
                    )
    if known_skill_levels:
        merged["campaign_known_skill_levels"] = dict(
            sorted(known_skill_levels.items())
        )
    _refresh_training_deficit_marker(merged)
    regressions = _observed_training_skill_regression(previous, current)
    if regressions:
        existing_regression = merged.get(_TRAINING_SKILL_REGRESSION_KEY)
        current_boot_id = merged.get("world_boot_id")
        current_level = _level(merged)
        same_marker = isinstance(existing_regression, Mapping) and (
            existing_regression.get("boot_id") in {None, current_boot_id}
            and existing_regression.get("level") in {None, current_level}
        )
        merged[_TRAINING_SKILL_REGRESSION_KEY] = {
            "boot_id": current_boot_id,
            "level": current_level,
            "skills": regressions,
            "attempted": bool(
                same_marker and existing_regression.get("attempted")
            ),
            "observed_policy": policy_id or current.get("campaign_last_policy"),
        }
    protection_marker = merged.get(_PROTECTION_RECOVERY_KEY)
    if (
        isinstance(protection_marker, Mapping)
        and merged.get("world_boot_id") is not None
        and protection_marker.get("boot_id") is not None
        and protection_marker.get("boot_id") != merged.get("world_boot_id")
    ):
        # The sticky metadata pass preserves useful campaign facts between
        # segments, but a protection failure is valid only in its reboot.
        merged.pop(_PROTECTION_RECOVERY_KEY, None)
    ordinary_fallback = merged.get(
        _PROTECTION_RECOVERY_ORDINARY_FALLBACK_KEY
    )
    if isinstance(ordinary_fallback, Mapping) and (
        (
            merged.get("world_boot_id") is not None
            and ordinary_fallback.get("boot_id") is not None
            and ordinary_fallback.get("boot_id") != merged.get("world_boot_id")
        )
        or ordinary_fallback.get("level") not in {None, _level(merged)}
        or _state_has_sanctuary_reserve(merged)
    ):
        merged.pop(_PROTECTION_RECOVERY_ORDINARY_FALLBACK_KEY, None)
    if (
        previous.get(_MAGIC_SHOP_ROUTE_BLOCKED_KEY)
        and execution
        not in {"buy-flight", "buy-flight-potion", "buy-optional-flight"}
    ):
        # StarterPolicy emits a false route-block default on unrelated runs.
        # Keep the live block until productive field work advances its owner.
        merged[_MAGIC_SHOP_ROUTE_BLOCKED_KEY] = True
        if previous.get(_MAGIC_SHOP_ROUTE_BLOCKED_BOOT_KEY):
            merged[_MAGIC_SHOP_ROUTE_BLOCKED_BOOT_KEY] = previous[
                _MAGIC_SHOP_ROUTE_BLOCKED_BOOT_KEY
            ]
    fame = _state_fame(current)
    if fame is not None:
        if fame < 0:
            merged[_SHOP_REARM_REPUTATION_BLOCKED_KEY] = True
        else:
            merged.pop(_SHOP_REARM_REPUTATION_BLOCKED_KEY, None)
    if not current.get("world_boot_id") and previous.get("world_boot_id"):
        merged["world_boot_id"] = previous["world_boot_id"]
    flight_evidence = current.get(FLIGHT_EVIDENCE_KEY)
    if isinstance(flight_evidence, Mapping) and not flight_evidence.get("boot_id"):
        merged[FLIGHT_EVIDENCE_KEY] = {
            **dict(flight_evidence), "boot_id": merged.get("world_boot_id"),
        }
    transit_evidence = current.get(CITY_TRANSIT_KEY)
    if isinstance(transit_evidence, Mapping) and not transit_evidence.get("boot_id"):
        merged[CITY_TRANSIT_KEY] = {
            **dict(transit_evidence), "boot_id": merged.get("world_boot_id"),
        }
    partial_timeout_retry = merged.get(
        _SOURCE_RANKED_PARTIAL_TIMEOUT_RETRY_KEY
    )
    if isinstance(partial_timeout_retry, Mapping) and (
        partial_timeout_retry.get("boot_id") != merged.get("world_boot_id")
        or partial_timeout_retry.get("level") not in {None, _level(merged)}
    ):
        merged.pop(_SOURCE_RANKED_PARTIAL_TIMEOUT_RETRY_KEY, None)
    frontier_retry = merged.get(_SOURCE_RANKED_FRONTIER_RETRY_KEY)
    if (
        isinstance(frontier_retry, Mapping)
        and frontier_retry.get("boot_id") != merged.get("world_boot_id")
    ):
        merged.pop(_SOURCE_RANKED_FRONTIER_RETRY_KEY, None)
    elif execution == "source-ranked-hunt" and (
        _level(current) > _level(previous)
        or current.get("campaign_objective_kills")
        or current.get("campaign_completed_kills")
    ):
        # A confirmed kill or level gain starts a fresh frontier cycle. A
        # partial, non-productive retry keeps its one-attempt guard so the
        # campaign cannot spin on the same reboot-local target.
        merged.pop(_SOURCE_RANKED_FRONTIER_RETRY_KEY, None)
    current_flight_price = current.get(_MAGIC_SHOP_FLIGHT_PRICE_KEY)
    if current_flight_price is None:
        for key in (
            _MAGIC_SHOP_FLIGHT_PRICE_KEY,
            _MAGIC_SHOP_FLIGHT_PRICE_BOOT_KEY,
        ):
            if merged.get(key) is None and previous.get(key) is not None:
                merged[key] = previous[key]
    else:
        # A standalone shop run can observe the list price before it issues
        # `time`, leaving the policy's price boot unset. Bind that fresh quote
        # to the campaign's known current reboot instead of retaining a stale
        # prior-reboot stamp.
        current_price_boot = current.get(_MAGIC_SHOP_FLIGHT_PRICE_BOOT_KEY)
        if current_price_boot:
            merged[_MAGIC_SHOP_FLIGHT_PRICE_BOOT_KEY] = current_price_boot
        elif merged.get("world_boot_id"):
            merged[_MAGIC_SHOP_FLIGHT_PRICE_BOOT_KEY] = merged["world_boot_id"]
        else:
            merged.pop(_MAGIC_SHOP_FLIGHT_PRICE_BOOT_KEY, None)
    if (
        "combat_pouch_potions" not in current
        and "combat_pouch_potions" in previous
    ):
        merged["combat_pouch_potions"] = previous["combat_pouch_potions"]
    if (
        "verified_combat_pouch_potions" not in current
        and "verified_combat_pouch_potions" in previous
    ):
        merged["verified_combat_pouch_potions"] = previous[
            "verified_combat_pouch_potions"
        ]
    if (
        execution
        not in {"buy-flight", "buy-flight-potion", "buy-optional-flight"}
        and previous.get("magic_shop_purchase_failed")
    ):
        merged["magic_shop_purchase_failed"] = True
    if previous.get("vault_storage_rejected"):
        merged["vault_storage_rejected"] = True
    if _SACK_VAULT_ITEMS_KEY in previous:
        merged[_SACK_VAULT_ITEMS_KEY] = previous[_SACK_VAULT_ITEMS_KEY]
    if _SACK_VAULT_RECLAIM_LEVEL_KEY in previous:
        merged[_SACK_VAULT_RECLAIM_LEVEL_KEY] = previous[
            _SACK_VAULT_RECLAIM_LEVEL_KEY
        ]
    for owner, key in (
        ("outfit-basic-gear", "campaign_outfit_attempted_level"),
        ("recover-basic-body", "campaign_body_gear_attempted_level"),
        (
            "recover-school-wrist-float",
            "campaign_school_wrist_float_attempted_level",
        ),
        ("recover-gremlin-waist", "campaign_gremlin_waist_attempted_level"),
        ("recover-daycare-ring", "campaign_daycare_ring_attempted_level"),
        ("recover-daycare-ring", _DAYCARE_RING_ATTEMPT_BOOT_KEY),
        ("recover-daycare-ring", _DAYCARE_RING_COOLDOWN_KEY),
        ("recover-daycare-ring", _DAYCARE_RING_BLOCKED_LEVEL_KEY),
        ("recover-daycare-ring", _DAYCARE_RING_BLOCKED_BOOT_KEY),
        ("recover-war-dog-collar", "campaign_war_dog_collar_attempted_level"),
        ("recover-war-dog-collar", _WAR_DOG_COLLAR_ATTEMPT_BOOT_KEY),
        ("recover-war-dog-collar", _WAR_DOG_COLLAR_COOLDOWN_KEY),
        (
            "recover-foundry-set-circlet",
            _FOUNDRY_SET_CIRCLET_ATTEMPTED_LEVEL_KEY,
        ),
        ("upgrade-piercing-weapon", _PIERCING_WEAPON_UPGRADE_BOOT_KEY),
        ("upgrade-piercing-weapon", _PIERCING_WEAPON_UPGRADE_COOLDOWN_KEY),
    ):
        if execution != owner and key in previous:
            if (
                key in set(_MAINTENANCE_ATTEMPT_LEVEL_KEYS.values())
                and key in current
            ):
                # Reconciliation can rebuild a checkpoint from an older
                # failed segment. Never age a newer same-level maintenance
                # attempt back to the level stored in that old segment.
                try:
                    merged[key] = max(int(previous[key]), int(current[key]))
                except (TypeError, ValueError):
                    merged[key] = current[key]
            else:
                merged[key] = previous[key]
    if _INTERMEDIATE_PIERCING_WEAPON_UPGRADE_COOLDOWN_KEY in previous:
        merged[_INTERMEDIATE_PIERCING_WEAPON_UPGRADE_COOLDOWN_KEY] = previous[
            _INTERMEDIATE_PIERCING_WEAPON_UPGRADE_COOLDOWN_KEY
        ]
    return _apply_flight_funding_state_transition(
        previous,
        merged,
        execution=execution,
        funding_completed=False,
    )


def _apply_flight_funding_state_transition(
    previous: dict[str, Any],
    current: dict[str, Any],
    *,
    execution: str,
    funding_completed: bool,
) -> dict[str, Any]:
    """Advance the bounded flight-funding loop without mixing it with XP."""
    transitioned = dict(current)
    if execution == "cast-flight":
        evidence = transitioned.get(FLIGHT_EVIDENCE_KEY)
        if (
            isinstance(evidence, Mapping) and evidence.get("status") == "confirmed"
            and any(_state_has_active_affect(transitioned.get("affects"), effect)
                    for effect in ("fly", "levitation"))
        ):
            for key in (_FLIGHT_FUNDING_REQUIRED_KEY, _FLIGHT_FUNDING_RETRY_KEY,
                        _FLIGHT_PURCHASE_COOLDOWN_KEY):
                transitioned.pop(key, None)
            if any(str(transitioned.get("campaign_fastwalk_abort_reason") or "").startswith(prefix)
                   for prefix in _FLIGHT_ROUTE_ABORT_PREFIXES):
                transitioned.pop("campaign_fastwalk_abort_reason", None)
            transitioned = _clear_flight_blocked_research_evidence(transitioned)
        return transitioned
    if execution == "provision-funding":
        if previous.get(_FLIGHT_FUNDING_REQUIRED_KEY) and funding_completed:
            transitioned.pop(_FLIGHT_FUNDING_REQUIRED_KEY, None)
            transitioned[_FLIGHT_FUNDING_RETRY_KEY] = True
        return transitioned
    if execution not in {
        "buy-flight",
        "buy-flight-potion",
        "buy-optional-flight",
    }:
        return transitioned

    active_flight = any(
        _state_has_active_affect(transitioned.get("affects"), effect)
        for effect in ("fly", "levitation")
    )
    if transitioned.get(_MAGIC_SHOP_ROUTE_BLOCKED_KEY) and not active_flight:
        # The shop was not reached, so this is neither a successful purchase
        # nor evidence that more money is needed. Preserve the existing funding
        # objective and rotate through productive work before another live
        # preflight of mobile 3064's current location.
        for key in (_FLIGHT_FUNDING_REQUIRED_KEY, _FLIGHT_FUNDING_RETRY_KEY):
            if previous.get(key) and key not in transitioned:
                transitioned[key] = previous[key]
        transitioned["magic_shop_purchase_failed"] = False
        transitioned[_FLIGHT_PURCHASE_COOLDOWN_KEY] = (
            _FLIGHT_PURCHASE_COOLDOWN_SEGMENTS
        )
        route_boot = transitioned.get("world_boot_id") or previous.get(
            "world_boot_id"
        )
        if route_boot:
            transitioned[_MAGIC_SHOP_ROUTE_BLOCKED_BOOT_KEY] = route_boot
        return transitioned

    transitioned.pop(_MAGIC_SHOP_ROUTE_BLOCKED_KEY, None)
    transitioned.pop(_MAGIC_SHOP_ROUTE_BLOCKED_BOOT_KEY, None)

    if active_flight or transitioned.get("magic_shop_purchase_failed") is False:
        transitioned.pop(_FLIGHT_FUNDING_REQUIRED_KEY, None)
        transitioned.pop(_FLIGHT_FUNDING_RETRY_KEY, None)
        transitioned.pop(_FLIGHT_PURCHASE_COOLDOWN_KEY, None)
        transitioned.pop("campaign_fastwalk_abort_reason", None)
        if active_flight:
            transitioned = _clear_flight_blocked_research_evidence(transitioned)
    elif transitioned.get("magic_shop_purchase_failed") is True:
        transitioned.pop(_FLIGHT_FUNDING_RETRY_KEY, None)
        transitioned[_FLIGHT_PURCHASE_COOLDOWN_KEY] = (
            _FLIGHT_PURCHASE_COOLDOWN_SEGMENTS
        )
        if execution == "buy-optional-flight":
            transitioned.pop(_FLIGHT_FUNDING_REQUIRED_KEY, None)
        else:
            transitioned[_FLIGHT_FUNDING_REQUIRED_KEY] = True
    return transitioned


def _clear_flight_blocked_research_evidence(
    state: dict[str, Any],
) -> dict[str, Any]:
    """Reopen same-reboot routes that failed only for missing flight."""
    if not any(
        _state_has_active_affect(state.get("affects"), effect)
        for effect in ("fly", "levitation")
    ):
        return state
    research_results = state.get("campaign_research_results")
    if not isinstance(research_results, dict):
        return state
    current_boot = state.get("world_boot_id")
    flight_blocked_policy_ids = {
        str(policy_id)
        for policy_id, result in research_results.items()
        if isinstance(result, Mapping)
        and result.get("boot_id") == current_boot
        and isinstance(result.get("route_hazard"), str)
        and result["route_hazard"].startswith(_FLIGHT_ROUTE_ABORT_PREFIXES)
    }
    if not flight_blocked_policy_ids:
        return state
    repaired = dict(state)
    remaining_results = {
        policy_id: result
        for policy_id, result in research_results.items()
        if str(policy_id) not in flight_blocked_policy_ids
    }
    if remaining_results:
        repaired["campaign_research_results"] = remaining_results
    else:
        repaired.pop("campaign_research_results", None)
    cooldowns = dict(repaired.get(_RESEARCH_ABSENCE_COOLDOWN_KEY) or {})
    for policy_id in flight_blocked_policy_ids:
        cooldowns.pop(policy_id, None)
    if cooldowns:
        repaired[_RESEARCH_ABSENCE_COOLDOWN_KEY] = cooldowns
    else:
        repaired.pop(_RESEARCH_ABSENCE_COOLDOWN_KEY, None)
    cleared = {
        str(policy_id)
        for policy_id in repaired.get(_CLEARED_RESEARCH_POLICIES_KEY, ())
        if str(policy_id) not in flight_blocked_policy_ids
    }
    if cleared:
        repaired[_CLEARED_RESEARCH_POLICIES_KEY] = sorted(cleared)
    else:
        repaired.pop(_CLEARED_RESEARCH_POLICIES_KEY, None)
    return repaired


def _campaign_has_item(state: dict[str, Any], item_name: str) -> bool:
    """Check carried, worn, and newly acquired state for a named item."""
    target = normalize_item_name(item_name)
    descriptions = [
        *_inventory_descriptions(state.get("inventory")),
        *(
            str(description)
            for description in state.get("campaign_worn_equipment") or ()
        ),
        *(
            str(item.get("item", ""))
            for item in state.get("acquired_items") or ()
            if isinstance(item, dict)
        ),
    ]
    return any(
        target in normalize_item_name(description)
        for description in descriptions
    )


def _prioritize_sack_vault_claims(items: Any) -> tuple[str, ...]:
    """Reclaim combat-value gear before heavier fallback armour."""
    if not isinstance(items, (list, tuple)):
        return ()
    priority = {
        keyword: index
        for index, keyword in enumerate(
            ("collar", "bracer", "belt", "sleeves", "vest", "guards", "cape")
        )
    }
    unique = tuple(dict.fromkeys(str(item).casefold() for item in items))
    return tuple(
        sorted(unique, key=lambda item: (priority.get(item, len(priority)), item))
    )


def _campaign_research_results(state: dict[str, Any]) -> dict[str, dict[str, Any]]:
    raw_results = state.get("campaign_research_results")
    if not isinstance(raw_results, dict):
        return {}
    return {
        str(policy_id): dict(result)
        for policy_id, result in raw_results.items()
        if isinstance(result, dict)
    }


def _repair_research_absence_cooldowns(
    state: Mapping[str, Any],
) -> dict[str, Any]:
    """Drop absence cooldowns whose reboot-scoped evidence no longer exists."""
    raw_cooldowns = state.get(_RESEARCH_ABSENCE_COOLDOWN_KEY)
    if not isinstance(raw_cooldowns, Mapping):
        return dict(state)
    results = _campaign_research_results(dict(state))
    boot_id = state.get("world_boot_id")
    retained: dict[str, int] = {}
    for raw_policy_id, raw_remaining in raw_cooldowns.items():
        policy_id = str(raw_policy_id)
        try:
            remaining = int(raw_remaining)
        except (TypeError, ValueError):
            continue
        result = results.get(policy_id)
        if (
            remaining <= 0
            or not isinstance(result, dict)
            or result.get("boot_id") != boot_id
            or not (
                result.get("absent") is True
                or result.get("route_hazard")
                == _DYNAMIC_FIELD_ROUTE_HAZARD_ABORT_REASON
                or _is_retryable_source_ranked_route_hazard(
                    policy_id,
                    result.get("route_hazard"),
                )
                or result.get("retryable_failure") is True
            )
        ):
            continue
        retained[policy_id] = remaining
    original = dict(raw_cooldowns)
    if retained == original:
        return dict(state)
    repaired = dict(state)
    if retained:
        repaired[_RESEARCH_ABSENCE_COOLDOWN_KEY] = retained
    else:
        repaired.pop(_RESEARCH_ABSENCE_COOLDOWN_KEY, None)
    return repaired


def _repair_protection_recovery_metadata(
    state: Mapping[str, Any],
    segments: list[Any],
    *,
    storage: RunStorage | None = None,
) -> dict[str, Any]:
    """Recover a current-reboot protection need from recorded hunt evidence."""
    updated = dict(state)
    existing_marker = updated.get(_PROTECTION_RECOVERY_KEY)
    boot_id = updated.get("world_boot_id")
    if (
        boot_id is not None
        and isinstance(existing_marker, Mapping)
        and existing_marker.get("boot_id") is not None
        and existing_marker.get("boot_id") != boot_id
    ):
        # Protection evidence is reboot-scoped; never carry an old-world
        # marker into a new live world.
        updated.pop(_PROTECTION_RECOVERY_KEY, None)
        existing_marker = None
    fallback_marker = updated.get(
        _PROTECTION_RECOVERY_ORDINARY_FALLBACK_KEY
    )
    if isinstance(fallback_marker, Mapping) and (
        (
            boot_id is not None
            and fallback_marker.get("boot_id") is not None
            and fallback_marker.get("boot_id") != boot_id
        )
        or fallback_marker.get("level") not in {None, _level(updated)}
    ):
        updated.pop(_PROTECTION_RECOVERY_ORDINARY_FALLBACK_KEY, None)
    existing_hard_health_marker = bool(
        isinstance(existing_marker, Mapping)
        and existing_marker.get("trigger")
        == _PROTECTION_RECOVERY_HARD_HEALTH_TRIGGER
    )
    has_sanctuary_reserve = _state_has_sanctuary_reserve(updated)
    if has_sanctuary_reserve and not existing_hard_health_marker:
        updated.pop(_PROTECTION_RECOVERY_KEY, None)
    if boot_id is None:
        return updated

    def hunt_evidence(segment: Mapping[str, Any]) -> tuple[
        str, Mapping[str, Any], list[Any] | None, int, bool, bool
    ] | None:
        if segment.get("status") not in {"success", "ready"}:
            return None
        phase = str(segment.get("phase") or "")
        source_policy_id: str | None = (
            phase if phase.startswith(_SOURCE_RANKED_POLICY_PREFIX) else None
        )
        if phase == "provision-funding" and storage is not None:
            try:
                run_id = int(segment.get("run_id"))
            except (TypeError, ValueError):
                run_id = None
            terminal_state = (
                _run_terminal_state(storage, run_id)
                if run_id is not None
                else None
            )
            source_policy_ids = (
                _source_ranked_policy_ids_from_fastwalk_state(terminal_state)
                if terminal_state is not None
                else ()
            )
            if len(source_policy_ids) == 1:
                source_policy_id = source_policy_ids[0]
        if source_policy_id is None and "-hunt-" not in phase:
            return None
        try:
            start = json.loads(segment.get("start_state_json") or "{}")
            end = json.loads(segment.get("end_state_json") or "{}")
        except (TypeError, json.JSONDecodeError):
            return None
        if not isinstance(start, Mapping) or not isinstance(end, Mapping):
            return None
        if not end or end.get("world_boot_id") != boot_id:
            return None
        outcomes = end.get("campaign_fastwalk_consider_outcomes")
        objective_kills = _segment_objective_kills(storage, segment)
        xp_delta = _xp_delta(start, end)
        has_viable_consider = (
            isinstance(outcomes, Mapping)
            and any(value is True for value in outcomes.values())
        )
        source_ranked_xp_loss = (
            source_policy_id is not None
            and not objective_kills
            and (
                xp_delta < 0
                or _xp_loss_event_observed(start, end)
            )
        )
        if not (
            has_viable_consider
            or source_ranked_xp_loss
            or bool(objective_kills)
        ):
            return None
        return (
            source_policy_id or phase,
            end,
            objective_kills,
            xp_delta,
            _hard_health_floor_withdrawal(end),
            _xp_loss_event_observed(start, end),
        )

    def is_positive_kill(
        evidence: tuple[
            str, Mapping[str, Any], list[Any] | None, int, bool, bool
        ] | None,
    ) -> bool:
        if evidence is None:
            return False
        _phase, _end, objective_kills, xp_delta, _hard_health, _loss_observed = evidence
        return (
            isinstance(objective_kills, (list, tuple))
            and bool(objective_kills)
            and xp_delta > 0
        )

    normalized_segments: list[Mapping[str, Any]] = []
    for segment in segments:
        if isinstance(segment, Mapping):
            normalized_segments.append(segment)
            continue
        try:
            normalized_segments.append(
                {key: segment[key] for key in segment.keys()}
            )
        except (AttributeError, KeyError, TypeError):
            continue
    evidence = [hunt_evidence(segment) for segment in normalized_segments]
    replayed_loss_counts: Counter[str] = Counter()
    loss_evidence_indexes: dict[str, list[int]] = {}
    for index, (segment, item) in enumerate(zip(normalized_segments, evidence)):
        if item is None:
            continue
        phase, end, objective_kills, xp_delta, _hard_health, loss_observed = item
        if (
            phase.startswith(_SOURCE_RANKED_POLICY_PREFIX)
            and not objective_kills
            and (xp_delta < 0 or loss_observed)
        ):
            loss_evidence_indexes.setdefault(phase, []).append(index)
            replayed_loss_counts[phase] += 1
            updated = _remember_source_ranked_xp_loss(
                updated,
                policy_id=phase,
                level=_level(end),
                boot_id=end.get("world_boot_id"),
                xp_delta=xp_delta,
                observed_loss_count=replayed_loss_counts[phase],
                loss_event_id=segment.get("id"),
                sanctuary_protected=(
                    _source_ranked_loss_used_sanctuary(end)
                ),
            )
    positive_source_policy_indexes: dict[str, list[int]] = {}
    for index, item in enumerate(evidence):
        if item is None or not is_positive_kill(item):
            continue
        phase, _end, objective_kills, _objective_delta, _hard_health, _loss_observed = item
        if not phase.startswith(_SOURCE_RANKED_POLICY_PREFIX):
            continue
        tagged_policies = _source_ranked_kill_policy_ids(objective_kills)
        for policy_id in tagged_policies or (phase,):
            positive_source_policy_indexes.setdefault(
                str(policy_id),
                [],
            ).append(index)
    positive_source_policies: set[str] = set()
    for policy_id, positive_indexes in positive_source_policy_indexes.items():
        loss_indexes = loss_evidence_indexes.get(policy_id)
        if loss_indexes:
            # A productive result before a later loss must not reopen the
            # route. Only a positive result after the latest loss clears it.
            if any(index > max(loss_indexes) for index in positive_indexes):
                positive_source_policies.add(policy_id)
            continue
        record = _source_ranked_xp_loss_record(updated, policy_id)
        if record is None:
            continue
        try:
            recorded_loss_event_id = int(record.get("loss_event_id"))
        except (TypeError, ValueError):
            recorded_loss_event_id = None
        if recorded_loss_event_id is None:
            # Legacy loss records may not carry a segment id. With no loss
            # evidence in the current history, retain the older clear rule.
            positive_source_policies.add(policy_id)
            continue
        for index in positive_indexes:
            try:
                positive_segment_id = int(normalized_segments[index].get("id"))
            except (AttributeError, TypeError, ValueError):
                continue
            if positive_segment_id > recorded_loss_event_id:
                positive_source_policies.add(policy_id)
                break
    if positive_source_policies:
        # A later positive objective result is authoritative over an older
        # same-reboot loss when startup reconstructs the loss ledger.
        updated = _clear_source_ranked_xp_loss(
            updated,
            policy_ids=positive_source_policies,
        )
    existing = updated.get(_PROTECTION_RECOVERY_KEY)
    if (
        isinstance(existing, Mapping)
        and existing.get("boot_id") == boot_id
    ):
        # A checkpoint can predate the positive kill that cleared this gate.
        # Repair that persisted state before the marker can steer a new run.
        policy_id = str(existing.get("policy_id") or "")
        hard_health_marker = (
            existing.get("trigger")
            == _PROTECTION_RECOVERY_HARD_HEALTH_TRIGGER
        )
        failure_indexes = [
            index
            for index, item in enumerate(evidence)
            if (
                item is not None
                and item[0] == policy_id
                and not is_positive_kill(item)
                and (item[3] < 0 or item[4] or item[5])
            )
        ]
        if failure_indexes:
            failure_index = failure_indexes[-1]
            if any(
                is_positive_kill(item)
                and (not hard_health_marker or item[0] == policy_id)
                for item in evidence[failure_index + 1 :]
            ):
                updated.pop(_PROTECTION_RECOVERY_KEY, None)
        return updated
    for index in range(len(evidence) - 1, -1, -1):
        item = evidence[index]
        if item is None:
            continue
        phase, end, objective_kills, xp_delta, hard_health, loss_observed = item
        if isinstance(objective_kills, (list, tuple)) and objective_kills:
            continue
        if not hard_health and not loss_observed and xp_delta >= 0:
            continue
        if not hard_health and has_sanctuary_reserve:
            continue
        if any(
            is_positive_kill(later)
            and (not hard_health or later[0] == phase)
            for later in evidence[index + 1 :]
        ):
            return updated
        marker = {
            "boot_id": boot_id,
            "level": _level(end),
            "policy_id": phase,
            "xp_delta": xp_delta,
            "reason": (
                "recorded viable hunt reached the hard health floor before a kill"
                if hard_health
                else "recorded viable hunt withdrew with an XP loss before a kill"
            ),
        }
        if hard_health:
            marker["trigger"] = _PROTECTION_RECOVERY_HARD_HEALTH_TRIGGER
        updated[_PROTECTION_RECOVERY_KEY] = marker
        return updated
    return updated


def _remember_last_productive_policy(
    state: dict[str, Any],
    *,
    policy_xp_deltas: Mapping[str, int],
) -> dict[str, Any]:
    """Keep a current-reboot hunt available after an absent research probe."""
    results = _campaign_research_results(state)
    boot_id = state.get("world_boot_id")
    productive_history = _state_productive_policy_ids(state)
    history_is_present = isinstance(
        state.get(_PRODUCTIVE_POLICY_HISTORY_KEY),
        Mapping,
    )

    def is_productive(policy_id: str) -> bool:
        result = results.get(policy_id)
        if (
            history_is_present
            and policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX)
            and "-hunt-" in policy_id
            and policy_id not in productive_history
        ):
            return False
        if isinstance(result, dict) and "max_objective_kill_xp" in result:
            try:
                if int(result.get("max_objective_kill_xp") or 0) < (
                    _SOURCE_RANKED_MIN_MEANINGFUL_KILL_XP
                ):
                    return False
            except (TypeError, ValueError):
                return False
        return bool(
            isinstance(result, dict)
            and result.get("boot_id") == boot_id
            and result.get("observed") is True
            and result.get("viable") is True
            and result.get("completed_kill") is True
            and "-hunt" in str(policy_id)
        )

    existing = state.get(_LAST_PRODUCTIVE_POLICY_KEY)
    if isinstance(existing, str) and is_productive(existing):
        return state
    candidates = [
        str(policy_id)
        for policy_id, delta in policy_xp_deltas.items()
        if int(delta or 0) >= _SOURCE_RANKED_MIN_MEANINGFUL_KILL_XP
        and is_productive(str(policy_id))
    ]
    if not candidates:
        return state
    selected = max(
        candidates,
        key=lambda policy_id: (
            int(policy_xp_deltas.get(policy_id, 0) or 0),
            policy_id,
        ),
    )
    if existing == selected:
        return state
    remembered = dict(state)
    remembered[_LAST_PRODUCTIVE_POLICY_KEY] = selected
    return remembered


def _historical_productive_handoff_policy_id(
    state: Mapping[str, Any],
    *,
    current_group: frozenset[str],
) -> str | None:
    """Find a previously productive hunt whose current miss is retryable."""
    history = state.get(_PRODUCTIVE_POLICY_HISTORY_KEY)
    boot_id = state.get("world_boot_id")
    if not isinstance(history, Mapping) or history.get("boot_id") != boot_id:
        return None
    policy_ids = history.get("policy_ids")
    if not isinstance(policy_ids, (list, tuple, set, frozenset)):
        return None
    cooldowns = state.get(_RESEARCH_ABSENCE_COOLDOWN_KEY) or {}
    results = _campaign_research_results(dict(state))
    candidates: list[str] = []
    for raw_policy_id in policy_ids:
        policy_id = str(raw_policy_id)
        if "-hunt-" not in policy_id or policy_id in current_group:
            continue
        probe_id = policy_id.replace("-hunt-", "-probe-", 1)
        if any(
            int(cooldowns.get(candidate_id) or 0) > 0
            for candidate_id in (policy_id, probe_id)
        ):
            continue
        hunt_result = results.get(policy_id)
        probe_result = results.get(probe_id)
        blocked = False
        for result, is_hunt in (
            (hunt_result, True),
            (probe_result, False),
        ):
            if not isinstance(result, dict) or result.get("boot_id") != boot_id:
                continue
            if result.get("absent") is True or result.get("unobserved") is True:
                continue
            if is_hunt and result.get("completed_kill") is False:
                blocked = True
                break
            if result.get("observed") is True and result.get("viable") is True:
                continue
            blocked = True
            break
        if not blocked:
            candidates.append(policy_id)
    return sorted(candidates)[0] if candidates else None


def _repair_sanctuary_resource_acquisition_history(
    state: Mapping[str, Any],
    segments: Collection[Mapping[str, Any]],
) -> dict[str, Any]:
    """Restore successful sanctuary acquisitions misread as XP probes."""
    boot_id = state.get("world_boot_id")
    if boot_id is None:
        return dict(state)

    latest_by_policy: dict[str, Mapping[str, Any]] = {}
    for segment in segments:
        phase = str(segment.get("phase") or "")
        if phase in _SANCTUARY_RESOURCE_POLICY_IDS:
            latest_by_policy[phase] = segment

    repaired = dict(state)
    results = _campaign_research_results(repaired)
    absence_cooldowns = dict(
        repaired.get(_RESEARCH_ABSENCE_COOLDOWN_KEY) or {}
    )
    crowd_cooldowns = dict(repaired.get(_RESEARCH_CROWD_COOLDOWN_KEY) or {})
    reconstructed_attempts = dict(
        repaired.get(_SANCTUARY_RESOURCE_ATTEMPTS_KEY) or {}
    )
    changed = False

    # Replay independently of the current checkpoint: its counter already
    # includes these segments. The first segment's start supplies the prefix
    # missing from a bounded history window; the saved count remains a floor.
    history_attempts: dict[str, dict[str, Any]] = {}
    seen_attempt_policies: set[str] = set()
    acquired_attempt_policies: set[str] = set()
    for segment in sorted(
        segments,
        key=lambda row: int(row.get("sequence", 0) or 0),
    ):
        phase = str(segment.get("phase") or "")
        if phase not in _SANCTUARY_RESOURCE_POLICY_IDS:
            continue
        try:
            start = json.loads(segment.get("start_state_json") or "{}")
            end = json.loads(segment.get("end_state_json") or "{}")
        except (TypeError, ValueError, json.JSONDecodeError):
            continue
        if not isinstance(start, Mapping) or not isinstance(end, Mapping):
            continue
        if end.get("world_boot_id") != boot_id:
            continue
        if phase not in seen_attempt_policies:
            seen_attempt_policies.add(phase)
            initial_count = _sanctuary_resource_attempt_count(
                start, phase, boot_id=boot_id, level=_level(end),
            )
            if initial_count:
                history_attempts[phase] = {
                    "boot_id": boot_id, "level": _level(end),
                    "count": initial_count,
                }
        if _verified_combat_potion_count(end, "purple") > _verified_combat_potion_count(
            start,
            "purple",
        ):
            history_attempts.pop(phase, None)
            acquired_attempt_policies.add(phase)
            continue
        result = _campaign_research_results(end).get(phase)
        retryable_failure = bool(
            isinstance(result, Mapping)
            and result.get("retryable_failure") is True
        )
        route_abort = bool(
            isinstance(end.get("campaign_fastwalk_abort_reason"), str)
            and end.get("campaign_fastwalk_abort_reason")
            and not end.get("campaign_fastwalk_target_absent")
        )
        if (
            end.get("campaign_died_during_segment")
            or not (retryable_failure or route_abort)
        ):
            continue
        level = _level(end)
        previous_attempt = history_attempts.get(phase)
        if not (
            isinstance(previous_attempt, Mapping)
            and previous_attempt.get("boot_id") == boot_id
            and previous_attempt.get("level") == level
        ):
            count = 0
        else:
            try:
                count = max(0, int(previous_attempt.get("count") or 0))
            except (TypeError, ValueError):
                count = 0
        history_attempts[phase] = {
            "boot_id": boot_id,
            "level": level,
            "count": count + 1,
        }

    for phase in seen_attempt_policies:
        attempt = history_attempts.get(phase)
        if phase in acquired_attempt_policies:
            reconstructed_attempts.pop(phase, None)
            if attempt is not None:
                reconstructed_attempts[phase] = attempt
        elif attempt is not None and attempt["count"] > _sanctuary_resource_attempt_count(
            repaired, phase, boot_id=boot_id, level=attempt["level"],
        ):
            reconstructed_attempts[phase] = attempt

    for policy_id, segment in latest_by_policy.items():
        if str(segment.get("status") or "") != "success":
            continue
        try:
            start = json.loads(segment.get("start_state_json") or "{}")
            end = json.loads(segment.get("end_state_json") or "{}")
        except (TypeError, ValueError, json.JSONDecodeError):
            continue
        if not isinstance(start, Mapping) or not isinstance(end, Mapping):
            continue
        if end.get("world_boot_id") != boot_id:
            continue
        if end.get("campaign_died_during_segment"):
            continue
        end_purple = _verified_combat_potion_count(end, "purple")
        start_purple = _verified_combat_potion_count(start, "purple")
        if end_purple <= start_purple:
            previous_result = results.get(policy_id)
            if (
                not _state_has_sanctuary_reserve(repaired)
                and isinstance(previous_result, Mapping)
                and previous_result.get("boot_id") == boot_id
                and previous_result.get("required_object_acquired") is True
            ):
                # A pre-repair checkpoint can retain a successful acquisition
                # after a later recovery segment consumed the reserve without
                # finding another carrier. Invalidate that stale result at
                # startup so resume cannot reopen the same route indefinitely.
                failed_result: dict[str, Any] = {
                    "observed": bool(
                        end.get("campaign_fastwalk_target_present_observed")
                    ),
                    "viable": False,
                    "completed_kill": False,
                    "retryable_failure": True,
                    "boot_id": boot_id,
                }
                if end.get("campaign_fastwalk_target_absent"):
                    failed_result["absent"] = True
                results[policy_id] = failed_result
                retry_cooldown = _research_absence_retry_cooldown(
                    policy_id,
                    default=_DEFAULT_RESEARCH_CROWD_COOLDOWN,
                )
                if retry_cooldown is not None:
                    absence_cooldowns[policy_id] = retry_cooldown
                crowd_cooldowns.pop(policy_id, None)
                changed = True
            continue

        restored_result = {
            "observed": True,
            "viable": True,
            "completed_kill": False,
            "required_object_acquired": True,
            "required_object_vnums": [4050],
            "boot_id": boot_id,
        }
        if results.get(policy_id) != restored_result:
            results[policy_id] = restored_result
            changed = True
        if policy_id in absence_cooldowns:
            absence_cooldowns.pop(policy_id, None)
            changed = True
        if policy_id in crowd_cooldowns:
            crowd_cooldowns.pop(policy_id, None)
            changed = True

    for policy_id, attempt in tuple(reconstructed_attempts.items()):
        if not isinstance(attempt, Mapping):
            reconstructed_attempts.pop(policy_id, None)
            changed = True
            continue
        if attempt.get("boot_id") != boot_id:
            continue
        try:
            attempt_count = int(attempt.get("count") or 0)
        except (TypeError, ValueError):
            attempt_count = 0
        if attempt_count < _SANCTUARY_RESOURCE_MAX_ATTEMPTS:
            continue
        if (
            (
                policy_id == _SOURCE_RANKED_SANCTUARY_RECOVERY_POLICY.policy_id
                and _sanctuary_resource_revalidation_pending(repaired)
            )
            or _sanctuary_combat_only_transit_revalidation_pending(
                repaired,
                policy_id=policy_id,
            )
        ):
            # A policy revision archives the old terminal result but keeps its
            # count for audit. Only the fresh segment may close this gate.
            results.pop(policy_id, None)
            continue
        result = results.get(policy_id)
        if not isinstance(result, Mapping):
            # Older checkpoints can retain the durable attempt counter while
            # losing the transient research result. The counter is still
            # authoritative: reconstruct a terminal result so startup cannot
            # reopen the same exhausted carrier route.
            latest_segment = latest_by_policy.get(policy_id)
            if latest_segment is not None:
                try:
                    latest_end = json.loads(
                        latest_segment.get("end_state_json") or "{}"
                    )
                except (TypeError, ValueError, json.JSONDecodeError):
                    latest_end = {}
                if (
                    isinstance(latest_end, Mapping)
                    and latest_end.get("world_boot_id") == boot_id
                ):
                    latest_result = _campaign_research_results(latest_end).get(
                        policy_id
                    )
                    if isinstance(latest_result, Mapping):
                        result = latest_result
            if not isinstance(result, Mapping):
                result = {
                    "observed": False,
                    "viable": False,
                    "completed_kill": False,
                    "boot_id": boot_id,
                }
        if (
            result.get("boot_id") != boot_id
            or result.get("required_object_acquired") is True
            or result.get("fatal_failure") is True
        ):
            continue
        fatal_result = dict(result)
        fatal_result["fatal_failure"] = True
        fatal_result["level"] = attempt.get("level")
        fatal_result["route_hazard"] = fatal_result.get(
            "route_hazard"
        ) or (
            "sanctuary resource route exhausted after "
            f"{_SANCTUARY_RESOURCE_MAX_ATTEMPTS} failed attempts"
        )
        fatal_result.pop("retryable_failure", None)
        results[policy_id] = fatal_result
        absence_cooldowns.pop(policy_id, None)
        changed = True

    if reconstructed_attempts != repaired.get(_SANCTUARY_RESOURCE_ATTEMPTS_KEY):
        changed = True
        if reconstructed_attempts:
            repaired[_SANCTUARY_RESOURCE_ATTEMPTS_KEY] = reconstructed_attempts
        else:
            repaired.pop(_SANCTUARY_RESOURCE_ATTEMPTS_KEY, None)

    if not changed:
        return repaired
    repaired["campaign_research_results"] = results
    if absence_cooldowns:
        repaired[_RESEARCH_ABSENCE_COOLDOWN_KEY] = absence_cooldowns
    else:
        repaired.pop(_RESEARCH_ABSENCE_COOLDOWN_KEY, None)
    if crowd_cooldowns:
        repaired[_RESEARCH_CROWD_COOLDOWN_KEY] = crowd_cooldowns
    else:
        repaired.pop(_RESEARCH_CROWD_COOLDOWN_KEY, None)
    return repaired


def _repair_source_food_funding_handoff(
    state: Mapping[str, Any],
) -> dict[str, Any]:
    """Clear a food-funding marker once a durable food supply is present."""
    repaired = dict(state)
    if not repaired.get(_PROVISION_FUNDING_REQUIRED_KEY):
        return repaired
    if "inventory" in repaired and _has_campaign_food(
        repaired,
        gear_catalog=None,
    ):
        # A previous unaffordable restock can leave this marker behind after a
        # later run has already restored pies. Do not let it force liquidation
        # ahead of ordinary progression while food is visibly available.
        repaired.pop(_PROVISION_FUNDING_REQUIRED_KEY, None)
        return repaired
    policy_id = str(repaired.get("campaign_last_policy") or "")
    if not policy_id.startswith("source-ranked-food-reserve-"):
        return repaired
    result = _campaign_research_results(repaired).get(policy_id)
    if not isinstance(result, Mapping):
        return repaired
    if result.get("required_object_acquired") is not True:
        return repaired
    repaired.pop(_PROVISION_FUNDING_REQUIRED_KEY, None)
    return repaired


def _verified_combat_potion_count(
    state: Mapping[str, Any],
    keyword: str,
) -> int:
    """Return one source-verified pouch count without trusting inventory text."""
    counts = state.get("verified_combat_pouch_potions") or {}
    if not isinstance(counts, Mapping):
        return 0
    try:
        return max(0, int(counts.get(keyword) or 0))
    except (TypeError, ValueError):
        return 0


def _state_has_sanctuary_reserve(state: Mapping[str, Any]) -> bool:
    """Return whether sanctuary is active, trained, or carried."""
    if _has_named_affect(state.get("affects"), "sanctuary"):
        # DD4's affect output uses duration 0 for "less than an hour". That
        # is still live mitigation, but it is not a durable reserve for a
        # future field route: the effect can disappear before the target
        # arrives. Require a positive or indefinite duration here; the live
        # starter continues to treat the effect as active until GMCP removes
        # it and can still finish a bounded fight during that final window.
        sanctuary_duration = _named_affect_duration(
            state.get("affects"),
            "sanctuary",
        )
        if sanctuary_duration is None or sanctuary_duration != 0:
            return True
    known_skills = state.get("campaign_known_skills") or ()
    if isinstance(known_skills, str):
        known_skills = (known_skills,)
    if any(str(skill).casefold() == "sanctuary" for skill in known_skills):
        return True
    known_skill_levels = state.get("campaign_known_skill_levels") or {}
    if isinstance(known_skill_levels, Mapping) and any(
        str(skill).casefold() == "sanctuary" for skill in known_skill_levels
    ):
        return True
    if _state_has_item(state.get("inventory"), "purple potion"):
        return True
    if _verified_combat_potion_count(state, "purple") > 0:
        return True
    try:
        return int(
            dict(state.get("combat_pouch_potions") or {}).get("purple", 0)
            or 0
        ) > 0
    except (TypeError, ValueError):
        return False


def _state_needs_combat_pouch_repack(state: Mapping[str, Any]) -> bool:
    """Detect a source-safe loose purple potion after a field abort."""
    if not _state_has_item(state.get("inventory"), "purple potion"):
        return False
    if _verified_combat_potion_count(state, "purple") > 0:
        return False
    try:
        if int(
            dict(state.get("combat_pouch_potions") or {}).get("purple", 0)
            or 0
        ) > 0:
            return False
    except (TypeError, ValueError):
        return False
    marker = state.get(_PROTECTION_RECOVERY_KEY)
    current_boot_marker = (
        isinstance(marker, Mapping)
        and marker.get("boot_id") == state.get("world_boot_id")
    )
    return bool(
        current_boot_marker
        or state.get("campaign_acquired_sanctuary_potion")
    )


def _state_has_blindness_recovery_reserve(
    state: Mapping[str, Any],
    *,
    required_purple_count: int = 2,
) -> bool:
    """Return whether the required source-verified blindness cure is carried."""
    if required_purple_count < 1:
        raise ValueError("required_purple_count must be positive")
    if state.get("campaign_cure_blindness_available") is True:
        return True
    known_skills = state.get("campaign_known_skills") or ()
    if isinstance(known_skills, str):
        known_skills = (known_skills,)
    if any(str(skill).casefold() == "cure blindness" for skill in known_skills):
        return True

    # DD4's verified purple potion is the currently source-identified
    # blindness cure. Count inventory entries as well as pouch entries because
    # the runner may not have stowed a newly acquired potion yet. Caster
    # specials request two copies because one is spent on sanctuary first;
    # non-sanctuary status routes need only the cure itself.
    potion_counts = dict(state.get("verified_combat_pouch_potions") or {})
    if not potion_counts:
        potion_counts = dict(state.get("combat_pouch_potions") or {})
    purple_count = 0
    try:
        purple_count = int(potion_counts.get("purple") or 0)
    except (TypeError, ValueError):
        purple_count = 0
    purple_count += sum(
        1
        for description in _inventory_descriptions(state.get("inventory"))
        if "purple potion" in description.casefold()
    )
    return purple_count >= required_purple_count


def _hard_health_floor_withdrawal(state: Mapping[str, Any]) -> bool:
    """Return whether a field fight ended at its explicit hard HP floor."""
    return str(state.get("campaign_fastwalk_abort_reason") or "").startswith(
        _HARD_HEALTH_ABORT_PREFIX
    )


def _protection_recovery_required(state: Mapping[str, Any]) -> bool:
    """Return whether the current-level hunt needs a protection upgrade."""
    record = state.get(_PROTECTION_RECOVERY_KEY)
    if not isinstance(record, Mapping):
        return False
    if record.get("boot_id") != state.get("world_boot_id"):
        return False
    # A hard-health withdrawal is durable audit evidence, but it belongs to
    # the level at which the exchange occurred.  Once the character advances,
    # keep the marker for history without blocking a new level's frontier.
    current_level = state.get("level")
    if (
        isinstance(current_level, (int, float))
        and record.get("level") not in {None, int(current_level)}
    ):
        return False
    return not _state_has_sanctuary_reserve(state)


def _current_protection_recovery_marker_present(
    state: Mapping[str, Any],
) -> bool:
    """Return whether protection evidence still belongs to this level/boot."""
    record = state.get(_PROTECTION_RECOVERY_KEY)
    if not isinstance(record, Mapping):
        return False
    if record.get("boot_id") != state.get("world_boot_id"):
        return False
    return record.get("level") in {None, _level(state)}


def _negative_fame_cure_critical_reserve_waiting(
    state: Mapping[str, Any],
) -> bool:
    """Return whether fame recovery is waiting for its blocked reserve route."""
    fame = _state_fame(state)
    if fame is None or fame >= 0:
        return False
    verified_pouch = dict(state.get("verified_combat_pouch_potions") or {})
    if (
        _verified_combat_potion_keyword_for_spell(
            verified_pouch,
            None,
            "cure critical",
        )
        is not None
    ):
        return False
    return _research_retry_cooldown_active(
        state,
        _SOURCE_RANKED_CURE_CRITICAL_RESERVE_POLICY.policy_id,
    )


def _campaign_sanctuary_recovery_required(state: dict[str, Any]) -> bool:
    """Return whether a current-reboot protected hunt still needs a reserve."""
    if _protection_recovery_required(state):
        return True
    boot_id = state.get("world_boot_id")
    results = _campaign_research_results(state)
    for policy_id in (
        _SHIRE_ELVEN_WIZARD_HUNT_POLICY_ID,
        _HIGHTOWER_JAILOR_HUNT_POLICY_ID,
        _SOLACE_LORD_DOOM_HUNT_POLICY_ID,
        _SOLACE_LORD_DOOM_SANCTUARY_HUNT_POLICY_ID,
    ):
        result = results.get(policy_id)
        if (
            isinstance(result, dict)
            and result.get("boot_id") == boot_id
            and result.get("completed_kill") is False
        ):
            return True
    return False


def _campaign_productive_sanctuary_handoff(
    state: dict[str, Any],
    *,
    character_class: str,
) -> str | None:
    """Keep a productive hunt running while a required Moria pass is crowded."""
    if character_class.casefold() != "thief" or _level(state) < 17:
        return None
    if (
        int(
            dict(state.get("combat_pouch_potions") or {}).get("purple", 0)
            or 0
        )
        > 0
        or _state_has_item(state.get("inventory"), "purple potion")
    ):
        return None
    if not _campaign_sanctuary_recovery_required(state):
        return None
    policy_id = _MORIA_SANCTUARY_THIEF_LEVEL_SEVENTEEN_POLICY_ID
    result = _campaign_research_results(state).get(policy_id)
    cooldowns = state.get(_RESEARCH_CROWD_COOLDOWN_KEY) or {}
    if not (
        isinstance(result, dict)
        and result.get("crowded") is True
        and result.get("boot_id") == state.get("world_boot_id")
        and isinstance(cooldowns, dict)
    ):
        return None
    try:
        if int(cooldowns.get(policy_id) or 0) <= 0:
            return None
    except (TypeError, ValueError):
        return None
    productive_policy_id = state.get(_LAST_PRODUCTIVE_POLICY_KEY)
    productive_result = (
        _campaign_research_results(state).get(productive_policy_id)
        if isinstance(productive_policy_id, str)
        else None
    )
    if not (
        isinstance(productive_policy_id, str)
        and "-hunt" in productive_policy_id
        and isinstance(productive_result, dict)
        and productive_result.get("boot_id") == state.get("world_boot_id")
        and productive_result.get("observed") is True
        and (
            (
                productive_result.get("viable") is True
                and productive_result.get("completed_kill") is not False
            )
            or (
                state.get(_LAST_PRODUCTIVE_POLICY_KEY) == productive_policy_id
                and productive_result.get("completed_kill") is False
            )
        )
    ):
        return None
    if productive_policy_id in {
        _SHIRE_ELVEN_WIZARD_HUNT_POLICY_ID,
        _HIGHTOWER_JAILOR_HUNT_POLICY_ID,
        _SOLACE_LORD_DOOM_HUNT_POLICY_ID,
        _SOLACE_LORD_DOOM_SANCTUARY_HUNT_POLICY_ID,
    }:
        # A crowd checkpoint must never bypass the progression safety gate
        # for a caster hunt that requires a currently carried potion.
        return None
    return productive_policy_id


def _campaign_below_band_policy_ids(
    state: dict[str, Any],
    *,
    level: int,
    boot_id: str | int | None,
) -> frozenset[str]:
    """Return policies rejected by live consider at this level and reboot."""
    raw = state.get(_BELOW_BAND_POLICY_EXCLUSIONS_KEY)
    if not isinstance(raw, dict):
        return frozenset()
    return frozenset(
        str(policy_id)
        for policy_id, record in raw.items()
        if isinstance(record, dict)
        and record.get("level") == level
        and record.get("boot_id") == boot_id
    )


def _source_mobile_key(value: Any) -> str | None:
    """Return the stable mobile-namespace identity for a candidate record."""
    if isinstance(value, HuntCandidate):
        mobile_vnum = value.mobile_vnum
    elif isinstance(value, Mapping):
        mobile_vnum = value.get("mobile_vnum")
    else:
        return None
    try:
        mobile_vnum = int(mobile_vnum or 0)
    except (TypeError, ValueError):
        return None
    if mobile_vnum <= 0:
        return None
    return f"mobile:{mobile_vnum}"


def _campaign_below_band_source_mobile_keys(
    state: Mapping[str, Any],
    *,
    level: int,
    boot_id: str | int | None,
) -> frozenset[str]:
    """Return source mobile identities rejected by live consider."""
    raw = state.get(_BELOW_BAND_POLICY_EXCLUSIONS_KEY)
    if not isinstance(raw, Mapping):
        return frozenset()
    keys: set[str] = set()
    for policy_id, record in raw.items():
        if (
            not isinstance(record, Mapping)
            or record.get("level") != level
            or record.get("boot_id") != boot_id
        ):
            continue
        source_keys = record.get("source_mobile_keys")
        if isinstance(source_keys, (list, tuple, set, frozenset)):
            keys.update(str(key) for key in source_keys if str(key))
        if not source_keys and str(policy_id).startswith(
            _SOURCE_RANKED_POLICY_PREFIX
        ):
            # Older checkpoints keyed source exclusions by reset policy only.
            # The source-ranked policy format ends with mobile, room, level;
            # recover the mobile VNUM so those checkpoints cannot replay a
            # sibling reset before the next level or reboot.
            match = re.search(r"-(\d+)-\d+-\d+$", str(policy_id))
            if match:
                keys.add(f"mobile:{match.group(1)}")
    return frozenset(keys)


def _source_ranked_candidate_excluded_by_below_band_evidence(
    candidate: HuntCandidate,
    state: Mapping[str, Any],
    *,
    character_level: int,
) -> bool:
    key = _source_mobile_key(candidate)
    if not key or key not in _campaign_below_band_source_mobile_keys(
        state,
        level=character_level,
        boot_id=state.get("world_boot_id"),
    ):
        return False

    # A later below-band sighting must not hide an exact reset that has since
    # produced a meaningful kill at this level and reboot. Keep this narrow:
    # sibling reset rooms sharing the mobile key remain excluded until their
    # own live evidence reopens them.
    if _source_ranked_below_band_exclusion_reopened_by_productive_result(
        candidate,
        state,
        character_level=character_level,
    ):
        return False

    # Older circuit migrations could preserve a source mobile key while
    # attaching a below-band name from a different stop. A source key is
    # useful evidence only when the recorded target identity agrees with the
    # candidate; key-only records remain authoritative for backwards
    # compatibility.
    raw_exclusions = state.get(_BELOW_BAND_POLICY_EXCLUSIONS_KEY)
    if not isinstance(raw_exclusions, Mapping):
        return True
    candidate_targets = {
        _source_ranked_normalized_target(value)
        for value in (
            candidate.target_identity,
            candidate.target,
            candidate.target_keyword,
        )
        if _source_ranked_normalized_target(value)
    }
    for policy_id, record in raw_exclusions.items():
        if not (
            isinstance(record, Mapping)
            and record.get("level") == character_level
            and record.get("boot_id") == state.get("world_boot_id")
        ):
            continue
        source_keys = record.get("source_mobile_keys")
        if isinstance(source_keys, (list, tuple, set, frozenset)):
            mentions_key = key in {str(value) for value in source_keys}
        else:
            mentions_key = False
        if not mentions_key and not str(policy_id).startswith(
            _SOURCE_RANKED_POLICY_PREFIX
        ):
            continue
        if not mentions_key:
            match = re.search(r"-(\d+)-\d+-\d+$", str(policy_id))
            mentions_key = bool(match and f"mobile:{match.group(1)}" == key)
        if not mentions_key:
            continue
        targets = record.get("targets")
        if not isinstance(targets, (list, tuple, set, frozenset)):
            return True
        normalized_targets = {
            _source_ranked_normalized_target(value)
            for value in targets
            if _source_ranked_normalized_target(value)
        }
        if not normalized_targets or candidate_targets.intersection(
            normalized_targets
        ):
            return True
    return False


def _below_band_sighting_pairs(value: Any) -> set[tuple[str, str]]:
    if not isinstance(value, (list, tuple, set)):
        return set()
    pairs: set[tuple[str, str]] = set()
    for sighting in value:
        if not isinstance(sighting, dict):
            continue
        room_vnum = sighting.get("room_vnum")
        target = sighting.get("target")
        if room_vnum is None or target is None:
            continue
        room = str(room_vnum).strip()
        target_name = str(target).strip().casefold()
        if room and target_name:
            pairs.add((room, target_name))
    return pairs


def _campaign_below_band_sightings(
    state: dict[str, Any],
    policy_id: str,
    *,
    level: int,
    boot_id: str | int | None,
) -> frozenset[tuple[str, str]]:
    raw = state.get(_BELOW_BAND_SIGHTINGS_KEY)
    if not isinstance(raw, dict):
        return frozenset()
    record = raw.get(policy_id)
    if (
        not isinstance(record, dict)
        or record.get("level") != level
        or record.get("boot_id") != boot_id
    ):
        return frozenset()
    return frozenset(_below_band_sighting_pairs(record.get("sightings")))


def _source_ranked_circuit_policy_records(
    candidate_record: object,
    *,
    primary_policy_id: str,
) -> tuple[Mapping[str, Any], ...]:
    """Return the serialized source candidates dispatched in one circuit."""
    if not isinstance(candidate_record, Mapping):
        return ()
    raw_circuit = candidate_record.get("circuit")
    circuit_records = (
        tuple(raw_circuit)
        if isinstance(raw_circuit, (list, tuple))
        else ()
    )
    records: list[Mapping[str, Any]] = []
    for raw_record in (
        candidate_record,
        *circuit_records,
    ):
        if not isinstance(raw_record, Mapping):
            continue
        policy_id = str(raw_record.get("policy_id") or "")
        if not policy_id and raw_record is candidate_record:
            policy_id = primary_policy_id
        if not policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX):
            continue
        if any(
            str(record.get("policy_id") or primary_policy_id) == policy_id
            for record in records
        ):
            continue
        if raw_record.get("policy_id") == policy_id:
            records.append(raw_record)
        else:
            records.append({**raw_record, "policy_id": policy_id})
    return tuple(records)


def _source_ranked_normalized_target(value: object) -> str:
    """Normalize only grammatical articles around a source mobile identity."""
    normalized = normalize_item_name(str(value or "")).strip(" .")
    return re.sub(r"^(?:a|an|the)\s+", "", normalized)


def _source_ranked_policy_id_for_target(
    candidate_record: object,
    target: object,
    *,
    primary_policy_id: str,
) -> str | None:
    """Resolve a live identity to one unambiguous serialized source policy."""
    observed = _source_ranked_normalized_target(target)
    if not observed:
        return None
    matches: list[str] = []
    for record in _source_ranked_circuit_policy_records(
        candidate_record,
        primary_policy_id=primary_policy_id,
    ):
        identities = {
            _source_ranked_normalized_target(record.get("target_identity")),
            _source_ranked_normalized_target(record.get("target")),
        } - {""}
        if observed not in identities:
            continue
        policy_id = str(record.get("policy_id") or "")
        if policy_id not in matches:
            matches.append(policy_id)
    return matches[0] if len(matches) == 1 else None


def _source_ranked_consider_outcomes_by_policy(
    state: Mapping[str, Any],
    *,
    primary_policy_id: str,
) -> dict[str, bool]:
    """Prefer runner-recorded stop IDs, with identity fallback for old runs."""
    records = _source_ranked_circuit_policy_records(
        state.get(_SOURCE_RANKED_CANDIDATE_KEY),
        primary_policy_id=primary_policy_id,
    )
    valid_policy_ids = {
        str(record.get("policy_id") or "") for record in records
    }
    direct = state.get(_SOURCE_CONSIDER_OUTCOMES_KEY)
    if isinstance(direct, Mapping):
        resolved = {
            str(policy_id): outcome
            for policy_id, outcome in direct.items()
            if str(policy_id) in valid_policy_ids
            and isinstance(outcome, bool)
        }
        if resolved:
            return resolved

    resolved: dict[str, bool] = {}
    outcomes = state.get("campaign_fastwalk_consider_outcomes")
    if not isinstance(outcomes, Mapping):
        return resolved
    for target, outcome in outcomes.items():
        if not isinstance(outcome, bool):
            continue
        policy_id = _source_ranked_policy_id_for_target(
            state.get(_SOURCE_RANKED_CANDIDATE_KEY),
            target,
            primary_policy_id=primary_policy_id,
        )
        if policy_id is not None:
            resolved[policy_id] = bool(outcome or resolved.get(policy_id))
    return resolved


def _source_ranked_below_band_sightings_by_policy(
    state: Mapping[str, Any],
    *,
    primary_policy_id: str,
) -> dict[str, set[tuple[str, str]]]:
    """Attribute below-band sightings to the exact source circuit stop."""
    records = _source_ranked_circuit_policy_records(
        state.get(_SOURCE_RANKED_CANDIDATE_KEY),
        primary_policy_id=primary_policy_id,
    )
    valid_policy_ids = {
        str(record.get("policy_id") or "") for record in records
    }
    resolved: dict[str, set[tuple[str, str]]] = {}
    direct = state.get(_SOURCE_BELOW_BAND_SIGHTINGS_KEY)
    if isinstance(direct, (list, tuple)):
        for sighting in direct:
            if not isinstance(sighting, Mapping):
                continue
            policy_id = str(sighting.get("policy_id") or "")
            room_vnum = str(sighting.get("room_vnum") or "")
            target = str(sighting.get("target") or "").casefold()
            if policy_id in valid_policy_ids and room_vnum and target:
                resolved.setdefault(policy_id, set()).add(
                    (room_vnum, target)
                )
        if resolved:
            return resolved

    for room_vnum, target in _below_band_sighting_pairs(
        state.get("campaign_fastwalk_below_band_sightings")
    ):
        policy_id = _source_ranked_policy_id_for_target(
            state.get(_SOURCE_RANKED_CANDIDATE_KEY),
            target,
            primary_policy_id=primary_policy_id,
        )
        if policy_id is not None:
            resolved.setdefault(policy_id, set()).add(
                (room_vnum, target)
            )
    return resolved


def _source_ranked_absent_policy_ids(
    state: Mapping[str, Any],
    *,
    primary_policy_id: str,
) -> tuple[str, ...]:
    """Resolve runner-recorded reset misses to exact circuit policies."""
    valid_policy_ids = set(
        _source_ranked_circuit_policy_ids(
            state.get(_SOURCE_RANKED_CANDIDATE_KEY),
            primary_policy_id=primary_policy_id,
        )
    )
    direct = state.get(_SOURCE_ABSENT_SIGHTINGS_KEY)
    if not isinstance(direct, (list, tuple)):
        return ()
    return tuple(
        dict.fromkeys(
            str(sighting.get("policy_id") or "")
            for sighting in direct
            if isinstance(sighting, Mapping)
            and str(sighting.get("policy_id") or "") in valid_policy_ids
        )
    )


def _source_ranked_present_policy_ids(
    state: Mapping[str, Any],
    *,
    primary_policy_id: str,
) -> tuple[str, ...]:
    """Resolve runner-recorded live sightings to exact circuit policies."""
    valid_policy_ids = set(
        _source_ranked_circuit_policy_ids(
            state.get(_SOURCE_RANKED_CANDIDATE_KEY),
            primary_policy_id=primary_policy_id,
        )
    )
    direct = state.get(_SOURCE_PRESENT_SIGHTINGS_KEY)
    if not isinstance(direct, (list, tuple)):
        return ()
    return tuple(
        dict.fromkeys(
            str(sighting.get("policy_id") or "")
            for sighting in direct
            if isinstance(sighting, Mapping)
            and str(sighting.get("policy_id") or "") in valid_policy_ids
        )
    )


def _merge_campaign_below_band_policy_exclusions(
    previous: dict[str, Any],
    current: dict[str, Any],
    *,
    policy: ProgressionPolicy,
    level: int,
    boot_id: str | int | None,
) -> dict[str, Any]:
    """Persist live below-band rejections until level or reboot changes."""
    merged = dict(current)
    raw = previous.get(_BELOW_BAND_POLICY_EXCLUSIONS_KEY)
    exclusions = {
        str(policy_id): dict(record)
        for policy_id, record in (raw.items() if isinstance(raw, dict) else ())
        if isinstance(record, dict)
        and record.get("level") == level
        and record.get("boot_id") == boot_id
    }
    previous_sightings = previous.get(_BELOW_BAND_SIGHTINGS_KEY)
    sightings_by_policy: dict[str, set[tuple[str, str]]] = {}
    if isinstance(previous_sightings, dict):
        for policy_id, record in previous_sightings.items():
            if (
                isinstance(record, dict)
                and record.get("level") == level
                and record.get("boot_id") == boot_id
            ):
                pairs = _below_band_sighting_pairs(record.get("sightings"))
                if pairs:
                    sightings_by_policy[str(policy_id)] = pairs
    current_sightings = _below_band_sighting_pairs(
        current.get("campaign_fastwalk_below_band_sightings")
    )
    candidate_record = current.get(_SOURCE_RANKED_CANDIDATE_KEY)
    source_ranked_dispatch = bool(
        policy.execution == "source-ranked-hunt"
        and isinstance(candidate_record, Mapping)
        and candidate_record.get("policy_id") == policy.policy_id
    )
    source_sightings = (
        _source_ranked_below_band_sightings_by_policy(
            current,
            primary_policy_id=policy.policy_id,
        )
        if source_ranked_dispatch
        else {}
    )
    for source_policy_id, pairs in source_sightings.items():
        sightings_by_policy.setdefault(source_policy_id, set()).update(pairs)
    if current_sightings and not source_sightings:
        sightings_by_policy.setdefault(policy.policy_id, set()).update(
            current_sightings
        )

    targets = current.get("campaign_fastwalk_below_band_targets")
    raw_targets = (
        [str(target).casefold() for target in targets]
        if isinstance(targets, (list, tuple, set))
        else []
    )
    targets_by_policy: dict[str, set[str]] = {
        source_policy_id: {target for _, target in pairs}
        for source_policy_id, pairs in source_sightings.items()
    }
    for target in raw_targets:
        source_policy_id = (
            _source_ranked_policy_id_for_target(
                candidate_record,
                target,
                primary_policy_id=policy.policy_id,
            )
            if source_ranked_dispatch
            else None
        )
        targets_by_policy.setdefault(
            source_policy_id or policy.policy_id,
            set(),
        ).add(target)

    candidate_records = {
        str(record.get("policy_id") or ""): record
        for record in _source_ranked_circuit_policy_records(
            candidate_record,
            primary_policy_id=policy.policy_id,
        )
    }

    if policy.allow_partial_below_band:
        outcomes = current.get("campaign_fastwalk_consider_outcomes")
        has_viable_stop = isinstance(outcomes, dict) and any(
            value is True for value in outcomes.values()
        )
        below_band_evidence = (
            raw_targets
            if raw_targets
            else [target for _, target in current_sightings]
        )
        if below_band_evidence and not has_viable_stop:
            # A multi-stop hunt may tolerate one below-band mobile only when
            # another stop remains inside the useful XP band.
            record = dict(exclusions.get(policy.policy_id) or {})
            record.update({
                "level": level,
                "boot_id": boot_id,
                "targets": sorted(
                    {str(target).casefold() for target in below_band_evidence}
                ),
            })
            current_record = candidate_records.get(policy.policy_id)
            if current_record is not None:
                source_keys = {
                    str(key)
                    for key in record.get("source_mobile_keys") or ()
                }
                source_keys.add(_source_mobile_key(current_record))
                record["source_mobile_keys"] = sorted(source_keys)
            exclusions[policy.policy_id] = record
        else:
            exclusions.pop(policy.policy_id, None)
    else:
        for source_policy_id, source_targets in targets_by_policy.items():
            if not source_targets:
                continue
            record = dict(exclusions.get(source_policy_id) or {})
            retained_targets = {
                str(target).casefold()
                for target in record.get("targets") or ()
            }
            retained_targets.update(source_targets)
            record.update({
                "level": level,
                "boot_id": boot_id,
                "targets": sorted(retained_targets),
            })
            current_record = candidate_records.get(source_policy_id)
            if current_record is not None:
                source_keys = {
                    str(key)
                    for key in record.get("source_mobile_keys") or ()
                }
                source_keys.add(_source_mobile_key(current_record))
                record["source_mobile_keys"] = sorted(source_keys)
            exclusions[source_policy_id] = record
    if exclusions:
        merged[_BELOW_BAND_POLICY_EXCLUSIONS_KEY] = exclusions
    else:
        merged.pop(_BELOW_BAND_POLICY_EXCLUSIONS_KEY, None)
    if sightings_by_policy:
        merged[_BELOW_BAND_SIGHTINGS_KEY] = {
            policy_id: {
                "level": level,
                "boot_id": boot_id,
                "sightings": [
                    {"room_vnum": room_vnum, "target": target}
                    for room_vnum, target in sorted(pairs)
                ],
            }
            for policy_id, pairs in sorted(sightings_by_policy.items())
        }
    else:
        merged.pop(_BELOW_BAND_SIGHTINGS_KEY, None)
    return merged


def _merge_protection_recovery_metadata(
    current: dict[str, Any],
    *,
    policy: ProgressionPolicy,
    xp_delta: int,
    previous: Mapping[str, Any] | None = None,
    loss_event_id: Any = None,
) -> dict[str, Any]:
    """Remember a costly failed hunt until progress restores its gate."""
    updated = dict(current)
    existing = updated.get(_PROTECTION_RECOVERY_KEY)
    existing_hard_health_marker = bool(
        isinstance(existing, Mapping)
        and existing.get("trigger")
        == _PROTECTION_RECOVERY_HARD_HEALTH_TRIGGER
    )
    objective_kills = updated.get("campaign_objective_kills")
    positive_objective_kill = bool(
        xp_delta > 0
        and isinstance(objective_kills, (list, tuple))
        and objective_kills
    )
    source_kill_policy_ids = (
        set(_source_ranked_kill_policy_ids(objective_kills))
        if positive_objective_kill
        else set()
    )
    if source_kill_policy_ids:
        updated = _clear_source_ranked_xp_loss(
            updated,
            policy_ids=source_kill_policy_ids,
        )
        partial_retry = updated.get(_SOURCE_RANKED_PARTIAL_TIMEOUT_RETRY_KEY)
        if (
            isinstance(partial_retry, Mapping)
            and partial_retry.get("policy_id") in source_kill_policy_ids
        ):
            updated.pop(_SOURCE_RANKED_PARTIAL_TIMEOUT_RETRY_KEY, None)
        retry_marker = updated.get(_PROTECTION_RECOVERY_RETRY_KEY)
        if (
            isinstance(retry_marker, Mapping)
            and retry_marker.get("policy_id") in source_kill_policy_ids
        ):
            updated.pop(_PROTECTION_RECOVERY_RETRY_KEY, None)
    if positive_objective_kill and policy.status in {"research", "verified"}:
        # Fixed class routes use their policy id as the durable identity. A
        # positive objective kill is stronger than an earlier withdrawal from
        # that route, so let the measured route re-enter the next rotation.
        updated = _clear_registered_research_xp_loss(
            updated,
            policy_ids=(policy.policy_id,),
        )
    ordinary_fallback = updated.get(
        _PROTECTION_RECOVERY_ORDINARY_FALLBACK_KEY
    )
    if (
        positive_objective_kill
        and isinstance(ordinary_fallback, Mapping)
        and ordinary_fallback.get("boot_id") == updated.get("world_boot_id")
        and ordinary_fallback.get("policy_id") == policy.policy_id
    ):
        # A bounded low-peak kill is the explicit success condition for this
        # no-reserve fallback.  Clear both one-shot metadata and the older
        # protection marker so the normal source frontier can resume.
        updated.pop(_PROTECTION_RECOVERY_ORDINARY_FALLBACK_KEY, None)
        updated.pop(_PROTECTION_RECOVERY_KEY, None)
        return updated
    if (
        positive_objective_kill
        and isinstance(ordinary_fallback, Mapping)
        and ordinary_fallback.get("boot_id")
        == updated.get("world_boot_id")
        and not existing_hard_health_marker
    ):
        # Any productive independent source kill satisfies the ordinary loss
        # recovery boundary. Do not leave a different candidate's fallback
        # marker behind after the parent protection requirement is cleared.
        updated.pop(_PROTECTION_RECOVERY_ORDINARY_FALLBACK_KEY, None)
    same_policy_recovery = bool(
        positive_objective_kill
        and isinstance(existing, Mapping)
        and existing.get("policy_id") == policy.policy_id
    )
    if same_policy_recovery or (
        positive_objective_kill and not existing_hard_health_marker
    ):
        updated.pop(_PROTECTION_RECOVERY_KEY, None)
        retry_marker = updated.get(_PROTECTION_RECOVERY_RETRY_KEY)
        if (
            isinstance(retry_marker, Mapping)
            and retry_marker.get("policy_id") == policy.policy_id
        ):
            updated.pop(_PROTECTION_RECOVERY_RETRY_KEY, None)
        return updated
    execution = str(policy.execution or "")
    loss_observed = bool(
        xp_delta < 0
        or (
            previous is not None
            and _xp_loss_event_observed(previous, updated)
        )
    )
    if not updated.get("campaign_objective_kills") and loss_observed:
        source_policy_ids = (
            (policy.policy_id,)
            if execution == "source-ranked-hunt"
            else (
                _source_ranked_policy_ids_from_fastwalk_state(updated)
                if execution == "provision-funding"
                else ()
            )
        )
        for source_policy_id in source_policy_ids:
            updated = _remember_source_ranked_xp_loss(
                updated,
                policy_id=source_policy_id,
                level=_level(updated),
                boot_id=updated.get("world_boot_id"),
                xp_delta=xp_delta,
                loss_event_id=loss_event_id,
                sanctuary_protected=(
                    _source_ranked_loss_used_sanctuary(updated)
                ),
            )
        if (
            policy.status in {"research", "verified"}
            and execution not in _MAINTENANCE_EXECUTIONS
            and execution != "provision-funding"
        ):
            updated = _remember_registered_research_xp_loss(
                updated,
                policy_id=policy.policy_id,
                level=_level(updated),
                boot_id=updated.get("world_boot_id"),
                xp_delta=xp_delta,
                loss_event_id=loss_event_id,
            )
    partial_timeout_retry = _source_ranked_partial_timeout_retry_record(
        previous,
        updated,
        policy=policy,
        xp_delta=xp_delta,
        loss_event_id=loss_event_id,
    )
    if partial_timeout_retry is not None:
        updated[_SOURCE_RANKED_PARTIAL_TIMEOUT_RETRY_KEY] = (
            partial_timeout_retry
        )
    outcomes = updated.get("campaign_fastwalk_consider_outcomes")
    viable = isinstance(outcomes, Mapping) and any(
        value is True for value in outcomes.values()
    )
    hard_health_withdrawal = _hard_health_floor_withdrawal(updated)
    fallback_matches = bool(
        isinstance(ordinary_fallback, Mapping)
        and ordinary_fallback.get("boot_id") == updated.get("world_boot_id")
        and ordinary_fallback.get("policy_id") == policy.policy_id
    )
    if fallback_matches and (loss_observed or hard_health_withdrawal):
        # An actual failed exchange consumes the recovery fallback. Absent,
        # crowded, and route-only probes keep rotating through their bounded
        # distinct-policy budget because they did not test combat viability.
        updated[_PROTECTION_RECOVERY_ORDINARY_FALLBACK_KEY] = {
            **dict(ordinary_fallback),
            "attempted": True,
            "failed": True,
        }
    if (
        policy.status == "research"
        and execution.endswith("-hunt")
        and not updated.get("campaign_objective_kills")
        and viable
        and (loss_observed or hard_health_withdrawal)
        and updated.get("world_boot_id") is not None
    ):
        marker = {
            "boot_id": updated.get("world_boot_id"),
            "level": _level(updated),
            "policy_id": policy.policy_id,
            "xp_delta": xp_delta,
            "reason": (
                "viable hunt reached the hard health floor before a kill"
                if hard_health_withdrawal
                else "viable hunt withdrew with an XP loss before a kill"
            ),
        }
        if hard_health_withdrawal:
            marker["trigger"] = _PROTECTION_RECOVERY_HARD_HEALTH_TRIGGER
        updated[_PROTECTION_RECOVERY_KEY] = marker
        return updated
    if _state_has_sanctuary_reserve(updated):
        if not existing_hard_health_marker:
            updated.pop(_PROTECTION_RECOVERY_KEY, None)
        return updated
    return updated


def _merge_campaign_research_result(
    previous: dict[str, Any],
    current: dict[str, Any],
    *,
    policy: ProgressionPolicy,
) -> dict[str, Any]:
    """Persist one reboot-scoped live consideration for research promotion."""
    merged = dict(current)
    results = _campaign_research_results(previous)
    absence_cooldowns = dict(
        previous.get(_RESEARCH_ABSENCE_COOLDOWN_KEY) or {}
    )
    crowd_cooldowns = dict(
        previous.get(_RESEARCH_CROWD_COOLDOWN_KEY) or {}
    )
    source_ranked_crowd_attempts = dict(
        previous.get(_SOURCE_RANKED_CROWD_ATTEMPTS_KEY) or {}
    )
    sanctuary_resource_attempts = dict(
        previous.get(_SANCTUARY_RESOURCE_ATTEMPTS_KEY) or {}
    )
    cleared_research_policies = {
        str(policy_id)
        for policy_id in previous.get(_CLEARED_RESEARCH_POLICIES_KEY, ())
    }
    recorded_current_result = False
    if policy.status == "research":
        outcomes = current.get("campaign_fastwalk_consider_outcomes")
        viable = None
        if isinstance(outcomes, dict):
            boolean_outcomes = [
                value for value in outcomes.values() if isinstance(value, bool)
            ]
            if boolean_outcomes:
                viable = any(boolean_outcomes)
        target_present_observed = bool(
            current.get("campaign_fastwalk_target_present_observed")
        )
        acquired_required_object_vnums: tuple[int, ...] = ()
        raw_acquired_required_object_vnums = current.get(
            "campaign_fastwalk_required_object_vnums"
        )
        if isinstance(
            raw_acquired_required_object_vnums,
            (list, tuple, set, frozenset),
        ):
            parsed_acquired_required_object_vnums: set[int] = set()
            for raw_vnum in raw_acquired_required_object_vnums:
                try:
                    parsed_acquired_required_object_vnums.add(int(raw_vnum))
                except (TypeError, ValueError):
                    continue
            acquired_required_object_vnums = tuple(
                sorted(parsed_acquired_required_object_vnums)
            )
        source_consumable_spell = str(
            current.get(_SOURCE_CONSUMABLE_SPELL_KEY) or ""
        ).casefold()
        alternate_sanctuary_acquisition = bool(
            source_consumable_spell == "sanctuary"
            and acquired_required_object_vnums
            and policy.execution
            in {
                "moria-sanctuary-hunt",
                "moria-deep-sanctuary-hunt",
            }
        )
        sanctuary_resource_acquisition = bool(
            policy.execution
            in {
                "moria-sanctuary-hunt",
                "moria-deep-sanctuary-hunt",
            }
            and _verified_combat_potion_count(current, "purple")
            > _verified_combat_potion_count(previous, "purple")
        )
        resource_acquisition = bool(
            (
                (
                    acquired_required_object_vnums
                    and policy.execution
                    in {
                        "source-ranked-food-reserve",
                        "source-ranked-cure-critical-reserve",
                    }
                )
                or alternate_sanctuary_acquisition
                or sanctuary_resource_acquisition
            )
            and not current.get("campaign_died_during_segment")
        )
        fastwalk_abort_reason = str(
            current.get("campaign_fastwalk_abort_reason") or ""
        )
        hunt_without_confirmed_kill = bool(
            (
                str(policy.execution or "").endswith("-hunt")
                or policy.execution
                in {
                    "fame-recovery-circus",
                    "fame-recovery",
                    "fame-recovery-lotus",
                }
            )
            and not current.get("campaign_objective_kills")
        )
        unobserved_hunt = bool(
            hunt_without_confirmed_kill
            and viable is None
            and not current.get("campaign_fastwalk_consider_outcomes")
            and not target_present_observed
            and not current.get("campaign_fastwalk_target_absent")
            and not current.get("campaign_fastwalk_abort_reason")
            and not current.get("campaign_fastwalk_unattackable_target")
            and not current.get("campaign_fastwalk_target_vnum_mismatch")
        )
        unobserved_moria_deep_probe = bool(
            policy.policy_id == _MORIA_DEEP_SANCTUARY_THIEF_PROBE_POLICY_ID
            and viable is None
            and not current.get("campaign_fastwalk_consider_outcomes")
            and not target_present_observed
            and not current.get("campaign_fastwalk_target_absent")
            and not current.get("campaign_fastwalk_abort_reason")
            and not current.get("campaign_fastwalk_unattackable_target")
            and not current.get("campaign_fastwalk_target_vnum_mismatch")
        )
        unattackable_target = current.get(
            "campaign_fastwalk_unattackable_target"
        )
        target_vnum_mismatch = current.get(
            "campaign_fastwalk_target_vnum_mismatch"
        )
        crowded_field = bool(
            current.get("campaign_fastwalk_crowded")
            or any(
                fastwalk_abort_reason.startswith(prefix)
                for prefix in _FIELD_CROWD_ABORT_PREFIXES
            )
        )
        route_hazard = any(
            fastwalk_abort_reason.startswith(prefix)
            for prefix in _FIELD_ROUTE_HAZARD_ABORT_PREFIXES
        )
        protection_required = (
            _FIELD_REQUIRED_SANCTUARY_ABORT_FRAGMENT in fastwalk_abort_reason
        )
        if resource_acquisition:
            # Required-object acquisition is positive evidence for resource
            # routes even when the generic fastwalk target flag was stale.
            merged["campaign_fastwalk_target_absent"] = False
            merged["campaign_fastwalk_target_present_observed"] = True
            results[policy.policy_id] = {
                "observed": True,
                "viable": True,
                "completed_kill": False,
                "required_object_acquired": True,
                "required_object_vnums": list(
                    acquired_required_object_vnums
                    or ((4050,) if sanctuary_resource_acquisition else ())
                ),
                "boot_id": current.get("world_boot_id"),
            }
            absence_cooldowns.pop(policy.policy_id, None)
            crowd_cooldowns.pop(policy.policy_id, None)
            source_ranked_crowd_attempts.pop(policy.policy_id, None)
            recorded_current_result = True
            if policy.execution == "source-ranked-food-reserve":
                # The food route consumes the acquired item before returning
                # home. Clear the stale funding handoff so the next segment
                # can restock or resume field work instead of replaying a
                # money hunt after successful food recovery.
                merged.pop(_PROVISION_FUNDING_REQUIRED_KEY, None)
        elif route_hazard:
            result = {
                "observed": False,
                "viable": False,
                "route_hazard": fastwalk_abort_reason,
                "boot_id": current.get("world_boot_id"),
            }
            if _shadow_grove_route_hazard_observed(
                policy.policy_id,
                current,
                fastwalk_abort_reason,
            ):
                merged[_SHADOW_GROVE_ROUTE_HAZARD_KEY] = {
                    "boot_id": current.get("world_boot_id"),
                    "policy_id": policy.policy_id,
                    "route_hazard": fastwalk_abort_reason,
                    "source": "live_segment",
                }
            if (
                (
                    policy.policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX)
                    or policy.policy_id
                    in {
                        _SOURCE_RANKED_SANCTUARY_RESERVE_POLICY.policy_id,
                        _SOURCE_RANKED_SANCTUARY_RECOVERY_POLICY.policy_id,
                    }
                )
                and _is_retryable_dynamic_route_hazard(
                    policy.policy_id,
                    fastwalk_abort_reason,
                )
            ):
                result["retryable_failure"] = True
            results[policy.policy_id] = result
            recorded_current_result = True
            if _is_retryable_dynamic_route_hazard(
                policy.policy_id,
                fastwalk_abort_reason,
            ):
                retry_cooldown = _research_absence_retry_cooldown(
                    policy.policy_id
                )
                if retry_cooldown is not None:
                    absence_cooldowns[policy.policy_id] = retry_cooldown
            else:
                absence_cooldowns.pop(policy.policy_id, None)
            crowd_cooldowns.pop(policy.policy_id, None)
        elif crowded_field:
            previous_result = results.get(policy.policy_id)
            preserve_positive_result = (
                isinstance(previous_result, dict)
                and current.get("world_boot_id") is not None
                and previous_result.get("boot_id") == current.get("world_boot_id")
                and previous_result.get("viable") is True
                and previous_result.get("completed_kill") is not False
            )

            def record_source_ranked_crowd_attempt(
                result: dict[str, Any],
            ) -> None:
                if not policy.policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX):
                    return
                previous_attempt = source_ranked_crowd_attempts.get(
                    policy.policy_id
                )
                try:
                    attempt_count = (
                        int(previous_attempt.get("count") or 0)
                        if isinstance(previous_attempt, dict)
                        and previous_attempt.get("boot_id")
                        == current.get("world_boot_id")
                        else 0
                    )
                except (TypeError, ValueError):
                    attempt_count = 0
                if (
                    attempt_count == 0
                    and previous.get("campaign_fastwalk_crowded")
                    and previous.get("campaign_last_policy")
                    == policy.policy_id
                ):
                    # Checkpoints created before this counter existed
                    # already contain one crowd observation. Preserve it
                    # during the first post-upgrade merge.
                    attempt_count = _SOURCE_RANKED_CROWD_ROTATION_THRESHOLD - 1
                attempt_count += 1
                source_ranked_crowd_attempts[policy.policy_id] = {
                    "boot_id": current.get("world_boot_id"),
                    "count": attempt_count,
                }
                if attempt_count >= _SOURCE_RANKED_CROWD_ROTATION_THRESHOLD:
                    result["crowd_exhausted"] = True

            if not preserve_positive_result:
                results[policy.policy_id] = {
                    "observed": False,
                    "viable": False,
                    "crowded": True,
                    "boot_id": current.get("world_boot_id"),
                }
                record_source_ranked_crowd_attempt(
                    results[policy.policy_id]
                )
                crowd_cooldowns[policy.policy_id] = (
                    _DEFAULT_RESEARCH_CROWD_COOLDOWN
                )
                absence_cooldowns.pop(policy.policy_id, None)
            elif policy.policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX):
                preserved_result = dict(previous_result)
                # Keep the positive kill evidence for later same-reboot use,
                # but make the current crowd a temporary selection gate.
                preserved_result["crowded"] = True
                record_source_ranked_crowd_attempt(preserved_result)
                results[policy.policy_id] = preserved_result
                crowd_cooldowns[policy.policy_id] = (
                    _DEFAULT_RESEARCH_CROWD_COOLDOWN
                )
                absence_cooldowns.pop(policy.policy_id, None)
            else:
                absence_cooldowns.pop(policy.policy_id, None)
                crowd_cooldowns.pop(policy.policy_id, None)
                source_ranked_crowd_attempts.pop(policy.policy_id, None)
            recorded_current_result = True
        elif unattackable_target:
            results[policy.policy_id] = {
                "observed": viable is not None,
                "viable": False,
                "unattackable": str(unattackable_target),
                "boot_id": current.get("world_boot_id"),
            }
            recorded_current_result = True
            absence_cooldowns.pop(policy.policy_id, None)
            crowd_cooldowns.pop(policy.policy_id, None)
            source_ranked_crowd_attempts.pop(policy.policy_id, None)
        elif target_vnum_mismatch:
            results[policy.policy_id] = {
                "observed": target_present_observed,
                "viable": False,
                "target_vnum_mismatch": target_vnum_mismatch,
                "boot_id": current.get("world_boot_id"),
            }
            recorded_current_result = True
            absence_cooldowns.pop(policy.policy_id, None)
            crowd_cooldowns.pop(policy.policy_id, None)
            source_ranked_crowd_attempts.pop(policy.policy_id, None)
        aborted_without_consider = bool(
            current.get("campaign_fastwalk_abort_reason")
            and viable is None
            and not current.get("campaign_fastwalk_target_absent")
        )
        source_ranked_route_abort = bool(
            policy.execution == "source-ranked-hunt"
            and aborted_without_consider
        )
        if resource_acquisition:
            pass
        elif (
            route_hazard
            or crowded_field
            or unattackable_target
            or target_vnum_mismatch
        ):
            pass
        elif source_ranked_route_abort:
            result = {
                "observed": False,
                "viable": False,
                "route_hazard": fastwalk_abort_reason,
                "boot_id": current.get("world_boot_id"),
            }
            if _is_retryable_dynamic_route_hazard(
                policy.policy_id,
                fastwalk_abort_reason,
            ):
                result["retryable_failure"] = True
            results[policy.policy_id] = result
            recorded_current_result = True
            retry_cooldown = _research_absence_retry_cooldown(
                policy.policy_id,
                default=_DEFAULT_RESEARCH_CROWD_COOLDOWN,
            )
            if retry_cooldown is not None:
                absence_cooldowns[policy.policy_id] = retry_cooldown
            crowd_cooldowns.pop(policy.policy_id, None)
            source_ranked_crowd_attempts.pop(policy.policy_id, None)
        elif aborted_without_consider:
            if policy.execution in {
                "moria-sanctuary-hunt",
                "moria-deep-sanctuary-hunt",
            }:
                # A bounded Moria recovery can reach its safe return boundary
                # without finding a new carrier. Do not let the prior
                # successful acquisition result survive that attempt: it
                # would make the selector reopen the same 180-second route
                # indefinitely after the potion has been consumed.
                results[policy.policy_id] = {
                    "observed": target_present_observed,
                    "viable": False,
                    "completed_kill": False,
                    "retryable_failure": True,
                    "boot_id": current.get("world_boot_id"),
                }
                recorded_current_result = True
                retry_cooldown = _research_absence_retry_cooldown(
                    policy.policy_id,
                    default=_DEFAULT_RESEARCH_CROWD_COOLDOWN,
                )
                if retry_cooldown is not None:
                    absence_cooldowns[policy.policy_id] = retry_cooldown
                crowd_cooldowns.pop(policy.policy_id, None)
                source_ranked_crowd_attempts.pop(policy.policy_id, None)
        elif (
            current.get("campaign_fastwalk_target_absent")
            and viable is None
            and not target_present_observed
        ):
            results[policy.policy_id] = {
                "observed": False,
                "viable": False,
                "absent": True,
                "boot_id": current.get("world_boot_id"),
            }
            recorded_current_result = True
            retry_cooldown = _research_absence_retry_cooldown(
                policy.policy_id
            )
            if retry_cooldown is not None:
                absence_cooldowns[policy.policy_id] = retry_cooldown
            crowd_cooldowns.pop(policy.policy_id, None)
            source_ranked_crowd_attempts.pop(policy.policy_id, None)
        elif unobserved_moria_deep_probe:
            # The deep sanctuary probe uses a research execution rather than
            # a ``-hunt`` execution, so it does not enter ``unobserved_hunt``.
            # Preserve an explicit absence record or policy revision cleanup
            # will erase the failed probe and immediately reopen it.
            results[policy.policy_id] = {
                "observed": False,
                "viable": False,
                "absent": True,
                "boot_id": current.get("world_boot_id"),
            }
            recorded_current_result = True
            retry_cooldown = _research_absence_retry_cooldown(
                policy.policy_id,
            )
            if retry_cooldown is not None:
                absence_cooldowns[policy.policy_id] = retry_cooldown
            crowd_cooldowns.pop(policy.policy_id, None)
            source_ranked_crowd_attempts.pop(policy.policy_id, None)
        elif protection_required:
            results[policy.policy_id] = {
                "observed": viable is not None or target_present_observed,
                "viable": viable is True,
                "completed_kill": False,
                "protection_required": "sanctuary",
                "boot_id": current.get("world_boot_id"),
            }
            recorded_current_result = True
            absence_cooldowns.pop(policy.policy_id, None)
            crowd_cooldowns.pop(policy.policy_id, None)
            source_ranked_crowd_attempts.pop(policy.policy_id, None)
        elif hunt_without_confirmed_kill:
            # A positive consider proves only that the target was worth
            # probing. A research hunt is not viable until the runner records
            # the deliberate kill, even if the character dealt partial damage
            # before a safe withdrawal.
            result = {
                "observed": viable is not None or target_present_observed,
                "viable": False,
                "completed_kill": False,
                "boot_id": current.get("world_boot_id"),
            }
            if policy.execution == "source-ranked-hunt" and viable is not None:
                result["consider_viable"] = viable is True
            if unobserved_hunt:
                # A bounded hunt that never produced a live consideration did
                # not find a target to fight. Treat it as temporary absence so
                # the scheduler rotates to another policy instead of replaying
                # an empty, movement-expensive circuit immediately.
                result["absent"] = True
                result["unobserved"] = True
                retry_cooldown = _research_absence_retry_cooldown(
                    policy.policy_id
                )
                if retry_cooldown is not None:
                    absence_cooldowns[policy.policy_id] = retry_cooldown
            elif policy.execution == "source-ranked-hunt" and viable is False:
                # A negative live consider is terminal at this character
                # level and reboot. Do not attach a short route retry that
                # can later revive a below-band or over-ceiling target.
                absence_cooldowns.pop(policy.policy_id, None)
            else:
                previous_result = results.get(policy.policy_id)
                same_boot = bool(
                    current.get("world_boot_id") is not None
                    and (
                        previous_result is None
                        or (
                            isinstance(previous_result, dict)
                            and previous_result.get("boot_id")
                            == current.get("world_boot_id")
                        )
                    )
                )
                previously_productive = bool(
                    same_boot
                    and (
                        policy.policy_id
                        in _state_productive_policy_ids(previous)
                        or (
                            isinstance(previous_result, dict)
                            and previous_result.get("viable") is True
                            and previous_result.get("completed_kill") is not False
                        )
                    )
                )
                if previously_productive and viable is True:
                    # Preserve positive same-reboot history, but do not replay
                    # a route that just failed to finish its target.
                    result["retryable_failure"] = True
                    result["previously_productive"] = True
                    retry_cooldown = _research_absence_retry_cooldown(
                        policy.policy_id,
                        default=_DEFAULT_RESEARCH_CROWD_COOLDOWN,
                    )
                    absence_cooldowns[policy.policy_id] = retry_cooldown
                else:
                    # A present target that survived a bounded attempt needs
                    # the same short rotation as a previously productive one;
                    # otherwise the generic selector can immediately replay it.
                    if (
                        policy.policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX)
                        or policy.policy_id
                        == _SOURCE_RANKED_SANCTUARY_RESERVE_POLICY.policy_id
                        or policy.policy_id
                        == _SOURCE_RANKED_SANCTUARY_RECOVERY_POLICY.policy_id
                        or policy.policy_id
                        == _MORIA_SANCTUARY_THIEF_LEVEL_SEVENTEEN_POLICY_ID
                        or policy.policy_id
                        in {
                            _FAME_RECOVERY_CIRCUS_POLICY.policy_id,
                            _FAME_RECOVERY_POLICY.policy_id,
                            _FAME_RECOVERY_LOTUS_POLICY.policy_id,
                        }
                    ):
                        result["retryable_failure"] = True
                        retry_cooldown = _research_absence_retry_cooldown(
                            policy.policy_id,
                            default=_DEFAULT_RESEARCH_CROWD_COOLDOWN,
                        )
                        absence_cooldowns[policy.policy_id] = retry_cooldown
                    else:
                        absence_cooldowns.pop(policy.policy_id, None)
            results[policy.policy_id] = result
            recorded_current_result = True
            crowd_cooldowns.pop(policy.policy_id, None)
            source_ranked_crowd_attempts.pop(policy.policy_id, None)
        else:
            result = {
                "observed": viable is not None,
                "viable": viable is True,
                "boot_id": current.get("world_boot_id"),
            }
            objective_kills = current.get("campaign_objective_kills")
            segment_xp_delta = _xp_delta(previous, current)
            if not objective_kills and (
                segment_xp_delta < 0
                or _xp_loss_event_observed(previous, current)
            ):
                # Registered research executions historically persisted only
                # the live consider boolean. Keep the loss alongside it so a
                # later selector cannot mistake a safe withdrawal for a fresh
                # viable route.
                result["viable"] = False
                result["completed_kill"] = False
                result["xp_delta"] = segment_xp_delta
                result["xp_loss_observed"] = True
            if policy.execution == "source-ranked-hunt":
                # Generated source-ranked routes need an explicit durable
                # distinction between a productive hunt and a viable probe.
                # Other objective-bearing policies may intentionally record
                # an acquisition without promoting it to XP progress.
                result["completed_kill"] = bool(objective_kills)
                total_xp, max_kill_xp, explicit_xp = _objective_kill_xp_stats(
                    objective_kills
                )
                if objective_kills and explicit_xp:
                    result["objective_xp"] = total_xp
                    result["max_objective_kill_xp"] = max_kill_xp
                    if max_kill_xp < _SOURCE_RANKED_MIN_MEANINGFUL_KILL_XP:
                        result["low_reward"] = True
            if (
                policy.policy_id == _MORIA_SANCTUARY_THIEF_LEVEL_SEVENTEEN_POLICY_ID
                and current.get("campaign_objective_kills")
            ):
                result["objective_kill"] = True
            results[policy.policy_id] = result
            recorded_current_result = True
            absence_cooldowns.pop(policy.policy_id, None)
            crowd_cooldowns.pop(policy.policy_id, None)
            source_ranked_crowd_attempts.pop(policy.policy_id, None)
        if current.get("campaign_died_during_segment"):
            # A target kill before death is still useful forensic evidence, but
            # it does not make the route viable: the net attempt lost XP and
            # must remain blocked until the level or reboot changes.
            objective_kills = current.get("campaign_objective_kills")
            total_xp, max_kill_xp, explicit_xp = _objective_kill_xp_stats(
                objective_kills
            )
            fatal_result: dict[str, Any] = {
                "observed": True,
                "viable": False,
                "completed_kill": False,
                "fatal_failure": True,
                "boot_id": current.get("world_boot_id"),
                "level": _level(current),
            }
            if objective_kills:
                fatal_result["objective_kill_observed"] = True
            if objective_kills and explicit_xp:
                fatal_result["objective_xp"] = total_xp
                fatal_result["max_objective_kill_xp"] = max_kill_xp
            results[policy.policy_id] = fatal_result
            recorded_current_result = True
            absence_cooldowns.pop(policy.policy_id, None)
            crowd_cooldowns.pop(policy.policy_id, None)
            source_ranked_crowd_attempts.pop(policy.policy_id, None)
        sanctuary_resource_route = policy.execution in {
            "moria-sanctuary-hunt",
            "moria-deep-sanctuary-hunt",
        }
        if sanctuary_resource_route and resource_acquisition:
            sanctuary_resource_attempts.pop(policy.policy_id, None)
        if (
            sanctuary_resource_route
            and recorded_current_result
            and not resource_acquisition
        ):
            current_result = results.get(policy.policy_id)
            if (
                isinstance(current_result, dict)
                and current_result.get("retryable_failure") is True
            ):
                attempt_count = _sanctuary_resource_attempt_count(
                    previous,
                    policy.policy_id,
                    boot_id=current.get("world_boot_id"),
                    level=_level(current),
                )
                if attempt_count == 0:
                    previous_result = _campaign_research_results(
                        previous
                    ).get(policy.policy_id)
                    if (
                        isinstance(previous_result, Mapping)
                        and previous_result.get("boot_id")
                        == current.get("world_boot_id")
                        and previous_result.get("retryable_failure") is True
                    ):
                        # Legacy checkpoints predate the durable counter but
                        # still retain the immediately preceding failed pass.
                        attempt_count = 1
                attempt_count += 1
                sanctuary_resource_attempts[policy.policy_id] = {
                    "boot_id": current.get("world_boot_id"),
                    "level": _level(current),
                    "count": attempt_count,
                }
                if attempt_count >= _SANCTUARY_RESOURCE_MAX_ATTEMPTS:
                    current_result["fatal_failure"] = True
                    current_result["level"] = _level(current)
                    current_result["route_hazard"] = current_result.get(
                        "route_hazard"
                    ) or (
                        "sanctuary resource route exhausted after "
                        f"{_SANCTUARY_RESOURCE_MAX_ATTEMPTS} failed attempts"
                    )
                    current_result.pop("retryable_failure", None)
                    absence_cooldowns.pop(policy.policy_id, None)
                results[policy.policy_id] = current_result
        if sanctuary_resource_route and not resource_acquisition:
            previous_result = _campaign_research_results(previous).get(
                policy.policy_id
            )
            if (
                isinstance(previous_result, Mapping)
                and previous_result.get("fatal_failure") is True
                and previous_result.get("boot_id")
                == current.get("world_boot_id")
                and previous_result.get("completed_kill") is not True
            ):
                # A terminal resource result cannot be downgraded by a later
                # maintenance or retry segment that failed to acquire the
                # required object. A fresh reboot or successful acquisition
                # must be the event that reopens this route.
                results[policy.policy_id] = dict(previous_result)
                absence_cooldowns.pop(policy.policy_id, None)
                crowd_cooldowns.pop(policy.policy_id, None)
        for revalidation_key, failed_outcome in (
            (
                _SANCTUARY_VISIBILITY_REVALIDATION_KEY,
                _SANCTUARY_VISIBILITY_REVALIDATION_FAILED_OUTCOME,
            ),
            (
                _SANCTUARY_INVISIBLE_CARRIER_REVALIDATION_KEY,
                (
                    "expanded invisible carrier sweep completed without "
                    "sanctuary acquisition"
                ),
            ),
            (
                _SANCTUARY_LOCATOR_LABEL_REVALIDATION_KEY,
                (
                    "label-aware carrier sweep completed without sanctuary "
                    "acquisition"
                ),
            ),
        ):
            revalidation = merged.get(revalidation_key)
            if (
                policy.policy_id
                == _SOURCE_RANKED_SANCTUARY_RECOVERY_POLICY.policy_id
                and recorded_current_result
                and isinstance(revalidation, Mapping)
                and revalidation.get("status") == "attempted"
            ):
                merged[revalidation_key] = {
                    **dict(revalidation),
                    "status": (
                        "succeeded" if resource_acquisition else "failed"
                    ),
                    "outcome": (
                        "required sanctuary object acquired"
                        if resource_acquisition
                        else failed_outcome
                    ),
                }
        if recorded_current_result:
            cleared_research_policies.discard(policy.policy_id)
    if results:
        merged["campaign_research_results"] = results
    if absence_cooldowns:
        merged[_RESEARCH_ABSENCE_COOLDOWN_KEY] = absence_cooldowns
    else:
        merged.pop(_RESEARCH_ABSENCE_COOLDOWN_KEY, None)
    if crowd_cooldowns:
        merged[_RESEARCH_CROWD_COOLDOWN_KEY] = crowd_cooldowns
    else:
        merged.pop(_RESEARCH_CROWD_COOLDOWN_KEY, None)
    if source_ranked_crowd_attempts:
        merged[_SOURCE_RANKED_CROWD_ATTEMPTS_KEY] = (
            source_ranked_crowd_attempts
        )
    else:
        merged.pop(_SOURCE_RANKED_CROWD_ATTEMPTS_KEY, None)
    if sanctuary_resource_attempts:
        merged[_SANCTUARY_RESOURCE_ATTEMPTS_KEY] = (
            sanctuary_resource_attempts
        )
    else:
        merged.pop(_SANCTUARY_RESOURCE_ATTEMPTS_KEY, None)
    if cleared_research_policies:
        merged[_CLEARED_RESEARCH_POLICIES_KEY] = sorted(
            cleared_research_policies
        )
    else:
        merged.pop(_CLEARED_RESEARCH_POLICIES_KEY, None)
    # This identifies only the executor used by the current segment. The
    # durable research result carries the exact object VNUM, so retaining the
    # dispatch marker would make later unrelated segments look like reserve
    # acquisitions.
    merged.pop(_SOURCE_CONSUMABLE_SPELL_KEY, None)
    return merged


def _source_ranked_circuit_policy_ids(
    candidate_record: object,
    *,
    primary_policy_id: str,
) -> tuple[str, ...]:
    """Return the exact generated policies searched by one saved circuit."""
    records = _source_ranked_circuit_policy_records(
        candidate_record,
        primary_policy_id=primary_policy_id,
    )
    policy_ids = tuple(
        dict.fromkeys(
            str(record.get("policy_id") or "") for record in records
        )
    )
    return policy_ids or (primary_policy_id,)


def _restore_source_ranked_policy_metadata(
    previous: Mapping[str, Any],
    current: dict[str, Any],
    policy_id: str,
) -> dict[str, Any]:
    """Undo a circuit-wide merge for a primary stop that was not observed."""
    restored = dict(current)
    for key in (
        "campaign_research_results",
        _RESEARCH_ABSENCE_COOLDOWN_KEY,
        _RESEARCH_CROWD_COOLDOWN_KEY,
        _SOURCE_RANKED_CROWD_ATTEMPTS_KEY,
        _BELOW_BAND_POLICY_EXCLUSIONS_KEY,
        _BELOW_BAND_SIGHTINGS_KEY,
    ):
        current_records = dict(restored.get(key) or {})
        previous_records = previous.get(key)
        previous_record = (
            previous_records.get(policy_id)
            if isinstance(previous_records, Mapping)
            else None
        )
        current_record = current_records.get(policy_id)
        if previous_record is None:
            current_records.pop(policy_id, None)
        elif key != "campaign_research_results" or not isinstance(
            previous_record, Mapping
        ):
            current_records[policy_id] = previous_record
        else:
            restored_record = dict(previous_record)
            if (
                isinstance(current_record, Mapping)
                and current_record.get("consider_viable") is True
                and "consider_viable" not in restored_record
            ):
                # Confirmed-kill repair can recover a positive consideration
                # after this older circuit snapshot was written. Preserve
                # that newer evidence while still restoring the old primary
                # record's other circuit-owned fields.
                restored_record["consider_viable"] = True
            current_records[policy_id] = restored_record
        if current_records:
            restored[key] = current_records
        else:
            restored.pop(key, None)

    current_cleared = {
        str(value)
        for value in restored.get(_CLEARED_RESEARCH_POLICIES_KEY, ())
    }
    previous_cleared = {
        str(value)
        for value in previous.get(_CLEARED_RESEARCH_POLICIES_KEY, ())
    }
    explicit_retry_marker = restored.get(_EXPLICIT_RESEARCH_RETRY_KEY)
    explicitly_cleared = (
        isinstance(explicit_retry_marker, Mapping)
        and explicit_retry_marker.get("boot_id") == restored.get("world_boot_id")
        and policy_id
        in {
            str(value)
            for value in explicit_retry_marker.get("policy_ids", ())
        }
    )
    if policy_id in previous_cleared or explicitly_cleared:
        current_cleared.add(policy_id)
    else:
        current_cleared.discard(policy_id)
    if current_cleared:
        restored[_CLEARED_RESEARCH_POLICIES_KEY] = sorted(current_cleared)
    else:
        restored.pop(_CLEARED_RESEARCH_POLICIES_KEY, None)
    return restored


def _merge_source_ranked_circuit_consider_results(
    previous: Mapping[str, Any],
    state: dict[str, Any],
    objective_kills: object,
    *,
    primary_policy_id: str,
) -> dict[str, Any]:
    """Persist each circuit consideration against its own source policy."""
    policy_ids = _source_ranked_circuit_policy_ids(
        state.get(_SOURCE_RANKED_CANDIDATE_KEY),
        primary_policy_id=primary_policy_id,
    )
    if len(policy_ids) <= 1:
        return state
    outcomes = _source_ranked_consider_outcomes_by_policy(
        state,
        primary_policy_id=primary_policy_id,
    )
    if not outcomes:
        return state
    killed_policy_ids = set(_source_ranked_kill_policy_ids(objective_kills))
    merged = dict(state)
    if (
        primary_policy_id not in outcomes
        and primary_policy_id not in killed_policy_ids
    ):
        merged = _restore_source_ranked_policy_metadata(
            previous,
            merged,
            primary_policy_id,
        )

    results = _campaign_research_results(merged)
    previous_results = _campaign_research_results(dict(previous))
    absence_cooldowns = dict(
        merged.get(_RESEARCH_ABSENCE_COOLDOWN_KEY) or {}
    )
    crowd_cooldowns = dict(
        merged.get(_RESEARCH_CROWD_COOLDOWN_KEY) or {}
    )
    crowd_attempts = dict(
        merged.get(_SOURCE_RANKED_CROWD_ATTEMPTS_KEY) or {}
    )
    cleared = {
        str(value)
        for value in merged.get(_CLEARED_RESEARCH_POLICIES_KEY, ())
    }
    boot_id = merged.get("world_boot_id")
    for policy_id, outcome in outcomes.items():
        if policy_id in killed_policy_ids:
            continue
        result: dict[str, Any] = {
            "observed": True,
            "viable": False,
            "completed_kill": False,
            "consider_viable": outcome,
            "boot_id": boot_id,
        }
        if outcome:
            result["retryable_failure"] = True
            previous_result = previous_results.get(policy_id)
            if (
                isinstance(previous_result, Mapping)
                and previous_result.get("boot_id") == boot_id
                and previous_result.get("viable") is True
                and previous_result.get("completed_kill") is not False
            ):
                result["previously_productive"] = True
            absence_cooldowns[policy_id] = (
                _research_absence_retry_cooldown(
                    policy_id,
                    default=_DEFAULT_RESEARCH_CROWD_COOLDOWN,
                )
            )
        else:
            # The level-difference rejection is terminal for this level and
            # reboot. A short retry must never reopen it.
            absence_cooldowns.pop(policy_id, None)
        results[policy_id] = result
        crowd_cooldowns.pop(policy_id, None)
        crowd_attempts.pop(policy_id, None)
        cleared.discard(policy_id)

    merged["campaign_research_results"] = results
    for key, records in (
        (_RESEARCH_ABSENCE_COOLDOWN_KEY, absence_cooldowns),
        (_RESEARCH_CROWD_COOLDOWN_KEY, crowd_cooldowns),
        (_SOURCE_RANKED_CROWD_ATTEMPTS_KEY, crowd_attempts),
    ):
        if records:
            merged[key] = records
        else:
            merged.pop(key, None)
    if cleared:
        merged[_CLEARED_RESEARCH_POLICIES_KEY] = sorted(cleared)
    else:
        merged.pop(_CLEARED_RESEARCH_POLICIES_KEY, None)
    return merged


def _with_source_ranked_absence_results(
    state: dict[str, Any],
    policy_ids: Collection[str],
) -> dict[str, Any]:
    """Apply one reboot-scoped absence to exact generated policy identities."""
    unique_policy_ids = tuple(dict.fromkeys(str(value) for value in policy_ids))
    if not unique_policy_ids:
        return state
    merged = dict(state)
    boot_id = state.get("world_boot_id")
    results = _campaign_research_results(state)
    absence_cooldowns = dict(
        state.get(_RESEARCH_ABSENCE_COOLDOWN_KEY) or {}
    )
    crowd_cooldowns = dict(state.get(_RESEARCH_CROWD_COOLDOWN_KEY) or {})
    crowd_attempts = dict(state.get(_SOURCE_RANKED_CROWD_ATTEMPTS_KEY) or {})
    cleared = {
        str(policy_id)
        for policy_id in state.get(_CLEARED_RESEARCH_POLICIES_KEY, ())
    }
    for policy_id in unique_policy_ids:
        if not policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX):
            continue
        results[policy_id] = {
            "observed": False,
            "viable": False,
            "absent": True,
            "boot_id": boot_id,
        }
        retry_cooldown = _research_absence_retry_cooldown(policy_id)
        if retry_cooldown is not None:
            absence_cooldowns[policy_id] = retry_cooldown
        crowd_cooldowns.pop(policy_id, None)
        crowd_attempts.pop(policy_id, None)
        cleared.discard(policy_id)
    merged["campaign_research_results"] = results
    if absence_cooldowns:
        merged[_RESEARCH_ABSENCE_COOLDOWN_KEY] = absence_cooldowns
    else:
        merged.pop(_RESEARCH_ABSENCE_COOLDOWN_KEY, None)
    if crowd_cooldowns:
        merged[_RESEARCH_CROWD_COOLDOWN_KEY] = crowd_cooldowns
    else:
        merged.pop(_RESEARCH_CROWD_COOLDOWN_KEY, None)
    if crowd_attempts:
        merged[_SOURCE_RANKED_CROWD_ATTEMPTS_KEY] = crowd_attempts
    else:
        merged.pop(_SOURCE_RANKED_CROWD_ATTEMPTS_KEY, None)
    if cleared:
        merged[_CLEARED_RESEARCH_POLICIES_KEY] = sorted(cleared)
    else:
        merged.pop(_CLEARED_RESEARCH_POLICIES_KEY, None)
    return merged


def _merge_source_ranked_circuit_absence_results(
    state: dict[str, Any],
    objective_kills: object,
    *,
    primary_policy_id: str,
) -> dict[str, Any]:
    """Cool down exact reset misses without hiding behind circuit presence."""
    crowd_abort_reason = str(
        state.get("campaign_fastwalk_abort_reason") or ""
    )
    crowded_field = bool(
        state.get("campaign_fastwalk_crowded")
        or any(
            crowd_abort_reason.startswith(prefix)
            for prefix in _FIELD_CROWD_ABORT_PREFIXES
        )
    )
    killed_policy_ids = set(_source_ranked_kill_policy_ids(objective_kills))
    present_policy_ids = set(
        _source_ranked_present_policy_ids(
            state,
            primary_policy_id=primary_policy_id,
        )
    )
    present_policy_ids.update(
        _source_ranked_consider_outcomes_by_policy(
            state,
            primary_policy_id=primary_policy_id,
        )
    )
    direct_absences = tuple(
        policy_id
        for policy_id in _source_ranked_absent_policy_ids(
            state,
            primary_policy_id=primary_policy_id,
        )
        if policy_id not in killed_policy_ids
        and policy_id not in present_policy_ids
        # The primary policy's exact room miss is secondary to a live crowd
        # decision for the dispatched circuit.  The research merger already
        # recorded the primary as crowded; replacing it with absence here
        # causes startup repair to flip the same evidence back to crowd.
        and not (crowded_field and policy_id == primary_policy_id)
    )
    if direct_absences:
        state = _with_source_ranked_absence_results(
            state,
            direct_absences,
        )
    if not state.get("campaign_fastwalk_target_absent"):
        return state
    if (
        state.get("campaign_fastwalk_target_present_observed")
        or state.get("campaign_fastwalk_consider_outcomes")
    ):
        # Presence anywhere in the dispatched circuit means the route was not
        # a complete empty search. Preserve the primary attempt and leave
        # unvisited supplementary resets open.
        return state
    if isinstance(objective_kills, (list, tuple)) and objective_kills:
        return state
    policy_ids = _source_ranked_circuit_policy_ids(
        state.get(_SOURCE_RANKED_CANDIDATE_KEY),
        primary_policy_id=primary_policy_id,
    )
    if len(policy_ids) <= 1:
        return state
    return _with_source_ranked_absence_results(state, policy_ids)


def _repair_source_ranked_circuit_consider_history(
    state: dict[str, Any],
    segments: Collection[Mapping[str, Any]],
) -> dict[str, Any]:
    """Repair old circuit outcomes that were assigned to the primary stop."""
    repaired = dict(state)
    current_results = _campaign_research_results(state)
    current_absence_cooldowns = dict(
        state.get(_RESEARCH_ABSENCE_COOLDOWN_KEY) or {}
    )
    current_cleared_research_policies = {
        str(policy_id)
        for policy_id in state.get(_CLEARED_RESEARCH_POLICIES_KEY, ())
    }
    confirmed_current_boot_results = {
        str(policy_id): dict(result)
        for policy_id, result in _campaign_research_results(state).items()
        if (
            isinstance(result, Mapping)
            and result.get("boot_id") == state.get("world_boot_id")
            and result.get("viable") is True
            and result.get("completed_kill") is True
        )
    }
    previously_productive_policy_ids = {
        str(policy_id)
        for policy_id, result in _campaign_research_results(state).items()
        if (
            isinstance(result, Mapping)
            and result.get("previously_productive") is True
        )
    }
    later_evidence: set[str] = set()
    boot_id = state.get("world_boot_id")
    for segment in reversed(tuple(segments)):
        phase = str(segment["phase"] or "")
        if not phase.startswith(_SOURCE_RANKED_POLICY_PREFIX):
            continue
        try:
            start = json.loads(segment["start_state_json"] or "{}")
            end = json.loads(segment["end_state_json"] or "{}")
        except (TypeError, json.JSONDecodeError):
            continue
        if not isinstance(start, Mapping) or not isinstance(end, Mapping):
            continue
        segment_boot_id = end.get("world_boot_id")
        if boot_id and segment_boot_id and segment_boot_id != boot_id:
            continue
        candidate_record = start.get(_SOURCE_RANKED_CANDIDATE_KEY)
        policy_ids = _source_ranked_circuit_policy_ids(
            candidate_record,
            primary_policy_id=phase,
        )
        evidence_state = dict(end)
        if isinstance(candidate_record, Mapping):
            evidence_state[_SOURCE_RANKED_CANDIDATE_KEY] = candidate_record
        outcomes = _source_ranked_consider_outcomes_by_policy(
            evidence_state,
            primary_policy_id=phase,
        )
        killed_policy_ids = set(
            _source_ranked_kill_policy_ids(end.get("campaign_objective_kills"))
        )
        actual_evidence = set(outcomes) | killed_policy_ids
        revision = end.get("campaign_policy_revision")
        if type(revision) is int and revision >= 242:
            # Current terminal records already own per-stop results. Rebuilding
            # them from old considers fights the authoritative kill-ledger pass.
            later_evidence.update(actual_evidence | {phase})
            later_evidence.update(_source_ranked_absent_policy_ids(evidence_state, primary_policy_id=phase))
            later_evidence.update(_source_ranked_present_policy_ids(evidence_state, primary_policy_id=phase))
            continue
        if not outcomes:
            later_evidence.update(actual_evidence or {phase})
            continue

        policy = replace(
            _SOURCE_RANKED_HUNT_POLICY,
            policy_id=phase,
            minimum_level=_level(end),
            maximum_level=_level(end),
        )
        corrected = _merge_campaign_below_band_policy_exclusions(
            dict(start),
            evidence_state,
            policy=policy,
            level=_level(end),
            boot_id=segment_boot_id or boot_id,
        )
        corrected = _merge_campaign_research_result(
            dict(start),
            corrected,
            policy=policy,
        )
        corrected = _merge_source_ranked_circuit_consider_results(
            start,
            corrected,
            end.get("campaign_objective_kills"),
            primary_policy_id=phase,
        )
        repair_policy_ids = {
            policy_id
            for policy_id in actual_evidence
            if (
                policy_id not in later_evidence
                and policy_id not in current_cleared_research_policies
            )
        }
        if (
            phase not in actual_evidence
            and phase not in later_evidence
            and phase not in current_cleared_research_policies
        ):
            repair_policy_ids.add(phase)
        for policy_id in repair_policy_ids:
            repaired = _restore_source_ranked_policy_metadata(
                corrected,
                repaired,
                policy_id,
            )
        later_evidence.update(actual_evidence)
        later_evidence.add(phase)
    if previously_productive_policy_ids:
        results = dict(_campaign_research_results(repaired))
        changed = False
        for policy_id in previously_productive_policy_ids:
            result = results.get(policy_id)
            if not isinstance(result, Mapping) or result.get(
                "consider_viable"
            ) is False:
                continue
            if result.get("previously_productive") is True:
                continue
            restored = dict(result)
            restored["previously_productive"] = True
            results[policy_id] = restored
            changed = True
        if changed:
            repaired["campaign_research_results"] = results
    if confirmed_current_boot_results:
        results = dict(_campaign_research_results(repaired))
        changed = False
        for policy_id, confirmed_result in confirmed_current_boot_results.items():
            current_result = results.get(policy_id)
            if not (
                isinstance(current_result, Mapping)
                and current_result.get("boot_id")
                == state.get("world_boot_id")
                and (
                    current_result.get("viable") is not True
                    or current_result.get("completed_kill") is not True
                )
            ):
                continue
            # A current-reboot confirmed objective kill is authoritative over
            # an older circuit migration that only reclassified a secondary
            # consider or no-kill outcome. Keeping it intact also makes the
            # startup repair converge instead of alternating on reconnect.
            results[policy_id] = confirmed_result
            changed = True
        if changed:
            repaired["campaign_research_results"] = results

    # Segment history contains the original three-step cooldown, while the
    # current checkpoint may already have consumed one or more reset waits.
    # Preserve that newer reboot-local value so a reconnect cannot rewind the
    # reset state. A cleared policy is likewise authoritative: do not
    # resurrect its old result merely because an earlier segment mentioned it.
    repaired_results = _campaign_research_results(repaired)
    repaired_absence_cooldowns = dict(
        repaired.get(_RESEARCH_ABSENCE_COOLDOWN_KEY) or {}
    )
    repaired_crowd_cooldowns = dict(
        repaired.get(_RESEARCH_CROWD_COOLDOWN_KEY) or {}
    )
    metadata_changed = False
    for policy_id in current_cleared_research_policies:
        current_result = current_results.get(policy_id)
        if isinstance(current_result, Mapping):
            if repaired_results.get(policy_id) != current_result:
                repaired_results[policy_id] = dict(current_result)
                metadata_changed = True
            continue
        if policy_id in repaired_results:
            repaired_results.pop(policy_id, None)
            metadata_changed = True
        if repaired_absence_cooldowns.pop(policy_id, None) is not None:
            metadata_changed = True
        if repaired_crowd_cooldowns.pop(policy_id, None) is not None:
            metadata_changed = True

    current_boot_id = state.get("world_boot_id")
    for raw_policy_id, raw_remaining in current_absence_cooldowns.items():
        policy_id = str(raw_policy_id)
        try:
            remaining = int(raw_remaining)
        except (TypeError, ValueError):
            continue
        if remaining <= 0 or policy_id in current_cleared_research_policies:
            continue
        current_result = current_results.get(policy_id)
        repaired_result = repaired_results.get(policy_id)
        if not (
            isinstance(current_result, Mapping)
            and current_result.get("boot_id") == current_boot_id
            and (
                current_result.get("retryable_failure") is True
                or (
                    current_result.get("route_hazard")
                    == _DYNAMIC_FIELD_ROUTE_HAZARD_ABORT_REASON
                )
                or _is_retryable_source_ranked_route_hazard(
                    policy_id,
                    current_result.get("route_hazard"),
                )
            )
            and not (
                isinstance(repaired_result, Mapping)
                and repaired_result.get("viable") is True
                and repaired_result.get("completed_kill") is True
            )
        ):
            continue
        if repaired_absence_cooldowns.get(policy_id) != remaining:
            repaired_absence_cooldowns[policy_id] = remaining
            metadata_changed = True

    if metadata_changed:
        if repaired_results:
            repaired["campaign_research_results"] = repaired_results
        else:
            repaired.pop("campaign_research_results", None)
        if repaired_absence_cooldowns:
            repaired[_RESEARCH_ABSENCE_COOLDOWN_KEY] = (
                repaired_absence_cooldowns
            )
        else:
            repaired.pop(_RESEARCH_ABSENCE_COOLDOWN_KEY, None)
        if repaired_crowd_cooldowns:
            repaired[_RESEARCH_CROWD_COOLDOWN_KEY] = (
                repaired_crowd_cooldowns
            )
        else:
            repaired.pop(_RESEARCH_CROWD_COOLDOWN_KEY, None)
    return repaired


def _repair_source_ranked_present_circuit_history(
    state: dict[str, Any],
    segments: Collection[Mapping[str, Any]],
) -> dict[str, Any]:
    """Reverse pre-revision-149 absence propagation after a live sighting."""
    ordered_segments = tuple(segments)
    results = _campaign_research_results(state)
    absence_cooldowns = dict(
        state.get(_RESEARCH_ABSENCE_COOLDOWN_KEY) or {}
    )
    changed = False
    for index, segment in enumerate(ordered_segments):
        phase = str(segment["phase"] or "")
        if not phase.startswith(_SOURCE_RANKED_POLICY_PREFIX):
            continue
        try:
            start = json.loads(segment["start_state_json"] or "{}")
            end = json.loads(segment["end_state_json"] or "{}")
        except (TypeError, json.JSONDecodeError):
            continue
        if not (
            end.get("campaign_fastwalk_target_absent") is True
            and end.get("campaign_fastwalk_target_present_observed") is True
            and not end.get("campaign_objective_kills")
        ):
            continue
        boot_id = end.get("world_boot_id") or state.get("world_boot_id")
        if (
            boot_id
            and state.get("world_boot_id")
            and boot_id != state.get("world_boot_id")
        ):
            continue
        policy_ids = _source_ranked_circuit_policy_ids(
            start.get(_SOURCE_RANKED_CANDIDATE_KEY),
            primary_policy_id=phase,
        )
        later_evidence: set[str] = set()
        for later_segment in ordered_segments[index + 1 :]:
            later_phase = str(later_segment["phase"] or "")
            try:
                later_end = json.loads(
                    later_segment["end_state_json"] or "{}"
                )
            except (TypeError, json.JSONDecodeError):
                continue
            later_boot = later_end.get("world_boot_id")
            if boot_id and later_boot and later_boot != boot_id:
                continue
            if later_phase.startswith(_SOURCE_RANKED_POLICY_PREFIX):
                later_evidence.add(later_phase)
            later_evidence.update(
                _source_ranked_kill_policy_ids(
                    later_end.get("campaign_objective_kills")
                )
            )
        primary_result = results.get(phase)
        if (
            phase not in later_evidence
            and isinstance(primary_result, Mapping)
            and primary_result.get("absent") is True
            and primary_result.get("boot_id") == boot_id
        ):
            outcomes = end.get("campaign_fastwalk_consider_outcomes")
            consider_viable = bool(
                isinstance(outcomes, Mapping)
                and any(value is True for value in outcomes.values())
            )
            repaired_primary: dict[str, Any] = {
                "observed": True,
                "viable": False,
                "completed_kill": False,
                "retryable_failure": True,
                "boot_id": boot_id,
            }
            if isinstance(outcomes, Mapping) and outcomes:
                repaired_primary["consider_viable"] = consider_viable
            results[phase] = repaired_primary
            absence_cooldowns[phase] = _research_absence_retry_cooldown(
                phase,
                default=_DEFAULT_RESEARCH_CROWD_COOLDOWN,
            )
            changed = True
        for secondary_id in policy_ids[1:]:
            if secondary_id in later_evidence:
                continue
            secondary_result = results.get(secondary_id)
            if not (
                isinstance(secondary_result, Mapping)
                and secondary_result.get("absent") is True
                and secondary_result.get("boot_id") == boot_id
            ):
                continue
            results.pop(secondary_id, None)
            absence_cooldowns.pop(secondary_id, None)
            changed = True
    if not changed:
        return state
    repaired = dict(state)
    if results:
        repaired["campaign_research_results"] = results
    else:
        repaired.pop("campaign_research_results", None)
    if absence_cooldowns:
        repaired[_RESEARCH_ABSENCE_COOLDOWN_KEY] = absence_cooldowns
    else:
        repaired.pop(_RESEARCH_ABSENCE_COOLDOWN_KEY, None)
    return repaired


def _repair_source_ranked_circuit_absence_history(
    state: dict[str, Any],
    segments: Collection[Mapping[str, Any]],
) -> dict[str, Any]:
    """Backfill secondary absences from pre-revision-147 circuit segments."""
    repaired = state
    ordered_segments = tuple(segments)
    for index, segment in enumerate(ordered_segments):
        phase = str(segment["phase"] or "")
        if not phase.startswith(_SOURCE_RANKED_POLICY_PREFIX):
            continue
        try:
            start = json.loads(segment["start_state_json"] or "{}")
            end = json.loads(segment["end_state_json"] or "{}")
        except (TypeError, json.JSONDecodeError):
            continue
        if not (
            end.get("campaign_fastwalk_target_absent") is True
            and not end.get("campaign_fastwalk_target_present_observed")
            and not end.get("campaign_fastwalk_consider_outcomes")
            and not end.get("campaign_objective_kills")
        ):
            continue
        primary_result = _campaign_research_results(repaired).get(phase)
        if not (
            isinstance(primary_result, Mapping)
            and primary_result.get("absent") is True
            and primary_result.get("boot_id") == repaired.get("world_boot_id")
        ):
            continue
        try:
            remaining = int(
                (repaired.get(_RESEARCH_ABSENCE_COOLDOWN_KEY) or {}).get(
                    phase
                )
                or 0
            )
        except (AttributeError, TypeError, ValueError):
            remaining = 0
        if remaining <= 0:
            continue
        candidate_record = start.get(_SOURCE_RANKED_CANDIDATE_KEY)
        policy_ids = _source_ranked_circuit_policy_ids(
            candidate_record,
            primary_policy_id=phase,
        )
        if len(policy_ids) <= 1:
            continue
        later_evidence: set[str] = set()
        for later_segment in ordered_segments[index + 1 :]:
            later_phase = str(later_segment["phase"] or "")
            if later_phase.startswith(_SOURCE_RANKED_POLICY_PREFIX):
                later_evidence.add(later_phase)
            try:
                later_end = json.loads(
                    later_segment["end_state_json"] or "{}"
                )
            except (TypeError, json.JSONDecodeError):
                continue
            later_evidence.update(
                _source_ranked_kill_policy_ids(
                    later_end.get("campaign_objective_kills")
                )
            )
        missing_absences = tuple(
            policy_id
            for policy_id in policy_ids[1:]
            if policy_id not in later_evidence
        )
        repaired = _with_source_ranked_absence_results(
            repaired,
            missing_absences,
        )
    return repaired


def _repair_source_ranked_partial_absence_history(
    state: dict[str, Any],
    segments: Collection[Mapping[str, Any]],
) -> dict[str, Any]:
    """Backfill exact misses from completed mixed-presence circuits."""
    repaired = state
    later_evidence: set[str] = set()
    current_boot_id = state.get("world_boot_id")
    for segment in reversed(tuple(segments)):
        phase = str(segment["phase"] or "")
        if not phase.startswith(_SOURCE_RANKED_POLICY_PREFIX):
            continue
        if str(segment["status"] or "") != "success":
            continue
        try:
            start = json.loads(segment["start_state_json"] or "{}")
            end = json.loads(segment["end_state_json"] or "{}")
        except (TypeError, json.JSONDecodeError):
            continue
        if not isinstance(start, Mapping) or not isinstance(end, Mapping):
            continue
        boot_id = end.get("world_boot_id")
        if current_boot_id and boot_id and boot_id != current_boot_id:
            continue
        candidate_record = start.get(_SOURCE_RANKED_CANDIDATE_KEY)
        policy_ids = _source_ranked_circuit_policy_ids(
            candidate_record,
            primary_policy_id=phase,
        )
        if len(policy_ids) <= 1:
            later_evidence.update(policy_ids)
            continue
        evidence_state = dict(end)
        evidence_state[_SOURCE_RANKED_CANDIDATE_KEY] = candidate_record
        outcomes = _source_ranked_consider_outcomes_by_policy(
            evidence_state,
            primary_policy_id=phase,
        )
        killed_policy_ids = set(
            _source_ranked_kill_policy_ids(
                end.get("campaign_objective_kills")
            )
        )
        direct_absences = set(
            _source_ranked_absent_policy_ids(
                evidence_state,
                primary_policy_id=phase,
            )
        )
        present_policy_ids = set(
            _source_ranked_present_policy_ids(
                evidence_state,
                primary_policy_id=phase,
            )
        )
        present_policy_ids.update(outcomes)
        direct_absences.difference_update(
            killed_policy_ids | present_policy_ids
        )
        actual_evidence = (
            set(outcomes)
            | killed_policy_ids
            | direct_absences
            | present_policy_ids
        )
        inferred_absences: set[str] = set(direct_absences)
        if (
            outcomes
            and not killed_policy_ids
            and not end.get("campaign_fastwalk_crowded")
            and not end.get("campaign_fastwalk_abort_reason")
        ):
            inferred_absences.update(set(policy_ids) - actual_evidence)
        inferred_absences.difference_update(later_evidence)
        if inferred_absences:
            repaired = _with_source_ranked_absence_results(
                repaired,
                sorted(inferred_absences),
            )
        later_evidence.update(actual_evidence)
    return repaired


def _merge_source_ranked_circuit_kill_results(
    state: dict[str, Any],
    objective_kills: object,
    *,
    primary_policy_id: str,
) -> dict[str, Any]:
    """Promote every source target that produced a tagged circuit kill."""
    killed_policy_ids = _source_ranked_kill_policy_ids(objective_kills)
    if not killed_policy_ids:
        return state

    merged = dict(state)
    results = _campaign_research_results(state)
    boot_id = state.get("world_boot_id")
    for policy_id in killed_policy_ids:
        result: dict[str, Any] = {
            "observed": True,
            "viable": True,
            "completed_kill": True,
            "consider_viable": True,
            "boot_id": boot_id,
        }
        policy_kills = [
            kill
            for kill in objective_kills
            if isinstance(kill, Mapping)
            and str(kill.get("source_policy_id") or "") == policy_id
        ]
        total_xp, max_kill_xp, explicit_xp = _objective_kill_xp_stats(
            policy_kills
        )
        if explicit_xp:
            result["objective_xp"] = total_xp
            result["max_objective_kill_xp"] = max_kill_xp
        results[policy_id] = result

    # The generic research merger sees the circuit-wide kill list. Do not let
    # a secondary kill falsely promote an absent or rejected primary target.
    if primary_policy_id not in killed_policy_ids:
        primary_result = results.get(primary_policy_id)
        if isinstance(primary_result, Mapping):
            corrected = dict(primary_result)
            corrected["viable"] = False
            corrected["completed_kill"] = False
            corrected.pop("consider_viable", None)
            results[primary_policy_id] = corrected

    merged["campaign_research_results"] = results
    for key in (
        _RESEARCH_ABSENCE_COOLDOWN_KEY,
        _RESEARCH_CROWD_COOLDOWN_KEY,
        _SOURCE_RANKED_CROWD_ATTEMPTS_KEY,
    ):
        records = dict(state.get(key) or {})
        for policy_id in killed_policy_ids:
            records.pop(policy_id, None)
        if records:
            merged[key] = records
        else:
            merged.pop(key, None)
    cleared = {
        str(policy_id)
        for policy_id in state.get(_CLEARED_RESEARCH_POLICIES_KEY, ())
    }
    cleared.difference_update(killed_policy_ids)
    if cleared:
        merged[_CLEARED_RESEARCH_POLICIES_KEY] = sorted(cleared)
    else:
        merged.pop(_CLEARED_RESEARCH_POLICIES_KEY, None)
    return merged


def _clear_completed_source_ranked_dispatch(
    state: dict[str, Any],
    objective_kills: object,
) -> dict[str, Any]:
    """Rebuild source circuits after a completed target changes the frontier."""
    if not isinstance(objective_kills, (list, tuple)) or not objective_kills:
        return state
    refreshed = dict(state)
    refreshed.pop(_SOURCE_RANKED_CANDIDATE_KEY, None)
    return refreshed


def _run_has_crowded_field_decision(
    storage: RunStorage,
    run_id: int,
) -> bool:
    """Detect the old runner's durable decision evidence for a crowd."""
    for event in storage.list_events(run_id):
        if event["kind"] != "decision":
            continue
        try:
            payload = json.loads(event["payload_json"] or "{}")
        except (TypeError, json.JSONDecodeError):
            continue
        reason = str(payload.get("reason") or "").casefold()
        if (
            "crowded circuit target" in reason
            or "crowded field room" in reason
        ):
            return True
    return False


def _repair_crowded_field_metadata(
    storage: RunStorage,
    checkpoint: Any,
    state: dict[str, Any],
) -> dict[str, Any]:
    """Migrate old multi-stop crowd runs that were mislabeled as absent."""
    if (
        checkpoint is None
        or not state.get("campaign_fastwalk_target_absent")
        or state.get("campaign_fastwalk_crowded")
        or state.get("campaign_objective_kills")
    ):
        return state
    run_id = checkpoint["run_id"]
    if run_id is None:
        return state
    try:
        run_id = int(run_id)
    except (TypeError, ValueError):
        return state
    if not _run_has_crowded_field_decision(storage, run_id):
        return state
    policy_id = str(state.get("campaign_last_policy") or "")
    if not policy_id:
        return state
    result = _campaign_research_results(state).get(policy_id)
    if not isinstance(result, dict) or result.get("absent") is not True:
        return state
    repaired = dict(state)
    results = dict(_campaign_research_results(state))
    results[policy_id] = {
        "observed": False,
        "viable": False,
        "crowded": True,
        "boot_id": result.get("boot_id") or state.get("world_boot_id"),
    }
    repaired["campaign_research_results"] = results
    absence_cooldowns = dict(
        state.get(_RESEARCH_ABSENCE_COOLDOWN_KEY) or {}
    )
    absence_cooldowns.pop(policy_id, None)
    if absence_cooldowns:
        repaired[_RESEARCH_ABSENCE_COOLDOWN_KEY] = absence_cooldowns
    else:
        repaired.pop(_RESEARCH_ABSENCE_COOLDOWN_KEY, None)
    crowd_cooldowns = dict(state.get(_RESEARCH_CROWD_COOLDOWN_KEY) or {})
    crowd_cooldowns[policy_id] = _DEFAULT_RESEARCH_CROWD_COOLDOWN
    repaired[_RESEARCH_CROWD_COOLDOWN_KEY] = crowd_cooldowns
    repaired["campaign_fastwalk_target_absent"] = False
    repaired["campaign_fastwalk_crowded"] = True
    cleared = {
        str(candidate_id)
        for candidate_id in state.get(_CLEARED_RESEARCH_POLICIES_KEY, ())
    }
    cleared.discard(policy_id)
    if cleared:
        repaired[_CLEARED_RESEARCH_POLICIES_KEY] = sorted(cleared)
    else:
        repaired.pop(_CLEARED_RESEARCH_POLICIES_KEY, None)
    return repaired


def _repair_source_ranked_crowd_history(
    state: dict[str, Any],
    segments: Collection[Mapping[str, Any]],
) -> dict[str, Any]:
    """Rehydrate a current-reboot crowd lost by an older restart repair."""
    boot_id = state.get("world_boot_id")
    if not boot_id:
        return state
    latest_by_policy: dict[str, tuple[str, Mapping[str, Any]]] = {}
    for segment in sorted(
        segments,
        key=lambda row: int(row["sequence"] or 0),
    ):
        policy_id = str(segment["phase"] or "")
        if not policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX):
            continue
        try:
            end_state = json.loads(segment["end_state_json"] or "{}")
        except (TypeError, json.JSONDecodeError):
            continue
        if not isinstance(end_state, Mapping):
            continue
        if end_state.get("world_boot_id") != boot_id:
            continue
        latest_by_policy[policy_id] = (
            str(segment["status"] or ""),
            end_state,
        )

    results = dict(_campaign_research_results(state))
    absence_cooldowns = dict(
        state.get(_RESEARCH_ABSENCE_COOLDOWN_KEY) or {}
    )
    crowd_cooldowns = dict(
        state.get(_RESEARCH_CROWD_COOLDOWN_KEY) or {}
    )
    cleared_research_policies = {
        str(policy_id)
        for policy_id in state.get(_CLEARED_RESEARCH_POLICIES_KEY, ())
    }
    explicit_retry_policy_ids: set[str] = set()
    retry_marker = state.get(_EXPLICIT_RESEARCH_RETRY_KEY)
    if (
        isinstance(retry_marker, Mapping)
        and retry_marker.get("boot_id") == boot_id
    ):
        explicit_retry_policy_ids = {
            str(policy_id)
            for policy_id in retry_marker.get("policy_ids", ())
        }
    crowd_policy_ids: set[str] = set()
    absent_policy_ids: set[str] = set()
    changed = False
    for policy_id, (status, end_state) in latest_by_policy.items():
        if status not in {"ready", "success"}:
            continue
        abort_reason = str(
            end_state.get("campaign_fastwalk_abort_reason") or ""
        )
        crowd_signal = bool(
            end_state.get("campaign_fastwalk_crowded")
            or any(
                abort_reason.startswith(prefix)
                for prefix in _FIELD_CROWD_ABORT_PREFIXES
            )
        )
        if not crowd_signal:
            if (
                end_state.get("campaign_fastwalk_target_absent") is True
                and not end_state.get(
                    "campaign_fastwalk_target_present_observed"
                )
                and not end_state.get("campaign_fastwalk_consider_outcomes")
            ):
                absent_policy_ids.add(policy_id)
            continue
        if policy_id in explicit_retry_policy_ids:
            # This route was deliberately retired by a same-reboot reset
            # retry. Preserve that decision; generic crowd migration must not
            # immediately reopen it on the next reconnect.
            continue
        crowd_policy_ids.add(policy_id)
        historical_result = _campaign_research_results(end_state).get(
            policy_id
        )
        current_result = results.get(policy_id)
        base_result = (
            current_result
            if isinstance(current_result, Mapping)
            and current_result.get("boot_id") == boot_id
            else historical_result
        )
        if (
            isinstance(base_result, Mapping)
            and base_result.get("viable") is True
            and base_result.get("completed_kill") is not False
        ):
            repaired_result = dict(base_result)
            repaired_result["crowded"] = True
        else:
            repaired_result = {
                "observed": False,
                "viable": False,
                "crowded": True,
                "boot_id": boot_id,
            }
            if isinstance(base_result, Mapping) and base_result.get(
                "crowd_exhausted"
            ) is True:
                repaired_result["crowd_exhausted"] = True
        if results.get(policy_id) != repaired_result:
            results[policy_id] = repaired_result
            changed = True
        absence_cooldowns.pop(policy_id, None)
        crowd_cooldowns[policy_id] = max(
            _DEFAULT_RESEARCH_CROWD_COOLDOWN,
            int(crowd_cooldowns.get(policy_id) or 0),
        )
        if policy_id in cleared_research_policies:
            cleared_research_policies.discard(policy_id)
            changed = True

    current_policy_id = str(state.get("campaign_last_policy") or "")
    restore_current_absent_marker = bool(
        current_policy_id in absent_policy_ids
        and state.get("campaign_fastwalk_crowded")
    )
    if restore_current_absent_marker:
        results[current_policy_id] = {
            "observed": False,
            "viable": False,
            "absent": True,
            "boot_id": boot_id,
        }
        absence_cooldowns[current_policy_id] = max(
            _DEFAULT_RESEARCH_CROWD_COOLDOWN,
            int(absence_cooldowns.get(current_policy_id) or 0),
        )
        crowd_cooldowns.pop(current_policy_id, None)
        cleared_research_policies.discard(current_policy_id)
        changed = True

    if not changed:
        return state
    repaired = dict(state)
    repaired["campaign_research_results"] = results
    if absence_cooldowns:
        repaired[_RESEARCH_ABSENCE_COOLDOWN_KEY] = absence_cooldowns
    else:
        repaired.pop(_RESEARCH_ABSENCE_COOLDOWN_KEY, None)
    repaired[_RESEARCH_CROWD_COOLDOWN_KEY] = crowd_cooldowns
    if cleared_research_policies:
        repaired[_CLEARED_RESEARCH_POLICIES_KEY] = sorted(
            cleared_research_policies
        )
    else:
        repaired.pop(_CLEARED_RESEARCH_POLICIES_KEY, None)
    if restore_current_absent_marker:
        repaired["campaign_fastwalk_target_absent"] = True
        repaired["campaign_fastwalk_crowded"] = False
        repaired.pop("campaign_fastwalk_abort_reason", None)
    if repaired.get("campaign_last_policy") in crowd_policy_ids:
        repaired["campaign_fastwalk_target_absent"] = False
        repaired["campaign_fastwalk_crowded"] = True
    return repaired


def _clear_crowd_absence_marker(state: dict[str, Any]) -> dict[str, Any]:
    """Undo the old crowd-as-absence encoding without touching real absence."""
    reason = str(state.get("campaign_fastwalk_abort_reason") or "")
    if not (
        state.get("campaign_fastwalk_crowded")
        or reason.startswith("field room contained ")
    ):
        return state
    policy_id = state.get("campaign_last_policy")
    if not isinstance(policy_id, str) or not policy_id:
        return state
    results = _campaign_research_results(state)
    result = results.get(policy_id)
    if not isinstance(result, dict) or not result.get("absent"):
        return state
    crowd_signal = bool(
        state.get("campaign_fastwalk_crowded")
        or reason.startswith("field room contained ")
    )
    if policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX) and crowd_signal:
        # Source-ranked field runs briefly used the old absent encoding for a
        # crowded room. Preserve that live crowd evidence instead of letting
        # startup migration erase its cooldown and reopen the same route.
        repaired = dict(state)
        source_result = dict(result)
        source_result.pop("absent", None)
        source_result.pop("unobserved", None)
        source_result.update(
            {
                "observed": False,
                "viable": False,
                "crowded": True,
                "boot_id": source_result.get("boot_id")
                or state.get("world_boot_id"),
            }
        )
        results[policy_id] = source_result
        repaired["campaign_research_results"] = results
        absence_cooldowns = dict(
            state.get(_RESEARCH_ABSENCE_COOLDOWN_KEY) or {}
        )
        absence_remaining = int(absence_cooldowns.pop(policy_id, 0) or 0)
        if absence_cooldowns:
            repaired[_RESEARCH_ABSENCE_COOLDOWN_KEY] = absence_cooldowns
        else:
            repaired.pop(_RESEARCH_ABSENCE_COOLDOWN_KEY, None)
        crowd_cooldowns = dict(
            state.get(_RESEARCH_CROWD_COOLDOWN_KEY) or {}
        )
        crowd_cooldowns[policy_id] = max(
            _DEFAULT_RESEARCH_CROWD_COOLDOWN,
            absence_remaining,
            int(crowd_cooldowns.get(policy_id) or 0),
        )
        repaired[_RESEARCH_CROWD_COOLDOWN_KEY] = crowd_cooldowns
        cleared_research_policies = {
            str(candidate_id)
            for candidate_id in state.get(_CLEARED_RESEARCH_POLICIES_KEY, ())
        }
        cleared_research_policies.discard(policy_id)
        if cleared_research_policies:
            repaired[_CLEARED_RESEARCH_POLICIES_KEY] = sorted(
                cleared_research_policies
            )
        else:
            repaired.pop(_CLEARED_RESEARCH_POLICIES_KEY, None)
        repaired["campaign_fastwalk_target_absent"] = False
        repaired["campaign_fastwalk_crowded"] = True
        return repaired
    results.pop(policy_id, None)
    repaired = dict(state)
    if results:
        repaired["campaign_research_results"] = results
    else:
        repaired.pop("campaign_research_results", None)
    cooldowns = dict(repaired.get(_RESEARCH_ABSENCE_COOLDOWN_KEY) or {})
    cooldowns.pop(policy_id, None)
    if cooldowns:
        repaired[_RESEARCH_ABSENCE_COOLDOWN_KEY] = cooldowns
    else:
        repaired.pop(_RESEARCH_ABSENCE_COOLDOWN_KEY, None)
    cleared_research_policies = {
        str(policy_id)
        for policy_id in state.get(_CLEARED_RESEARCH_POLICIES_KEY, ())
    }
    cleared_research_policies.add(policy_id)
    repaired[_CLEARED_RESEARCH_POLICIES_KEY] = sorted(
        cleared_research_policies
    )
    repaired["campaign_fastwalk_target_absent"] = False
    repaired["campaign_fastwalk_crowded"] = False
    return repaired


def _clear_absent_research_results(
    state: dict[str, Any],
    *,
    except_policy_id: str,
) -> dict[str, Any]:
    """Retry missing or crowded reset targets after productive work elsewhere."""
    merged = dict(state)
    results = _campaign_research_results(state)
    cooldowns = dict(state.get(_RESEARCH_ABSENCE_COOLDOWN_KEY) or {})
    crowd_cooldowns = dict(
        state.get(_RESEARCH_CROWD_COOLDOWN_KEY) or {}
    )
    cleared_research_policies = {
        str(policy_id)
        for policy_id in state.get(_CLEARED_RESEARCH_POLICIES_KEY, ())
    }
    retained: dict[str, dict[str, Any]] = {}
    expired_retryable_groups: set[frozenset[str]] = set()
    for policy_id, result in results.items():
        if policy_id == except_policy_id:
            retained[policy_id] = result
            continue
        if (
            result.get("fatal_failure") is True
            and result.get("boot_id") == state.get("world_boot_id")
        ):
            # Terminal evidence is stronger than a reset-wait cooldown. Keep
            # the exhausted route blocked until a reboot or successful
            # resource acquisition changes the underlying fact.
            retained[policy_id] = result
            cooldowns.pop(policy_id, None)
            crowd_cooldowns.pop(policy_id, None)
            cleared_research_policies.discard(policy_id)
            continue
        if (
            result.get("consider_viable") is False
            and result.get("boot_id") == state.get("world_boot_id")
        ):
            # A live level-band rejection remains authoritative for this
            # reboot. Generic retry metadata must not age it back into use.
            retained[policy_id] = result
            cooldowns.pop(policy_id, None)
            continue
        if result.get("retryable_failure"):
            remaining = int(
                cooldowns.get(
                    policy_id,
                    _research_absence_retry_cooldown(
                        policy_id,
                        default=_DEFAULT_RESEARCH_CROWD_COOLDOWN,
                    ),
                )
                or 0
            )
            if remaining > 1:
                retained[policy_id] = result
                cooldowns[policy_id] = remaining - 1
            else:
                cooldowns.pop(policy_id, None)
                expired_retryable_groups.add(
                    _research_retryable_failure_group(policy_id)
                )
                cleared_research_policies.add(policy_id)
            continue
        if not result.get("absent"):
            retained[policy_id] = result
            continue
        remaining = int(cooldowns.get(policy_id) or 0)
        if remaining > 1:
            retained[policy_id] = result
            cooldowns[policy_id] = remaining - 1
        else:
            cooldowns.pop(policy_id, None)
            cleared_research_policies.add(policy_id)
    for policy_id, result in list(retained.items()):
        if (
            policy_id == except_policy_id
            or not result.get("crowded")
            or result.get("boot_id") != state.get("world_boot_id")
        ):
            continue
        remaining = int(
            crowd_cooldowns.get(policy_id)
            or _DEFAULT_RESEARCH_CROWD_COOLDOWN
        )
        if remaining > 1:
            crowd_cooldowns[policy_id] = remaining - 1
        else:
            crowd_cooldowns.pop(policy_id, None)
            retained.pop(policy_id, None)
            cleared_research_policies.add(policy_id)
    for retryable_group in expired_retryable_groups:
        for policy_id in retryable_group:
            retained.pop(policy_id, None)
            cooldowns.pop(policy_id, None)
            crowd_cooldowns.pop(policy_id, None)
            cleared_research_policies.add(policy_id)
    if retained:
        merged["campaign_research_results"] = retained
    else:
        merged.pop("campaign_research_results", None)
    if cooldowns:
        merged[_RESEARCH_ABSENCE_COOLDOWN_KEY] = cooldowns
    else:
        merged.pop(_RESEARCH_ABSENCE_COOLDOWN_KEY, None)
    if crowd_cooldowns:
        merged[_RESEARCH_CROWD_COOLDOWN_KEY] = crowd_cooldowns
    else:
        merged.pop(_RESEARCH_CROWD_COOLDOWN_KEY, None)
    if cleared_research_policies:
        merged[_CLEARED_RESEARCH_POLICIES_KEY] = sorted(
            cleared_research_policies
        )
    else:
        merged.pop(_CLEARED_RESEARCH_POLICIES_KEY, None)
    return merged


def _campaign_should_await_research_reset(state: dict[str, Any]) -> bool:
    """Allow a bounded reset wait for an absent target or dynamic hazard."""
    policy_id = str(state.get("campaign_last_policy") or "")
    if not policy_id:
        return False
    results = _campaign_research_results(state)
    absence_cooldowns = state.get(_RESEARCH_ABSENCE_COOLDOWN_KEY) or {}
    crowd_cooldowns = state.get(_RESEARCH_CROWD_COOLDOWN_KEY) or {}
    if not isinstance(absence_cooldowns, dict) and not isinstance(
        crowd_cooldowns,
        dict,
    ):
        return False
    group = _research_absence_retry_group(policy_id)
    group_cooldown_active = any(
        max(
            int(absence_cooldowns.get(candidate_id) or 0)
            if isinstance(absence_cooldowns, dict)
            else 0,
            int(crowd_cooldowns.get(candidate_id) or 0)
            if isinstance(crowd_cooldowns, dict)
            else 0,
        )
        > 0
        for candidate_id in group
    )
    if not group_cooldown_active:
        return False
    for candidate_id in group:
        result = results.get(candidate_id)
        if not isinstance(result, dict) or result.get("boot_id") != state.get(
            "world_boot_id"
        ):
            continue
        if not (
            result.get("absent") is True
            or result.get("crowded") is True
            or result.get("route_hazard")
            == _DYNAMIC_FIELD_ROUTE_HAZARD_ABORT_REASON
            or (
                policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX)
                and result.get("route_hazard")
            )
            or (
                candidate_id
                == _SOURCE_RANKED_SANCTUARY_RECOVERY_POLICY.policy_id
                and result.get("retryable_failure") is True
            )
        ):
            continue
        return True
    return False


def _campaign_has_pending_dynamic_route_hazard(state: dict[str, Any]) -> bool:
    """Identify a current dynamic route hazard that is waiting for reset."""
    policy_id = str(state.get("campaign_last_policy") or "")
    result = _campaign_research_results(state).get(policy_id)
    if not (
        isinstance(result, dict)
        and (
            result.get("route_hazard")
            == _DYNAMIC_FIELD_ROUTE_HAZARD_ABORT_REASON
            or (
                policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX)
                and result.get("route_hazard")
            )
        )
        and result.get("boot_id") == state.get("world_boot_id")
    ):
        return False
    cooldowns = state.get(_RESEARCH_ABSENCE_COOLDOWN_KEY) or {}
    return isinstance(cooldowns, dict) and int(cooldowns.get(policy_id) or 0) > 0


def _maintenance_failure_state(
    state: dict[str, Any],
    *,
    execution: str,
    boot_id: str | int | None = None,
    error: str | None = None,
) -> dict[str, Any]:
    """Prevent a failed optional equipment errand from looping at one level."""
    attempted_level_key = _MAINTENANCE_ATTEMPT_LEVEL_KEYS.get(execution)
    if attempted_level_key is None:
        if execution == "restock" and (
            error is None
            or any(
                marker in (error or "").casefold()
                for marker in (
                    "no pie after purchase",
                    "can't even afford",
                    "not enough money",
                    "unaffordable",
                )
            )
        ):
            failed_state = dict(state)
            failed_state[_PROVISION_FUNDING_REQUIRED_KEY] = True
            return failed_state
        return state
    failed_state = dict(state)
    failed_state[attempted_level_key] = _level(state)
    if execution == "recover-daycare-ring":
        failed_state[_DAYCARE_RING_COOLDOWN_KEY] = _DAYCARE_RING_COOLDOWN_SEGMENTS
        if boot_id is not None:
            failed_state[_DAYCARE_RING_ATTEMPT_BOOT_KEY] = boot_id
    if execution == "recover-war-dog-collar" and boot_id is not None:
        failed_state[_WAR_DOG_COLLAR_ATTEMPT_BOOT_KEY] = boot_id
    if execution == "recover-war-dog-collar":
        failed_state[_WAR_DOG_COLLAR_COOLDOWN_KEY] = (
            _WAR_DOG_COLLAR_COOLDOWN_SEGMENTS
        )
    if execution == "restock" and (
        error is None
        or any(
            marker in error.casefold()
            for marker in (
                "no pie after purchase",
                "can't even afford",
                "not enough money",
                "unaffordable",
            )
        )
    ):
        failed_state[_PROVISION_FUNDING_REQUIRED_KEY] = True
    return failed_state


def _repair_city_shop_route_hazard_state(
    storage: RunStorage,
    campaign_id: int,
    checkpoint: Mapping[str, Any] | None,
    state: dict[str, Any],
    *,
    boot_id: str | int | None = None,
) -> dict[str, Any]:
    """Migrate a pre-fix blocked liquidation into a resumable checkpoint."""
    if checkpoint is None:
        return state
    checkpoint = dict(checkpoint)
    if (
        checkpoint.get("phase") != "liquidate-loot"
        or checkpoint.get("reason") != "segment_failed"
        or checkpoint.get("segment_id") is None
    ):
        return state
    segment = next(
        (
            row
            for row in storage.list_campaign_segments(campaign_id)
            if int(row["id"]) == int(checkpoint["segment_id"])
        ),
        None,
    )
    if segment is None or not _is_retryable_city_shop_route_failure(
        "sell-loot",
        segment["error"],
    ):
        return state
    repaired = dict(state)
    repaired[_MAGIC_SHOP_ROUTE_BLOCKED_KEY] = True
    repaired[_CITY_SHOP_ROUTE_COOLDOWN_KEY] = max(
        int(repaired.get(_CITY_SHOP_ROUTE_COOLDOWN_KEY) or 0),
        _CITY_SHOP_ROUTE_COOLDOWN_SEGMENTS,
    )
    route_boot = repaired.get("world_boot_id") or boot_id
    if route_boot is not None:
        repaired[_MAGIC_SHOP_ROUTE_BLOCKED_BOOT_KEY] = route_boot
    run_id = checkpoint.get("run_id")
    if run_id is not None:
        terminal = _run_failed_terminal_state(storage, int(run_id))
        if terminal is not None:
            repaired["city_shop_route_wait_attempts"] = max(
                int(repaired.get("city_shop_route_wait_attempts") or 0),
                int(terminal.get("city_shop_route_wait_attempts") or 0),
            )
            if terminal.get("campaign_sale_rejections") is not None:
                repaired[_CAMPAIGN_SALE_REJECTIONS_KEY] = list(
                    terminal["campaign_sale_rejections"] or ()
                )
    return repaired


def _repair_failed_flight_funding_state(
    state: dict[str, Any],
    checkpoint: Any,
) -> dict[str, Any]:
    """Re-arm one pre-withdrawal funding failure after its bank fix."""
    if (
        checkpoint is None
        or checkpoint["reason"] != "segment_failed"
        or checkpoint["phase"] != "borrow-flight-potion"
        or not state.get("campaign_flight_loan_attempted")
        or state.get("campaign_flight_funding_repair_applied")
    ):
        return state
    repaired = dict(state)
    repaired["campaign_flight_loan_attempted"] = False
    repaired["campaign_flight_funding_repair_applied"] = True
    return repaired


def _repair_exhausted_flight_funding_state(
    state: dict[str, Any],
    *,
    has_sellable_loot: bool | None = None,
) -> dict[str, Any]:
    """Re-arm funding after a used flight reserve expires without cash."""
    affects = state.get("affects")
    if (
        affects is None
        or not state.get("campaign_flight_loan_attempted")
        or any(
            _state_has_active_affect(affects, effect)
            for effect in ("fly", "levitation")
        )
    ):
        return state
    if state.get(_FLIGHT_FUNDING_RETRY_KEY):
        if (
            has_sellable_loot is False
            and _state_copper_value(state) < _flight_purchase_minimum(state)
        ):
            if state.get(_FLIGHT_FUNDING_REQUIRED_KEY):
                return state
            repaired = dict(state)
            repaired[_FLIGHT_FUNDING_REQUIRED_KEY] = True
            return repaired
        if not state.get(_FLIGHT_FUNDING_REQUIRED_KEY):
            return state
        repaired = dict(state)
        repaired.pop(_FLIGHT_FUNDING_REQUIRED_KEY, None)
        return repaired
    if (
        state.get(_FLIGHT_FUNDING_REQUIRED_KEY)
        or _state_copper_value(state) >= _flight_purchase_minimum(state)
    ):
        return state
    repaired = dict(state)
    repaired[_FLIGHT_FUNDING_REQUIRED_KEY] = True
    return repaired


def _newer_progress_state(
    checkpoint: dict[str, Any],
    live: dict[str, Any] | None,
) -> dict[str, Any]:
    if not live:
        return checkpoint
    if not _progress_state_is_valid(live):
        return checkpoint
    if (
        isinstance(live.get("level"), (int, float))
        and isinstance(live.get("xp"), (int, float))
    ):
        merged = {**checkpoint, **live}
        if checkpoint:
            # The live character snapshot can predate a metadata-only
            # checkpoint. Campaign policy, cooldown, and equipment facts are
            # owned by that durable checkpoint; only live game progress and
            # protocol state should override it here.
            for key in _CAMPAIGN_STICKY_METADATA_KEYS:
                if key in checkpoint:
                    merged[key] = checkpoint[key]
                else:
                    merged.pop(key, None)
        _preserve_verified_progress_on_unexplained_regression(
            checkpoint,
            live,
            merged,
        )
        if (
            merged.get("dead")
            and str(merged.get("area", "")).casefold() != "purgatory"
            and _numeric_progress(merged, "hp") > 0
        ):
            merged["dead"] = False
        return merged
    checkpoint_progress = (_level(checkpoint), _numeric_progress(checkpoint, "xp"))
    live_progress = (_level(live), _numeric_progress(live, "xp"))
    return {**checkpoint, **live} if live_progress >= checkpoint_progress else checkpoint


def _numeric_progress(state: dict[str, Any], key: str) -> int:
    value = state.get(key)
    return int(value) if isinstance(value, (int, float)) else 0


def _state_fame(state: Mapping[str, Any]) -> int | None:
    """Return the current GMCP fame value when it is present."""
    stats = state.get("stats")
    if isinstance(stats, Mapping):
        fame = stats.get("fame")
        try:
            return int(fame)
        except (TypeError, ValueError):
            pass
    fame = state.get("fame")
    try:
        return int(fame) if fame is not None else None
    except (TypeError, ValueError):
        return None


def _shop_rearm_blocked_by_reputation(state: Mapping[str, Any]) -> bool:
    """Prefer current GMCP fame over a prior textual shop refusal."""
    fame = _state_fame(state)
    if fame is not None:
        return fame < 0
    return bool(state.get(_SHOP_REARM_REPUTATION_BLOCKED_KEY))


def _negative_fame_food_restock_retry_allowed(
    state: Mapping[str, Any],
    *,
    has_food: bool,
) -> bool:
    """Permit one safe bakery retry when negative fame strands provisions."""
    if has_food or state.get("dead") or state.get("in_combat"):
        return False
    if not _shop_rearm_blocked_by_reputation(state):
        return False
    if state.get(_MAGIC_SHOP_ROUTE_BLOCKED_KEY):
        return False
    room_flags = {
        str(flag).casefold()
        for flag in (state.get("room_flags") or ())
    }
    if not (
        str(state.get("room_vnum") or "") in _MIDGAARD_CITY_HEALER_ROOMS
        or "healing" in room_flags
    ):
        return False
    boot_id = state.get("world_boot_id")
    if boot_id is None or state.get(_FOOD_RESTOCK_REPUTATION_ATTEMPT_BOOT_KEY) == boot_id:
        return False
    # A nonzero balance makes this a meaningful shop recheck. If the price is
    # still unaffordable, the normal funding policy remains responsible for it.
    return _state_copper_value(state) > 0


def _run_has_unrecovered_weapon_loss(
    storage: RunStorage,
    run_id: int,
) -> bool:
    """Reconstruct the final weapon state for legacy or interrupted runs."""
    primary_weapon = _replay_run_equipment(storage, run_id).primary_weapon
    return primary_weapon is not None and not bool(
        primary_weapon[0] and primary_weapon[1]
    )


def _latest_character_run(
    storage: RunStorage,
    character_name: str,
) -> Any | None:
    """Return the latest conventionally named runner for one character."""
    suffixes = (
        f":{character_name}".casefold(),
        f"-{character_name}".casefold(),
    )
    return next(
        (
            run
            for run in storage.list_runs(limit=1000)
            if str(run["scenario_name"]).casefold().endswith(suffixes)
        ),
        None,
    )


def _latest_new_character_run(
    storage: RunStorage,
    character_name: str,
    prior_run_ids: Collection[int],
) -> Any | None:
    """Return the newest named run created during the current segment."""
    prior = {int(run_id) for run_id in prior_run_ids}
    suffixes = (
        f":{character_name}".casefold(),
        f"-{character_name}".casefold(),
    )
    return next(
        (
            run
            for run in storage.list_runs(limit=1000)
            if int(run["id"]) not in prior
            and str(run["scenario_name"]).casefold().endswith(suffixes)
        ),
        None,
    )


def _run_latest_state(storage: RunStorage, run_id: int) -> dict[str, Any] | None:
    """Return the last character snapshot recorded by one run."""
    snapshot = storage.get_latest_state_snapshot(run_id)
    if snapshot is None:
        return None
    try:
        state = json.loads(snapshot["state_json"])
    except (TypeError, json.JSONDecodeError):
        return None
    return dict(state) if isinstance(state, dict) else None


def _run_successful_vault_lodges(
    storage: RunStorage,
    run_id: int,
) -> tuple[str, ...]:
    """Return command keywords for vault lodges acknowledged by DD4."""
    lodged: list[str] = []
    pending_keyword: str | None = None
    for event in storage.list_events(run_id):
        payload = json.loads(event["payload_json"])
        if event["kind"] == "command":
            command = str(payload.get("command", "")).strip().casefold()
            pending_keyword = (
                command.removeprefix("lodge ")
                if command.startswith("lodge ")
                else None
            )
            continue
        if event["kind"] != "response" or pending_keyword is None:
            continue
        response = _ANSI_ESCAPE.sub(
            "",
            str(payload.get("text", "")),
        ).casefold()
        if "you lodge " in response and " in your vault." in response:
            lodged.append(pending_keyword)
        pending_keyword = None
    return tuple(dict.fromkeys(lodged))


@dataclass
class _RunEquipmentReplay:
    empty_categories: set[str] | None = None
    worn_descriptions: list[str] | None = None
    primary_weapon: tuple[bool, str | None] | None = None


def _complete_worn_snapshot(payload: Mapping[str, Any]) -> Any | None:
    """Return the value from a complete GMCP Char.Worn event."""
    if payload.get("type") != "equipment_changed":
        return None
    data = payload.get("data")
    if not isinstance(data, Mapping):
        return None
    if str(data.get("package", "")).casefold() != "char.worn":
        return None
    value = data.get("value", [])
    if isinstance(value, str):
        try:
            return json.loads(_ANSI_ESCAPE.sub("", value))
        except json.JSONDecodeError:
            return None
    return value


def _structured_worn_descriptions(value: Any) -> list[str]:
    """Extract occupied-slot descriptions from a structured worn snapshot."""
    if isinstance(value, list):
        descriptions: list[str] = []
        for item in value:
            descriptions.extend(_structured_worn_descriptions(item))
        return descriptions
    if not isinstance(value, Mapping):
        return []
    if "slot" in value or "wear_loc" in value:
        description = value.get("name", value.get("short_desc"))
        if description is None:
            return []
        cleaned = _ANSI_ESCAPE.sub("", str(description)).strip()
        return [_strip_live_selector(cleaned)] if cleaned else []
    descriptions = []
    for item in value.values():
        if isinstance(item, (list, Mapping)):
            descriptions.extend(_structured_worn_descriptions(item))
    return descriptions


def _replay_run_equipment(
    storage: RunStorage,
    run_id: int,
) -> _RunEquipmentReplay:
    """Replay authoritative worn snapshots plus later confirmed slot changes."""
    result = _RunEquipmentReplay()
    weapon_description: str | None = None
    structured_current = False
    awaiting_audit = False

    def set_weapon(present: bool, description: str | None) -> None:
        nonlocal weapon_description
        cleaned = (
            _strip_live_selector(description)
            if description is not None
            else None
        )
        if result.worn_descriptions is not None and weapon_description is not None:
            result.worn_descriptions = [
                item
                for item in result.worn_descriptions
                if item != weapon_description
            ]
        weapon_description = cleaned if present else None
        result.primary_weapon = (bool(present and cleaned), weapon_description)
        if result.worn_descriptions is not None and weapon_description is not None:
            result.worn_descriptions.append(weapon_description)
        if result.empty_categories is not None:
            if weapon_description is not None:
                result.empty_categories.discard("wield")
            else:
                result.empty_categories.add("wield")

    for event in storage.list_events(run_id):
        payload = json.loads(event["payload_json"])
        kind = event["kind"]
        if kind == "command":
            command = str(payload.get("command", "")).strip().casefold()
            if command in {"equipment", "eq all"}:
                awaiting_audit = True
            if command == "wear all" or command.startswith(
                ("wear ", "remove ", "wield ", "hold ")
            ):
                structured_current = False
            continue
        if kind == "game_event":
            snapshot = _complete_worn_snapshot(payload)
            if snapshot is None:
                continue
            result.worn_descriptions = _structured_worn_descriptions(snapshot)
            weapon_seen, structured_description = _equipment_weapon_from_payload(
                snapshot
            )
            weapon_description = (
                _strip_live_selector(structured_description)
                if weapon_seen and structured_description is not None
                else None
            )
            result.primary_weapon = (
                weapon_description is not None,
                weapon_description,
            )
            if result.empty_categories is not None:
                if weapon_description is None:
                    result.empty_categories.add("wield")
                else:
                    result.empty_categories.discard("wield")
            structured_current = True
            continue
        if kind != "response":
            continue

        response = str(payload.get("text", ""))
        if awaiting_audit and _equipment_audit_present(response):
            empty_categories = _equipment_empty_categories(response)
            if structured_current:
                if result.primary_weapon and result.primary_weapon[1] is not None:
                    empty_categories.discard("wield")
                else:
                    empty_categories.add("wield")
            else:
                result.worn_descriptions = [
                    _strip_live_selector(description)
                    for description in _equipment_audit_descriptions(response)
                ]
                weapon_seen, audited_description = _equipment_weapon_slot(response)
                weapon_description = (
                    _strip_live_selector(audited_description)
                    if weapon_seen and audited_description is not None
                    else None
                )
                result.primary_weapon = (
                    weapon_description is not None,
                    weapon_description,
                )
            result.empty_categories = empty_categories
            awaiting_audit = False

        acknowledgement = _direct_weapon_slot_acknowledgement(response)
        if acknowledgement is not None:
            structured_current = False
            set_weapon(acknowledgement[0], acknowledgement[1])
        folded = _ANSI_ESCAPE.sub("", response).casefold()
        if (
            "disarms you" in folded
            or "your weapon slips from your hand" in folded
        ):
            structured_current = False
            set_weapon(False, None)
    return result


def _run_equipment_empty_categories(
    storage: RunStorage,
    run_id: int,
) -> set[str] | None:
    """Return the newest empty categories from structured and text evidence."""
    return _replay_run_equipment(storage, run_id).empty_categories


def _run_worn_equipment_descriptions(
    storage: RunStorage,
    run_id: int,
) -> list[str] | None:
    """Return occupied equipment from structured and text evidence."""
    return _replay_run_equipment(storage, run_id).worn_descriptions


def _direct_weapon_slot_acknowledgement(
    response: str,
) -> tuple[bool, str | None] | None:
    """Extract a direct wield or stop-using acknowledgement from game text."""
    wielded = re.search(
        r"(?im)^\s*you wield\s+(?P<item>.+?)(?:[.!]\s*$|\s*$)",
        response,
    )
    if wielded is not None:
        return True, wielded.group("item").strip()
    if re.search(r"(?im)^\s*you stop using\s+", response):
        return False, None
    return None


_LIVE_SELECTOR_PREFIX = re.compile(r"^\s*\[#\d+\]\s*")


def _strip_live_selector(description: str) -> str:
    """Remove a connection-scoped TARGETMODE selector before persistence."""
    return _LIVE_SELECTOR_PREFIX.sub("", description).strip()


def _run_primary_weapon_slot(
    storage: RunStorage,
    run_id: int,
) -> tuple[bool, str | None] | None:
    """Return the newest observed primary weapon state, if one was recorded."""
    return _replay_run_equipment(storage, run_id).primary_weapon


def _research_absence_retry_group(policy_id: str) -> frozenset[str]:
    """Return the probe/hunt identities that share one reset target."""
    if policy_id in _MORIA_SANCTUARY_RESEARCH_POLICY_IDS:
        return _MORIA_SANCTUARY_RESEARCH_POLICY_IDS
    if policy_id in {
        _NOBLEMAN_LEVEL_SEVENTEEN_HUNT_POLICY_ID,
        _NOBLEMAN_LEVEL_SEVENTEEN_PROBE_POLICY_ID,
    }:
        return frozenset(
            {
                policy_id,
                _NOBLEMAN_LEVEL_SEVENTEEN_HUNT_POLICY_ID,
                _NOBLEMAN_LEVEL_SEVENTEEN_PROBE_POLICY_ID,
            }
        )
    if policy_id in {_SOLACE_MAGNUS_POLICY_ID, _SOLACE_MAGNUS_HUNT_POLICY_ID}:
        return frozenset({_SOLACE_MAGNUS_POLICY_ID, _SOLACE_MAGNUS_HUNT_POLICY_ID})
    return frozenset({policy_id})


def _research_retryable_failure_group(policy_id: str) -> frozenset[str]:
    """Return paired identities only for previously productive hunt retries."""
    for group in (
        frozenset(
            {
                "mirror-realm-watchman-probe-19-20",
                "mirror-realm-watchman-hunt-19-20",
            }
        ),
        frozenset(
            {
                "crystalmir-white-stag-probe-16-20",
                "crystalmir-white-stag-hunt-16-20",
            }
        ),
        frozenset(
            {
                "shadow-keep-undead-soldier-probe-16-20",
                "shadow-keep-undead-soldier-hunt-16-20",
            }
        ),
        frozenset(
            {
                "galaxy-white-dwarf-probe-17-20",
                "galaxy-white-dwarf-hunt-17-20",
            }
        ),
        frozenset(
            {
                "galaxy-white-dwarf-secondary-probe-17-20",
                "galaxy-white-dwarf-secondary-hunt-17-20",
            }
        ),
        frozenset(
            {
                "galaxy-red-supergiant-probe-17-20",
                "galaxy-red-supergiant-hunt-17-20",
            }
        ),
        frozenset(
            {
                "galaxy-horsehead-nebula-probe-18-20",
                "galaxy-horsehead-nebula-hunt-18-20",
            }
        ),
        frozenset(
            {
                _HIGHTOWER_JAILOR_POLICY_ID,
                _HIGHTOWER_JAILOR_HUNT_POLICY_ID,
            }
        ),
        frozenset(
            {
                _SHIRE_DWARVEN_PRINCE_POLICY_ID,
                _SHIRE_DWARVEN_PRINCE_HUNT_POLICY_ID,
            }
        ),
        frozenset(
            {
                "shire-dwarven-prince-thief-probe-19-20",
                "shire-dwarven-prince-thief-hunt-19-20",
            }
        ),
        frozenset({_SHIRE_THAIN_POLICY_ID, _SHIRE_THAIN_HUNT_POLICY_ID}),
        frozenset(
            {
                _SHIRE_ELVEN_WIZARD_POLICY_ID,
                _SHIRE_ELVEN_WIZARD_HUNT_POLICY_ID,
            }
        ),
        frozenset(
            {
                _PYRAMID_ALI_BABA_POLICY_ID,
                _PYRAMID_ALI_BABA_HUNT_POLICY_ID,
            }
        ),
        frozenset(
            {
                _SOLACE_LORD_DOOM_POLICY_ID,
                _SOLACE_LORD_DOOM_HUNT_POLICY_ID,
            }
        ),
        frozenset(
            {
                _ARGENT_BANDIT_LEADER_POLICY_ID,
                "argent-bandit-leader-hunt-17-20",
            }
        ),
        frozenset(
            {
                _ARGENT_BANDIT_LEADER_LEVEL_NINETEEN_POLICY_ID,
                _ARGENT_BANDIT_LEADER_LEVEL_NINETEEN_HUNT_POLICY_ID,
            }
        ),
        frozenset(
            {
                _HIGHLAND_KEEPER_POLICY_ID,
                _HIGHLAND_KEEPER_HUNT_POLICY_ID,
            }
        ),
    ):
        if policy_id in group:
            return group
    return frozenset({policy_id})


def _next_absent_research_retry_policy(
    state: dict[str, Any],
    *,
    current_group: frozenset[str],
    current_policy_id: str,
    only_expired: bool = True,
) -> str:
    """Rotate to another absent target after retrying the current one.

    A reset wait is a chance to inspect a different registered target as well
    as the one that just expired.  Keeping the cooldown map intact prevents a
    depleted route from being reopened on every campaign invocation.
    """
    results = _campaign_research_results(state)
    boot_id = state.get("world_boot_id")
    cooldowns = state.get(_RESEARCH_ABSENCE_COOLDOWN_KEY) or {}
    candidates: list[tuple[int, str]] = []
    for policy_id, remaining_value in cooldowns.items():
        candidate_id = str(policy_id)
        if candidate_id in current_group:
            continue
        try:
            remaining = int(remaining_value)
        except (TypeError, ValueError):
            continue
        result = results.get(candidate_id)
        cooldown_ready = remaining <= 0 if only_expired else remaining > 0
        if (
            cooldown_ready
            and isinstance(result, dict)
            and result.get("absent") is True
            and result.get("boot_id") == boot_id
        ):
            candidates.append((remaining, candidate_id))
    if not candidates:
        return current_policy_id
    return min(candidates)[1]


def _next_pending_absent_research_retry_policy(
    state: dict[str, Any],
    *,
    maximum_remaining: int = 1,
) -> str | None:
    """Find a current-reboot absence retry that is one step from reopening."""
    results = _campaign_research_results(state)
    boot_id = state.get("world_boot_id")
    cooldowns = state.get(_RESEARCH_ABSENCE_COOLDOWN_KEY) or {}
    candidates: list[tuple[int, str]] = []
    for raw_policy_id, raw_remaining in cooldowns.items():
        policy_id = str(raw_policy_id)
        if not _is_research_absence_retry_policy(policy_id):
            continue
        result = results.get(policy_id)
        if not (
            isinstance(result, dict)
            and result.get("boot_id") == boot_id
        ):
            continue
        route_hazard = result.get("route_hazard")
        retryable_route_hazard = (
            route_hazard == _DYNAMIC_FIELD_ROUTE_HAZARD_ABORT_REASON
            or (
                policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX)
                and _is_retryable_source_ranked_route_hazard(
                    policy_id,
                    route_hazard,
                )
            )
        )
        if not (
            (result.get("absent") is True and not route_hazard)
            or retryable_route_hazard
        ):
            continue
        try:
            remaining = int(raw_remaining)
        except (TypeError, ValueError):
            continue
        if 0 < remaining <= maximum_remaining:
            candidates.append((remaining, policy_id))
    return min(candidates)[1] if candidates else None


def _retry_current_absent_research_policy(
    state: dict[str, Any],
    *,
    productive_only: bool = False,
) -> dict[str, Any]:
    """Re-open the next target whose bounded reset wait has just expired."""
    policy_id = str(state.get("campaign_last_policy") or "")
    if _source_ranked_retry_exclusion(state) == policy_id:
        # This source route already received its explicit reset retry. Let
        # the generic frontier choose another candidate on the next pass.
        return state
    if not _is_research_absence_retry_policy(policy_id):
        return state
    result = _campaign_research_results(state).get(policy_id)
    if not (
        isinstance(result, dict)
        and (
            result.get("absent")
            or (
                policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX)
                and result.get("route_hazard")
            )
        )
        and result.get("boot_id") == state.get("world_boot_id")
    ):
        return state
    retried = dict(state)
    retried.pop(_POLICY_HANDOFF_KEY, None)
    current_group = _research_absence_retry_group(policy_id)
    results = dict(_campaign_research_results(state))
    protection_recovery_blocks_handoff = (
        _protection_recovery_required(state)
        and not _state_has_sanctuary_reserve(state)
    )
    productive_policy_id = state.get(_LAST_PRODUCTIVE_POLICY_KEY)
    productive_result = (
        results.get(productive_policy_id)
        if isinstance(productive_policy_id, str)
        else None
    )
    productive_handoff = bool(
        isinstance(productive_policy_id, str)
        and productive_policy_id not in current_group
        and isinstance(productive_result, dict)
        and productive_result.get("boot_id") == state.get("world_boot_id")
        and productive_result.get("observed") is True
        and productive_result.get("viable") is True
        and productive_result.get("completed_kill") is True
        and not protection_recovery_blocks_handoff
    )
    historical_handoff = (
        None
        if productive_handoff or protection_recovery_blocks_handoff
        else _historical_productive_handoff_policy_id(
            state,
            current_group=current_group,
        )
    )
    handoff_policy_id = (
        productive_policy_id
        if productive_handoff
        else historical_handoff
    )
    if productive_only and handoff_policy_id is None:
        return state
    if handoff_policy_id is not None:
        selected_policy_id = handoff_policy_id
        retry_policy_ids = ()
        retried[_POLICY_HANDOFF_KEY] = selected_policy_id
    else:
        cooldowns = state.get(_RESEARCH_ABSENCE_COOLDOWN_KEY) or {}
        current_cooldown = 0
        for candidate_id in current_group:
            try:
                current_cooldown = max(
                    current_cooldown,
                    int(cooldowns.get(candidate_id) or 0),
                )
            except (TypeError, ValueError):
                continue
        selected_policy_id = _next_absent_research_retry_policy(
            state,
            current_group=current_group,
            current_policy_id=policy_id,
        )
        if (
            selected_policy_id == policy_id
            and current_cooldown > 0
        ):
            return state
        retry_policy_ids = _research_absence_retry_group(selected_policy_id)
    for candidate_id in retry_policy_ids:
        results.pop(candidate_id, None)
    if results:
        retried["campaign_research_results"] = results
    else:
        retried.pop("campaign_research_results", None)
    cooldowns = dict(state.get(_RESEARCH_ABSENCE_COOLDOWN_KEY) or {})
    for candidate_id in retry_policy_ids:
        cooldowns.pop(candidate_id, None)
    if cooldowns:
        retried[_RESEARCH_ABSENCE_COOLDOWN_KEY] = cooldowns
    else:
        retried.pop(_RESEARCH_ABSENCE_COOLDOWN_KEY, None)
    if retry_policy_ids:
        cleared_research_policies = {
            str(candidate_id)
            for candidate_id in state.get(_CLEARED_RESEARCH_POLICIES_KEY, ())
        }
        cleared_research_policies.update(retry_policy_ids)
        retried[_CLEARED_RESEARCH_POLICIES_KEY] = sorted(
            cleared_research_policies
        )
    retried["campaign_fastwalk_target_absent"] = False
    retried["campaign_fastwalk_crowded"] = False
    retried.pop("campaign_fastwalk_abort_reason", None)
    retried["campaign_last_policy"] = selected_policy_id
    return retried


def _retry_any_pending_absent_research_policy(state: dict[str, Any]) -> dict[str, Any]:
    """Reopen a nearly-expired absence route after the frontier is exhausted."""
    policy_id = _next_pending_absent_research_retry_policy(state)
    if policy_id is None:
        return state
    retry_policy_ids = _research_absence_retry_group(policy_id)
    retried = dict(state)
    results = dict(_campaign_research_results(state))
    for candidate_id in retry_policy_ids:
        results.pop(candidate_id, None)
    if results:
        retried["campaign_research_results"] = results
    else:
        retried.pop("campaign_research_results", None)
    cooldowns = dict(state.get(_RESEARCH_ABSENCE_COOLDOWN_KEY) or {})
    for candidate_id in retry_policy_ids:
        cooldowns.pop(candidate_id, None)
    if cooldowns:
        retried[_RESEARCH_ABSENCE_COOLDOWN_KEY] = cooldowns
    else:
        retried.pop(_RESEARCH_ABSENCE_COOLDOWN_KEY, None)
    cleared_research_policies = {
        str(candidate_id)
        for candidate_id in state.get(_CLEARED_RESEARCH_POLICIES_KEY, ())
    }
    cleared_research_policies.update(retry_policy_ids)
    retried[_CLEARED_RESEARCH_POLICIES_KEY] = sorted(
        cleared_research_policies
    )
    retried["campaign_fastwalk_target_absent"] = False
    retried.pop("campaign_fastwalk_abort_reason", None)
    retried["campaign_last_policy"] = policy_id
    return retried


def _retry_required_sanctuary_research_policy(
    state: dict[str, Any],
) -> dict[str, Any]:
    """Reopen an absent sanctuary carrier after the bounded reset wait."""
    policy_id = _MORIA_SANCTUARY_THIEF_LEVEL_SEVENTEEN_POLICY_ID
    moria_policy_ids = _MORIA_SANCTUARY_RESEARCH_POLICY_IDS
    generic_policy_ids = frozenset(
        {
            _SOURCE_RANKED_SANCTUARY_RECOVERY_POLICY.policy_id,
            _SOURCE_RANKED_SANCTUARY_RESERVE_POLICY.policy_id,
        }
    )
    sanctuary_policy_ids = moria_policy_ids | generic_policy_ids
    results = _campaign_research_results(state)
    cooldowns = state.get(_RESEARCH_ABSENCE_COOLDOWN_KEY) or {}
    cooldown_active = isinstance(cooldowns, dict) and any(
        int(cooldowns.get(candidate_id) or 0) > 0
        for candidate_id in sanctuary_policy_ids
    )
    deferred_policy_ids = {
        candidate_id
        for candidate_id in sanctuary_policy_ids
        if isinstance(results.get(candidate_id), dict)
        and (
            results[candidate_id].get("absent") is True
            or results[candidate_id].get("retryable_failure") is True
        )
        and results[candidate_id].get("boot_id") == state.get("world_boot_id")
    }
    if generic_policy_ids.intersection(deferred_policy_ids):
        retry_policy_ids = generic_policy_ids.intersection(deferred_policy_ids)
        reopened_policy_id = (
            _SOURCE_RANKED_SANCTUARY_RECOVERY_POLICY.policy_id
            if _SOURCE_RANKED_SANCTUARY_RECOVERY_POLICY.policy_id
            in retry_policy_ids
            else _SOURCE_RANKED_SANCTUARY_RESERVE_POLICY.policy_id
        )
    else:
        retry_policy_ids = moria_policy_ids
        reopened_policy_id = policy_id
    sanctuary_target_deferred = any(
        isinstance(results.get(candidate_id), dict)
        and (
            results[candidate_id].get("absent") is True
            or results[candidate_id].get("retryable_failure") is True
        )
        and results[candidate_id].get("boot_id") == state.get("world_boot_id")
        for candidate_id in retry_policy_ids
    )
    if not (
        cooldown_active
        and sanctuary_target_deferred
        and _campaign_sanctuary_recovery_required(state)
    ):
        return state
    retried = dict(state)
    results = dict(results)
    for candidate_id in retry_policy_ids:
        results.pop(candidate_id, None)
    if results:
        retried["campaign_research_results"] = results
    else:
        retried.pop("campaign_research_results", None)
    remaining_cooldowns = dict(cooldowns)
    for candidate_id in retry_policy_ids:
        remaining_cooldowns.pop(candidate_id, None)
    if remaining_cooldowns:
        retried[_RESEARCH_ABSENCE_COOLDOWN_KEY] = remaining_cooldowns
    else:
        retried.pop(_RESEARCH_ABSENCE_COOLDOWN_KEY, None)
    cleared = {
        str(candidate_id)
        for candidate_id in state.get(_CLEARED_RESEARCH_POLICIES_KEY, ())
    }
    cleared.update(retry_policy_ids)
    retried[_CLEARED_RESEARCH_POLICIES_KEY] = sorted(cleared)
    retried["campaign_fastwalk_target_absent"] = False
    retried.pop("campaign_fastwalk_abort_reason", None)
    retried["campaign_last_policy"] = reopened_policy_id
    return retried


def _active_crowded_research_policy_id(
    state: dict[str, Any],
    *,
    exclude_policy_id: str | None = None,
) -> str | None:
    """Prefer a current-band field recheck over unrelated maintenance crowds."""
    results = _campaign_research_results(state)
    cooldowns = state.get(_RESEARCH_CROWD_COOLDOWN_KEY) or {}
    try:
        character_level = int(state.get("level"))
    except (TypeError, ValueError):
        character_level = None
    candidates: list[tuple[bool, int, str]] = []
    for policy_id, result in results.items():
        policy_id = str(policy_id)
        if (
            policy_id == exclude_policy_id
            or not isinstance(result, dict)
            or result.get("crowded") is not True
            or result.get("crowd_exhausted") is True
            or result.get("boot_id") != state.get("world_boot_id")
        ):
            continue
        if character_level is not None and policy_id.startswith(
            _SOURCE_RANKED_POLICY_PREFIX
        ):
            level_match = re.search(r"-(\d+)$", policy_id)
            if (
                level_match is not None
                and int(level_match.group(1)) != character_level
            ):
                # Source-ranked policy ids end with the character level. A
                # prior-band crowd must not block a fresh current-band route.
                continue
        try:
            remaining = int(cooldowns.get(policy_id) or 0)
        except (TypeError, ValueError):
            continue
        if remaining > 0:
            candidates.append((
                not policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX),
                remaining,
                policy_id,
            ))
    if not candidates:
        return None
    return min(candidates)[2]


def _crowd_policy_has_active_wait(
    state: Mapping[str, Any],
    policy_id: str,
) -> bool:
    """Return whether one current-reboot crowd still has a reset wait."""
    if not policy_id:
        return False
    result = _campaign_research_results(state).get(policy_id)
    if not (
        isinstance(result, Mapping)
        and result.get("boot_id") == state.get("world_boot_id")
        and result.get("crowded") is True
        and result.get("crowd_exhausted") is not True
    ):
        return False
    cooldowns = state.get(_RESEARCH_CROWD_COOLDOWN_KEY) or {}
    try:
        return int(cooldowns.get(policy_id) or 0) > 0
    except (AttributeError, TypeError, ValueError):
        return False


def _source_ranked_crowd_policy_exhausted(
    state: Mapping[str, Any],
    policy_id: str,
) -> bool:
    """Return whether a current-reboot source crowd is already exhausted."""
    if not policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX):
        return False
    if _source_ranked_crowd_attempts_exhausted(state, policy_id):
        return True
    result = _campaign_research_results(state).get(policy_id)
    return (
        isinstance(result, Mapping)
        and result.get("boot_id") == state.get("world_boot_id")
        and result.get("crowd_exhausted") is True
    )


def _active_source_ranked_reset_policy_id(
    state: dict[str, Any],
) -> str | None:
    """Return a source route that is waiting on current-reboot evidence."""
    results = _campaign_research_results(state)
    boot_id = state.get("world_boot_id")
    excluded_policy_id = _source_ranked_retry_exclusion(state)
    try:
        character_level = int(state.get("level"))
    except (TypeError, ValueError):
        character_level = None
    candidates: list[tuple[int, str]] = []
    for cooldown_key in (
        _RESEARCH_ABSENCE_COOLDOWN_KEY,
        _RESEARCH_CROWD_COOLDOWN_KEY,
    ):
        cooldowns = state.get(cooldown_key) or {}
        for raw_policy_id, raw_remaining in cooldowns.items():
            policy_id = str(raw_policy_id)
            if (
                not policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX)
                or policy_id == excluded_policy_id
            ):
                continue
            if character_level is not None:
                level_match = re.search(r"-(\d+)$", policy_id)
                if level_match is not None and int(level_match.group(1)) != character_level:
                    # Source-ranked candidate ids are generated per level.
                    # A stale cooldown from an earlier band must not make a
                    # current-level frontier appear unavailable.
                    continue
            result = results.get(policy_id)
            if not (
                isinstance(result, dict)
                and result.get("boot_id") == boot_id
                and result.get("crowd_exhausted") is not True
                and (
                    result.get("absent") is True
                    or result.get("crowded") is True
                    or result.get("crowd_exhausted") is True
                    or result.get("retryable_failure") is True
                    or result.get("route_hazard")
                )
            ):
                continue
            try:
                remaining = int(raw_remaining)
            except (TypeError, ValueError):
                continue
            if remaining > 0:
                candidates.append((remaining, policy_id))
    return min(candidates)[1] if candidates else None


def _retry_any_crowded_research_policy(
    state: dict[str, Any],
    *,
    exclude_policy_id: str | None = None,
) -> dict[str, Any]:
    """Reopen one crowded route after its explicit reset wait."""
    policy_id = _active_crowded_research_policy_id(
        state,
        exclude_policy_id=exclude_policy_id,
    )
    if policy_id is None:
        return state
    retried = dict(state)
    results = dict(_campaign_research_results(state))
    results.pop(policy_id, None)
    if results:
        retried["campaign_research_results"] = results
    else:
        retried.pop("campaign_research_results", None)
    cooldowns = dict(state.get(_RESEARCH_CROWD_COOLDOWN_KEY) or {})
    cooldowns.pop(policy_id, None)
    if cooldowns:
        retried[_RESEARCH_CROWD_COOLDOWN_KEY] = cooldowns
    else:
        retried.pop(_RESEARCH_CROWD_COOLDOWN_KEY, None)
    cleared_research_policies = {
        str(candidate_id)
        for candidate_id in state.get(_CLEARED_RESEARCH_POLICIES_KEY, ())
    }
    cleared_research_policies.add(policy_id)
    retried[_CLEARED_RESEARCH_POLICIES_KEY] = sorted(
        cleared_research_policies
    )
    retried["campaign_fastwalk_target_absent"] = False
    retried["campaign_fastwalk_crowded"] = False
    retried.pop("campaign_fastwalk_abort_reason", None)
    retried["campaign_last_policy"] = policy_id
    return retried


def _retry_current_crowded_research_policy(state: dict[str, Any]) -> dict[str, Any]:
    """Rotate a crowded research checkpoint after its bounded wait."""
    policy_id = str(state.get("campaign_last_policy") or "")
    abort_reason = str(state.get("campaign_fastwalk_abort_reason") or "")
    current_result = _campaign_research_results(state).get(policy_id)
    if (
        policy_id.startswith(_SOURCE_RANKED_POLICY_PREFIX)
        and isinstance(current_result, dict)
        and current_result.get("crowd_exhausted") is True
    ):
        active_policy_id = _active_crowded_research_policy_id(
            state,
            exclude_policy_id=policy_id,
        )
        if active_policy_id and active_policy_id != policy_id:
            # Preserve this exhausted route's evidence, but use the explicit
            # reset retry to reopen a different active crowd route. Without
            # this handoff, the retry can clear no route and fall through to
            # an unavailable policy even though executable work remains.
            return _retry_any_crowded_research_policy(
                state,
                exclude_policy_id=policy_id,
            )
        # Keep the evidence and cooldown intact.  `_policy_for_state` will
        # exclude this candidate and select another source-safe current-band
        # route, while a later reboot can reconsider the original target.
        rotated = dict(state)
        rotated["campaign_fastwalk_target_absent"] = False
        rotated["campaign_fastwalk_crowded"] = False
        rotated.pop("campaign_fastwalk_abort_reason", None)
        rotated["campaign_last_policy"] = policy_id
        return rotated
    if (
        abort_reason == _DYNAMIC_FIELD_ROUTE_HAZARD_ABORT_REASON
        or _is_retryable_source_ranked_route_hazard(policy_id, abort_reason)
    ):
        result = _campaign_research_results(state).get(policy_id)
        cooldowns = state.get(_RESEARCH_ABSENCE_COOLDOWN_KEY) or {}
        if not (
            isinstance(result, dict)
            and result.get("route_hazard") == abort_reason
            and result.get("boot_id") == state.get("world_boot_id")
            and isinstance(cooldowns, dict)
            and int(cooldowns.get(policy_id) or 0) > 0
        ):
            return state
        retried = dict(state)
        results = dict(_campaign_research_results(state))
        results.pop(policy_id, None)
        if results:
            retried["campaign_research_results"] = results
        else:
            retried.pop("campaign_research_results", None)
        remaining_cooldowns = dict(cooldowns)
        remaining_cooldowns.pop(policy_id, None)
        if remaining_cooldowns:
            retried[_RESEARCH_ABSENCE_COOLDOWN_KEY] = remaining_cooldowns
        else:
            retried.pop(_RESEARCH_ABSENCE_COOLDOWN_KEY, None)
        cleared_research_policies = {
            str(candidate_id)
            for candidate_id in state.get(_CLEARED_RESEARCH_POLICIES_KEY, ())
        }
        cleared_research_policies.add(policy_id)
        retried[_CLEARED_RESEARCH_POLICIES_KEY] = sorted(
            cleared_research_policies
        )
        retried["campaign_fastwalk_target_absent"] = False
        retried["campaign_fastwalk_crowded"] = False
        retried.pop("campaign_fastwalk_abort_reason", None)
        retried["campaign_last_policy"] = policy_id
        return retried
    if not policy_id or not any(
        abort_reason.startswith(prefix) for prefix in _FIELD_CROWD_ABORT_PREFIXES
    ):
        return _retry_any_crowded_research_policy(state)
    retry_policy_id = _next_absent_research_retry_policy(
        state,
        current_group=_research_absence_retry_group(policy_id),
        current_policy_id=policy_id,
        only_expired=False,
    )
    if retry_policy_id == policy_id:
        return _retry_any_crowded_research_policy(state)
    retried = dict(state)
    # Crowd rotation selects one executable route.  Paired probe/hunt
    # identities share absence-reset state only in the dedicated reset path;
    # clearing the whole group here can erase an unrelated sanctuary probe.
    retry_policy_ids = (retry_policy_id,)
    results = dict(_campaign_research_results(state))
    for candidate_id in retry_policy_ids:
        results.pop(candidate_id, None)
    if results:
        retried["campaign_research_results"] = results
    else:
        retried.pop("campaign_research_results", None)
    cooldowns = dict(state.get(_RESEARCH_ABSENCE_COOLDOWN_KEY) or {})
    for candidate_id in retry_policy_ids:
        cooldowns.pop(candidate_id, None)
    if cooldowns:
        retried[_RESEARCH_ABSENCE_COOLDOWN_KEY] = cooldowns
    else:
        retried.pop(_RESEARCH_ABSENCE_COOLDOWN_KEY, None)
    cleared_research_policies = {
        str(candidate_id)
        for candidate_id in state.get(_CLEARED_RESEARCH_POLICIES_KEY, ())
    }
    cleared_research_policies.update(retry_policy_ids)
    retried[_CLEARED_RESEARCH_POLICIES_KEY] = sorted(
        cleared_research_policies
    )
    retried["campaign_fastwalk_target_absent"] = False
    retried["campaign_fastwalk_crowded"] = False
    retried.pop("campaign_fastwalk_abort_reason", None)
    retried["campaign_last_policy"] = retry_policy_id
    return retried


def _is_equipment_audit_response(response: str) -> bool:
    """Reject stale command pulses while reconstructing an equipment audit."""
    return "you are not using any equipment" in response or bool(
        re.search(r"(?:\[weapon\]|\[held\]|<[^>]*worn[^>]*>)", response)
    )


def _state_has_item(value: Any, item_name: str) -> bool:
    target = item_name.casefold()
    if isinstance(value, str):
        try:
            decoded = json.loads(_ANSI_ESCAPE.sub("", value))
        except json.JSONDecodeError:
            return target in value.casefold()
        return _state_has_item(decoded, item_name)
    if isinstance(value, dict):
        for key in ("short_desc", "name", "item"):
            description = value.get(key)
            if isinstance(description, str) and target in description.casefold():
                return True
        return any(_state_has_item(item, item_name) for item in value.values())
    if isinstance(value, (list, tuple)):
        return any(_state_has_item(item, item_name) for item in value)
    return False


def _state_item_count(value: Any, item_name: str) -> int:
    target = item_name.casefold()
    if isinstance(value, str):
        try:
            decoded = json.loads(_ANSI_ESCAPE.sub("", value))
        except json.JSONDecodeError:
            return int(target in value.casefold())
        return _state_item_count(decoded, item_name)
    if isinstance(value, dict):
        description = next(
            (
                value[key]
                for key in ("short_desc", "name", "item")
                if isinstance(value.get(key), str)
            ),
            None,
        )
        if description is not None and target in description.casefold():
            quantity = value.get("quan", 1)
            try:
                return max(1, int(quantity))
            except (TypeError, ValueError):
                return 1
        return sum(_state_item_count(item, item_name) for item in value.values())
    if isinstance(value, (list, tuple)):
        return sum(_state_item_count(item, item_name) for item in value)
    return 0


def _state_has_active_affect(value: Any, affect_name: str) -> bool:
    target = affect_name.casefold()
    if isinstance(value, str):
        try:
            decoded = json.loads(_ANSI_ESCAPE.sub("", value))
        except json.JSONDecodeError:
            return target in value.casefold()
        return _state_has_active_affect(decoded, affect_name)
    if isinstance(value, dict):
        name = value.get("name")
        if isinstance(name, str) and target == name.casefold():
            return True
        return any(
            _state_has_active_affect(item, affect_name)
            for item in value.values()
        )
    if isinstance(value, (list, tuple)):
        return any(_state_has_active_affect(item, affect_name) for item in value)
    return False


def _state_flight_duration(value: Any) -> int | None:
    """Return the longest observed duration for fly or levitation."""
    durations: list[int] = []

    def collect(item: Any) -> None:
        if isinstance(item, str):
            try:
                decoded = json.loads(_ANSI_ESCAPE.sub("", item))
            except json.JSONDecodeError:
                return
            collect(decoded)
            return
        if isinstance(item, dict):
            name = item.get("name")
            if isinstance(name, str) and name.casefold() in {
                "fly",
                "levitation",
            }:
                try:
                    durations.append(int(item.get("duration")))
                except (TypeError, ValueError):
                    pass
            for nested in item.values():
                collect(nested)
            return
        if isinstance(item, (list, tuple)):
            for nested in item:
                collect(nested)

    collect(value)
    return max(durations) if durations else None


def _state_copper_value(state: dict[str, Any]) -> int:
    currencies = state.get("currencies")
    source = currencies if isinstance(currencies, dict) else state

    def amount(name: str) -> int:
        value = source.get(name, 0)
        try:
            return max(0, int(value))
        except (TypeError, ValueError):
            return 0

    return (
        amount("platinum") * 1_000
        + amount("gold") * 100
        + amount("silver") * 10
        + amount("copper")
    )


def _flight_purchase_minimum(state: dict[str, Any]) -> int:
    """Return the current reboot's observed price, with a legacy floor."""
    observed = state.get(_MAGIC_SHOP_FLIGHT_PRICE_KEY)
    try:
        price = int(observed)
    except (TypeError, ValueError):
        price = 0
    if price <= 0:
        return 90
    current_boot = state.get("world_boot_id")
    price_boot = state.get(_MAGIC_SHOP_FLIGHT_PRICE_BOOT_KEY)
    if current_boot and price_boot != current_boot:
        return 90
    return max(90, price)


def _state_needs_coin_deposit(state: dict[str, Any]) -> bool:
    """Bank coins that either consume carry room or expose a thief route."""
    currencies = state.get("currencies")
    source = currencies if isinstance(currencies, dict) else state
    coin_count = 0
    for denomination in ("platinum", "gold", "silver", "copper"):
        try:
            coin_count += max(0, int(source.get(denomination, 0)))
        except (TypeError, ValueError):
            continue

    # DD4's spec_thief uses total_coins_char(), not the number of physical
    # coins. Keep a compact working reserve before a source-ranked thief
    # special can remove a meaningful fraction of a carried hoard.
    if (
        _state_copper_value(state) * 20 // 100
        > _SPEC_THIEF_MAX_EXPOSURE_COINS
    ):
        return True

    stats = state.get("stats")
    if not isinstance(stats, dict):
        return False
    carry_weight = stats.get("carry_wt")
    maximum_weight = stats.get("maxcarry_wt")
    if not isinstance(carry_weight, (int, float)):
        return False
    if not isinstance(maximum_weight, (int, float)) or maximum_weight <= 0:
        return False
    if maximum_weight - carry_weight >= 10:
        return False
    return coin_count >= 10


def _has_campaign_sellable_loot(
    state: dict[str, Any],
    *,
    gear_catalog: GearCatalog | None = None,
) -> bool:
    character_class = (
        state.get("character_class")
        if isinstance(state.get("character_class"), str)
        else None
    )
    subclass = (
        state.get("subclass")
        if isinstance(state.get("subclass"), str)
        else None
    )
    # A completed liquidation records the inventory that the sale planner
    # intentionally retained.  Weight pressure alone must not reopen that
    # same no-op maintenance pass; only a changed liquidation signature can
    # justify another shop visit.
    if _matches_liquidation_baseline(state, gear_catalog=gear_catalog):
        ambiguous_sellable = bool(
            gear_catalog is not None
            and any(
                len(gear_catalog.candidates(description)) > 1
                and _sellable_inventory_keyword(
                    [[{"short_desc": description}]],
                    gear_catalog,
                    worn_descriptions=state.get("campaign_worn_equipment"),
                    character_class=character_class,
                    subclass=subclass,
                )
                is not None
                for description in _inventory_descriptions(state.get("inventory"))
                if "water skin" not in description.casefold()
                and "pie" not in description.casefold()
            )
        )
        if not ambiguous_sellable:
            return False
    stats = state.get("stats")
    if gear_catalog is not None and isinstance(stats, dict):
        carry_items = stats.get("carry_num")
        maximum_items = stats.get("maxcarry_num")
        if (
            isinstance(carry_items, (int, float))
            and isinstance(maximum_items, (int, float))
            and carry_items >= maximum_items
            and any(
                item is not None and is_disposable_food(item)
                for description in _inventory_descriptions(state.get("inventory"))
                for item in (gear_catalog.match(description),)
            )
        ):
            return True
    keyword = _sellable_inventory_keyword(
        state.get("inventory"),
        gear_catalog,
        worn_descriptions=state.get("campaign_worn_equipment"),
        character_class=character_class,
        subclass=subclass,
    )
    if keyword is None:
        return False
    if keyword == "collar":
        carried_collars = _state_item_count(
            state.get("inventory"),
            "war dog collar",
        )
        worn_collars = sum(
            "war dog collar" in normalize_item_name(description)
            for description in state.get("campaign_worn_equipment") or ()
        )
        retained_carried_collars = max(0, 2 - worn_collars)
        if carried_collars <= retained_carried_collars:
            return False
        stats = state.get("stats")
        if not isinstance(stats, dict):
            return False
        carry_weight = stats.get("carry_wt")
        maximum_weight = stats.get("maxcarry_wt")
        if not isinstance(carry_weight, (int, float)):
            return False
        if not isinstance(maximum_weight, (int, float)) or maximum_weight <= 0:
            return False
        if carry_weight / maximum_weight < 0.85:
            return False
    if isinstance(stats, dict):
        carry_weight = stats.get("carry_wt")
        maximum_weight = stats.get("maxcarry_wt")
        if (
            isinstance(carry_weight, (int, float))
            and isinstance(maximum_weight, (int, float))
            and maximum_weight > 0
            and maximum_weight - carry_weight <= 10
        ):
            empty_categories = set(
                state.get("campaign_empty_equipment_categories") or ()
            )
            for description in _inventory_descriptions(state.get("inventory")):
                if _sellable_inventory_keyword(
                    [[{"short_desc": description}]],
                    gear_catalog,
                    worn_descriptions=state.get("campaign_worn_equipment"),
                    character_class=character_class,
                    subclass=subclass,
                ) is None:
                    continue
                item = gear_catalog.match(description) if gear_catalog else None
                if (
                    item is not None
                    and item_category(item) in empty_categories
                ):
                    continue
                return True
            return False
    # A failed purchase is not new loot. Once a liquidation checkpoint has
    # recorded the retained inventory, repeating the same no-op sale only
    # stalls the pending purchase retry; a changed signature will still
    # schedule one fresh liquidation pass.
    return not _matches_liquidation_baseline(state, gear_catalog=gear_catalog)


def _campaign_should_liquidate_loot(
    state: dict[str, Any],
    *,
    gear_catalog: GearCatalog | None = None,
    force: bool = False,
) -> bool:
    if not _has_campaign_sellable_loot(state, gear_catalog=gear_catalog):
        return False
    if (
        state.get(_MAGIC_SHOP_ROUTE_BLOCKED_KEY)
        and (
            int(state.get(_CITY_SHOP_ROUTE_COOLDOWN_KEY) or 0) > 0
            or int(state.get(_FLIGHT_PURCHASE_COOLDOWN_KEY) or 0) > 0
        )
    ):
        # A live locator has shown that every healer-origin city-shop route
        # is currently exposed to the wandering drunk. Let the next bounded
        # field segment do useful work before retrying the same crossing.
        return False
    if force:
        return True
    if state.get(_PROTECTION_RECOVERY_KEY):
        # A protected loss leaves the character needing a reserve before the
        # next field attempt.  Do not make a single redundant weapon wait for
        # three more kills before converting it into that reserve.
        return True
    if (
        len(_campaign_liquidation_signature(state, gear_catalog=gear_catalog))
        >= _CAMPAIGN_LIQUIDATION_BATCH_SIZE
    ):
        return True

    stats = state.get("stats")
    if not isinstance(stats, dict):
        return True
    observed_capacity = False
    for current_key, maximum_key in (
        ("carry_num", "maxcarry_num"),
        ("carry_wt", "maxcarry_wt"),
    ):
        current = stats.get(current_key)
        maximum = stats.get(maximum_key)
        if not isinstance(current, (int, float)):
            continue
        if not isinstance(maximum, (int, float)) or maximum <= 0:
            continue
        observed_capacity = True
        if current / maximum >= _CAMPAIGN_LIQUIDATION_CAPACITY_RATIO:
            return True
    return not observed_capacity


def _campaign_vault_stow_items(
    state: dict[str, Any],
    *,
    gear_catalog: GearCatalog | None,
    required_free_weight: int = 10,
) -> tuple[str, ...]:
    if gear_catalog is None:
        return ()
    stats = state.get("stats")
    if not isinstance(stats, dict):
        return ()
    carry_weight = stats.get("carry_wt")
    maximum_weight = stats.get("maxcarry_wt")
    if not isinstance(carry_weight, (int, float)):
        return ()
    if not isinstance(maximum_weight, (int, float)):
        return ()
    if maximum_weight - carry_weight >= required_free_weight:
        return ()

    keywords: list[str] = []
    selected_weight = 0
    capacity_candidates: list[tuple[int, str]] = []
    worn_counts = Counter(
        normalize_item_name(description)
        for description in state.get("campaign_worn_equipment") or ()
    )
    for description in _inventory_descriptions(state.get("inventory")):
        item = gear_catalog.match(description)
        if item is None:
            continue
        normalized_description = normalize_item_name(description)
        if worn_counts[normalized_description] > 0:
            worn_counts[normalized_description] -= 1
            continue
        candidates = gear_catalog.candidates(description)
        ambiguous_weapon = (
            item.item_type == 5
            and len(candidates) > 1
            and all(candidate.item_type == 5 for candidate in candidates)
        )
        plain_armour = item.item_type == 9 and not protects_from_sale(item)
        protected_spare = (
            protects_from_sale(item)
            and not is_capacity_infrastructure(item)
            and item_category(item) not in {"light", "wield"}
        )
        keyword = item_keyword(item)
        normalized_name = normalize_item_name(item.short_description)
        if is_capacity_infrastructure(item):
            if "large sack" in normalized_name:
                keyword = "sack"
            elif "backpack" in normalized_name:
                keyword = "backpack"
            elif "girdle of many pouches" in normalized_name:
                keyword = "girdle"
        if not keyword:
            continue
        if is_capacity_infrastructure(item):
            capacity_candidates.append((item.weight, keyword))
            continue
        if ambiguous_weapon or plain_armour or protected_spare:
            selected_weight += item.weight
        else:
            continue
        if keyword not in keywords:
            keywords.append(keyword)

    free_weight = maximum_weight - carry_weight
    for weight, keyword in sorted(capacity_candidates, reverse=True):
        if free_weight + selected_weight >= required_free_weight:
            break
        if keyword not in keywords:
            keywords.append(keyword)
            selected_weight += weight
    if free_weight + selected_weight < required_free_weight:
        return ()
    return tuple(keywords)


def _has_oversized_capacity_stow_item(
    state: dict[str, Any],
    *,
    gear_catalog: GearCatalog | None,
    stow_items: tuple[str, ...],
) -> bool:
    if gear_catalog is None or not stow_items:
        return False
    stats = state.get("stats")
    maximum_weight = stats.get("maxcarry_wt") if isinstance(stats, dict) else None
    if not isinstance(maximum_weight, (int, float)) or maximum_weight <= 0:
        return False
    stow_keywords = {keyword.casefold() for keyword in stow_items}
    for description in _inventory_descriptions(state.get("inventory")):
        item = gear_catalog.match(description)
        if item is None or not is_capacity_infrastructure(item):
            continue
        if not stow_keywords.intersection(item.keywords.casefold().split()):
            continue
        if item.weight >= max(20, maximum_weight * 0.2):
            return True
    return False


def _has_campaign_free_weight(
    state: dict[str, Any],
    required_free_weight: int,
) -> bool:
    stats = state.get("stats")
    if not isinstance(stats, dict):
        return True
    carry_weight = stats.get("carry_wt")
    maximum_weight = stats.get("maxcarry_wt")
    if not isinstance(carry_weight, (int, float)):
        return True
    if not isinstance(maximum_weight, (int, float)):
        return True
    return maximum_weight - carry_weight >= required_free_weight


def _campaign_liquidation_signature(
    state: dict[str, Any],
    *,
    gear_catalog: GearCatalog | None = None,
) -> tuple[str, ...]:
    descriptions = _inventory_descriptions(state.get("inventory"))
    worn_descriptions = state.get("campaign_worn_equipment")
    character_class = (
        state.get("character_class")
        if isinstance(state.get("character_class"), str)
        else None
    )
    subclass = (
        state.get("subclass")
        if isinstance(state.get("subclass"), str)
        else None
    )
    protected_seen: Counter[str] = Counter()
    candidates: list[str] = []
    for description in descriptions:
        normalized = normalize_item_name(description)
        item = gear_catalog.match(description) if gear_catalog is not None else None
        if (
            item is not None
            and protects_from_sale(item)
            and not any(
                location == 1 and modifier < 0
                for location, modifier in item.affects
            )
            and _sellable_inventory_keyword(
                [[{"short_desc": description}]],
                gear_catalog,
                worn_descriptions=worn_descriptions,
                character_class=character_class,
                subclass=subclass,
            ) is None
        ):
            protected_seen[normalized] += 1
            retained_capacity = {
                "finger": 2,
                "neck": 2,
                "wrist": 2,
            }.get(item_category(item) or "", 1)
            if protected_seen[normalized] <= retained_capacity:
                continue
        elif (
            _sellable_inventory_keyword(
                [[{"short_desc": description}]],
                gear_catalog,
                worn_descriptions=worn_descriptions,
                character_class=character_class,
                subclass=subclass,
            )
            is None
        ):
            continue
        candidates.append(normalized)
    return tuple(sorted(candidates))


def _matches_liquidation_baseline(
    state: dict[str, Any],
    *,
    gear_catalog: GearCatalog | None = None,
) -> bool:
    baseline = state.get(_LIQUIDATION_BASELINE_KEY)
    if not isinstance(baseline, (list, tuple)) or not all(
        isinstance(item, str) for item in baseline
    ):
        return False
    return _campaign_liquidation_signature(
        state,
        gear_catalog=gear_catalog,
    ) == tuple(sorted(normalize_item_name(item) for item in baseline))


def _repair_noop_liquidation_baseline(
    storage: RunStorage,
    campaign_id: int,
    state: dict[str, Any],
    *,
    gear_catalog: GearCatalog | None = None,
) -> dict[str, Any]:
    """Remove a baseline written by a liquidation segment that sold nothing.

    A bounded liquidation segment can spend its entire runtime returning a
    character to the healer. That is a resumable interruption, not proof that
    the unchanged inventory was intentionally retained.
    """
    baseline = state.get(_LIQUIDATION_BASELINE_KEY)
    if not isinstance(baseline, (list, tuple)):
        return dict(state)
    baseline_signature = tuple(
        sorted(normalize_item_name(item) for item in baseline if isinstance(item, str))
    )
    for segment in reversed(_runtime_campaign_segments(storage, campaign_id)):
        if str(segment["phase"] or "") != "liquidate-loot":
            continue
        if segment["run_id"] is None:
            continue
        try:
            start_state = json.loads(segment["start_state_json"] or "{}")
            end_state = json.loads(segment["end_state_json"] or "{}")
        except (TypeError, json.JSONDecodeError):
            continue
        if not isinstance(start_state, dict) or not isinstance(end_state, dict):
            continue
        start_baseline = start_state.get(_LIQUIDATION_BASELINE_KEY)
        if isinstance(start_baseline, (list, tuple)) and start_baseline:
            continue
        if storage.list_loot_sales_for_run(int(segment["run_id"])):
            continue
        start_signature = _campaign_liquidation_signature(
            start_state,
            gear_catalog=gear_catalog,
        )
        end_signature = _campaign_liquidation_signature(
            end_state,
            gear_catalog=gear_catalog,
        )
        if start_signature != end_signature or baseline_signature != end_signature:
            continue
        repaired = dict(state)
        repaired.pop(_LIQUIDATION_BASELINE_KEY, None)
        return repaired
    return dict(state)


def _budget_failure(spec: CampaignSpec, totals: Any) -> str | None:
    if int(totals["segment_count"]) >= spec.max_segments:
        return f"Campaign exceeded its {spec.max_segments} segment budget."
    if int(totals["command_count"]) >= spec.max_total_commands:
        return f"Campaign exceeded its {spec.max_total_commands} command budget."
    if float(totals["duration_seconds"]) >= spec.max_total_runtime:
        return f"Campaign exceeded its {spec.max_total_runtime:g} second runtime budget."
    return None


def _stalled_count(
    before: dict[str, Any],
    after: dict[str, Any],
    checkpoint: Any,
) -> int:
    previous = _checkpoint_state(checkpoint)
    previous_stalled = int(previous.get("campaign_stalled_segments", 0))
    if previous.get("campaign_policy_revision") != before.get(
        "campaign_policy_revision"
    ):
        previous_stalled = 0
    if _level(after) > _level(before):
        return 0
    before_xp = before.get("xp")
    after_xp = after.get("xp")
    if isinstance(before_xp, (int, float)) and isinstance(after_xp, (int, float)):
        if after_xp > before_xp:
            return 0
    if not before and _level(after) > 0:
        return 0
    return previous_stalled + 1


def _run_duration(run: Any) -> float:
    if run is None or not run["finished_at"]:
        return 0.0
    try:
        elapsed = datetime.fromisoformat(run["finished_at"]) - datetime.fromisoformat(
            run["started_at"]
        )
    except ValueError:
        return 0.0
    return max(0.0, elapsed.total_seconds())
